var cp_head1 = global.get("cp_state_head1");
var cp_head2 = global.get("cp_state_head2");

var v1 = global.get("pm.measured_voltage")  || 0;
var i1 = global.get("pm.measured_current")  || 0;
var v2 = global.get("pm.measured_voltage2") || 0;
var i2 = global.get("pm.measured_current2") || 0;

// ===== FIX 16 ก.ค.: จัดสรรโมดูลต้องอิงคอนแทกเตอร์เชื่อมบัสจริง =====
// ground truth = "function 4" -> DC bypass (R6 / d_out/7)
//   ปิด  = บัส G1+G2 ขนานกัน -> โมดูลทุกกลุ่มไปช่วยหัวเดียวกันได้ (แบ่งตามสัดส่วนโมดูล)
//   เปิด = บัสแยกขาด        -> G1 ผูกหัว 1, G2 ผูกหัว 2 ตายตัว
// สูตร tie_closed ต้องเหมือน function 4 ทุกตัวอักษร ห้ามแก้ข้างเดียว
// (เดิมใช้แค่ b/c/d: อีกหัวตกไป state_e/state_f จะถูกนับว่า "ว่าง" -> หารกระแสไปอีกกลุ่ม
//  ทั้งที่บัสยังแยก -> ไฟไปไม่ถึงรถ และประกาศกำลังเกินที่จ่ายได้จริง)
var live1 = (cp_head1 === "state_b" || cp_head1 === "state_c" || cp_head1 === "state_d");
var live2 = (cp_head2 === "state_b" || cp_head2 === "state_c" || cp_head2 === "state_d");
var tie_closed = (live1 && cp_head2 === "state_a") || (live2 && cp_head1 === "state_a");
var head1_active = live1;
var head2_active = live2;

var measured_voltage, measured_current;

if (tie_closed && live1) {   // บัสขนาน: ทั้งสองกลุ่มป้อนหัวนี้
    // Head1 only — all modules contribute to head1
    measured_voltage = (v1 || v2) ? ((v1 > 0 ? v1 : v2)) : 0;
    measured_current = i1 + i2;
} else if (live1) {   // บัสแยก: มีแค่กลุ่มของตัวเองป้อน
    // Both active — G1 (i1) serves head1, G2 (i2) serves head2
    measured_voltage = v1 || 0;
    measured_current = i1;
} else {
    // ===== FIX 15 ก.ค.: หัว 1 ไม่มีรถต่ออยู่ -> คอนแทกเตอร์เปิด -> ที่หัวจ่ายต้องเป็น 0 =====
    // ห้ามรายงานค่าของกลุ่มโมดูลตัวเอง: ตอนหัว 2 ชาร์จเดี่ยว บัสขนานทำให้โมดูลกลุ่มนี้
    // ไปช่วยหัว 2 ค่าที่โมดูลอ่านได้จึงเป็นของบัสหัว 2 (เช่น 408 V / 66 A)
    // ถ้ารายงานออกไปจะกลายเป็น Present voltage/current หลอนที่หัว 1 ทั้งที่มิเตอร์วัดได้ 0
    measured_voltage = 0;
    measured_current = 0;
}

var isolation_status = global.get("imd.isolation_status");
var imd_status = global.get("imd.status");
var pm_status = global.get("pm.status");
var contactor_status = global.get("contactor.status");
var operational_status = "inoperative";

if (pm_status == "operative" && imd_status == "operative") {
    operational_status = "operative";
}

// ===== COMEMSO FIX (20 ม.ค.) + hotfix 14 ก.ค.: emergency -> inoperative + contactor open =====
// เฉพาะ state_e (CP short จริง) และปุ่มฉุกเฉิน (emerActive)
// ห้ามสะท้อน state_f: vSECC ออก state_f เองทุกครั้งที่ connector inoperative (PWM 0%)
// การรายงาน inoperative กลับเมื่อเห็น state_f จะสร้าง feedback loop -> แกว่ง/ค้างถาวร
var is_emergency = (cp_head1 === "state_e" ||
                    global.get("emerActive") === true);
if (is_emergency) {
    operational_status = "inoperative";
    contactor_status = "open";
    if (context.get("emWarned") !== true) {
        node.warn("STATUS H1: emergency detected -> inoperative + contactor open");
        context.set("emWarned", true);
    }
    node.status({ fill: "red", shape: "dot", text: "EMERGENCY -> inoperative" });
} else {
    context.set("emWarned", false);
}

msg.payload = {
    type: "info",
    kind: "status",
    payload: {
        measuredVoltage: measured_voltage,
        measuredCurrent: measured_current,
        drivenVoltage: 0,
        drivenCurrent: 0,
        temperature: 25.0,
        contactorsStatus: contactor_status != undefined ? contactor_status : "open",
        // ===== COMEMSO FIX: default "valid" เมื่อ IMD ยังไม่ set ค่า =====
        // (เดิม "invalid" ทำให้ vSECC ค้าง "Waiting for Isolation Monitoring")
        isolationStatus: isolation_status != undefined ? isolation_status : "valid",
        operationalStatus: operational_status
    },
};

return msg;

var min_voltage = global.get('pm.min_voltage');
var max_voltage = global.get('pm.max_voltage');
var min_current = global.get('pm.min_current');
var max_current = global.get('pm.max_current');
var min_power = global.get('pm.min_power');
var max_power = global.get('pm.max_power');
var discharge_min_current = global.get('pm.discharge_min_current');
var discharge_max_current = global.get('pm.discharge_max_current');
var discharge_min_power = global.get('pm.discharge_min_power');
var discharge_max_power = global.get('pm.discharge_max_power');

msg.payload.type = "response";
msg.payload.payload.firmwareVersion = "v0.0.1";
msg.payload.payload.manufacturer = "Vector Informatik GmbH";
msg.payload.payload.limitVoltageMin = min_voltage != undefined ? min_voltage : 0,
msg.payload.payload.limitVoltageMax = max_voltage != undefined ? max_voltage : 0,
msg.payload.payload.limitCurrentMin = min_current != undefined ? min_current : 0,
msg.payload.payload.limitCurrentMax = max_current != undefined ? max_current : 400,
msg.payload.payload.limitPowerMin = min_power != undefined ? min_power : 0,
msg.payload.payload.limitPowerMax = max_power != undefined ? max_power : 0,
msg.payload.payload.limitDischargeCurrentMin = discharge_min_current != undefined ? discharge_min_current : 0,
msg.payload.payload.limitDischargeCurrentMax = discharge_max_current != undefined ? discharge_max_current : 0,
msg.payload.payload.limitDischargePowerMin = discharge_min_power != undefined ? discharge_min_power : 0,
msg.payload.payload.limitDischargePowerMax = discharge_max_power != undefined ? discharge_max_power : 0,
msg.payload.payload.floatValues = true;
return msg;

// ===== HARDENED 16 ก.ค.: ห้ามให้ exception ฆ่าเส้นตอบ =====
// ถ้าเส้นตอบ targetValues เงียบเกิน ~3 วิ watchdog ของ vSECC (pe_ws_inbox/outbox)
// จะตัดเป็น pe_connection failure -> PE_OFFLINE -> ตู้หยุดชาร์จทั้งสองหัวทันที
// (เกิดจริง 16 ก.ค. 11:21:03) จึงต้องตอบให้ได้เสมอไม่ว่าจะเกิดอะไรขึ้น
try {
    msg.payload.type = "response";
    msg.payload.payload = null;
    return msg;
} catch (e) {
    node.warn("ack-response exception: " + e.message);
    return {
        _session: msg._session,
        payload: {
            type: "response",
            kind: (msg.payload && msg.payload.kind) || "targetValues",
            sequenceNumber: (msg.payload && msg.payload.sequenceNumber) || 0,
            payload: null
        }
    };
}

// CableCheck: ใช้ EV Max Voltage ตามมาตรฐาน DIN 70121 / ISO 15118
if (msg.payload.kind == "cableCheck") {
    // ดึงค่า EV Max Voltage จาก global context (ถูก set จาก ChargeParameterDiscovery)
    var evMaxVoltage = global.get("ev.max_voltage1") || 500;

    // ใช้ค่าที่น้อยกว่าระหว่าง EV Max Voltage และ EVSE Max Voltage
    var evseMaxVoltage = global.get("pm.max_voltage") || 1000;
    var targetVoltage = Math.min(evMaxVoltage, evseMaxVoltage);

    var TargetCurrent = 0;
    global.set("pep.target_voltage", targetVoltage);
    global.set("pep.target_current", TargetCurrent);
    global.set("pep.charging_state", "cableCheck");   // FIX-2A-20260814

    node.status({fill:"blue", shape:"dot", text:"CableCheck V=" + targetVoltage + " (EV Max=" + evMaxVoltage + ")"});

    msg.payload = { 
        "targetVoltage": targetVoltage,
        "targetCurrent": 0  
    };
}
else if (msg.payload.kind == "targetValues") {
    global.set("pep.target_voltage", msg.payload.payload.targetVoltage);
    global.set("pep.target_current", msg.payload.payload.targetCurrent);
    global.set("pep.charging_state", String(msg.payload.payload.chargingState || ""));   // FIX-2A-20260814
}
else if (msg.payload.kind == "reset") {
    global.set("pep.target_voltage", 0);
    global.set("pep.target_current", 0);
    global.set("pep.charging_state", "");   // FIX-2A-20260814
}
return msg;

