// guard-init 13 ส.ค.: ตั้งค่าเริ่มต้นเฉพาะตอนยังไม่มีค่า - deploy ระหว่างชาร์จจะไม่ทับค่า live
if (global.get("pep.target_voltage") === undefined) {
    global.set("pep.target_voltage", 0);
    global.set("pep.target_current", 0);
}

