// CableCheck: ใช้ EV Max Voltage ตามมาตรฐาน
if (msg.payload === "CableCheck") {
    // ดึงค่า EV Max Voltage
    var evMaxVoltage = global.get("ev.max_voltage1") || 500;
    var evseMaxVoltage = global.get("pm.max_voltage") || 1000;
    var targetVoltage = Math.min(evMaxVoltage, evseMaxVoltage);

    node.status({fill:"blue", shape:"dot", text:"CableCheck V=" + targetVoltage});

    msg.payload = {
        type: "request",
        kind: "cableCheck",
        sequenceNumber: 0,
        payload: {
            targetVoltage: targetVoltage,
            targetCurrent: 0
        }
    };
    return msg;
}

// ส่ง dynamic limits ไป vSECC
// ใช้เมื่อต้องการเปลี่ยน power limit ระหว่างชาร์จ


// อ่านค่าตัวเลขแบบไม่ให้ 0 หายไป  (0 || N คืน N เพราะ 0 เป็น falsy ใน JS)
const num = (v, dflt) => { const n = Number(v); return Number.isFinite(n) ? n : dflt; };
var maxVoltage = num(global.get('pm.max_voltage'), 1000);
var maxCurrent = num(global.get('pm.max_current'), 400);
const cfg = global.get('sinexcel_cfg') || {};
const fallbackMaxPower = num(cfg.total_power_W, 120000);
var maxPower   = num(global.get('pm.max_power'), fallbackMaxPower);
var minVoltage = num(global.get('pm.min_voltage'), 0);
var minCurrent = num(global.get('pm.min_current'), 0);
var minPower   = num(global.get('pm.min_power'), 0);

// สร้าง PEP-WS info-dynamicLimits message
msg.payload = {
    "type": "info",
    "kind": "dynamicLimits",
    "payload": {
        "limitVoltageMin": minVoltage,
        "limitVoltageMax": maxVoltage,
        "limitCurrentMin": minCurrent,
        "limitCurrentMax": maxCurrent,
        "limitPowerMin": minPower,
        "limitPowerMax": maxPower
    }
};

const held = (maxPower === 0 || maxCurrent === 0);
node.warn('PE1 Dynamic Limits: maxPower=' + maxPower + 'W, maxCurrent=' + maxCurrent + 'A' + (held ? '  <<< HOLD 0A' : ''));
node.status({ fill: held ? "yellow" : "green", shape: "dot",
              text: maxPower + "W / " + maxCurrent + "A" + (held ? "  HOLD" : "") });

return msg;

// FIX-2A-20260814
// PEP-WS "configuration" = STATIC nameplate ของตู้ ซึ่ง vSECC อ่านครั้งเดียวตอน
// WebSocket ต่อใหม่ แล้ว cache ไว้เป็น static_power_limit_watts ยาวทั้ง session
//
// ห้ามอ่าน pm.max_power / pm.max_current ตรงนี้เด็ดขาด เพราะเป็นค่า "สด" ที่ถูกบังคับ
// เป็น 0 ได้ (E-stop -> emerActive, ARCH2 hold) ถ้า vSECC บังเอิญถามตอนนั้น มันจะ
// จำว่าตู้จ่ายได้ 0 W แล้วสั่ง targetCurrent = 0 ทั้ง session
// เหตุจริง 14 ส.ค. 03:30:50 + 03:35:16 -> ChargingProfileMaxPowerLimit 0 W ที่ 03:38:57
//
// ค่าจำกัดแบบเรียลไทม์ต้องไปทาง "dynamicLimits" เท่านั้น (โหนด Send Dynamic Limits PE1)

const cfg = global.get('sinexcel_cfg') || {};

function modCount(group, fallback) {
    if (cfg.group_modules && Array.isArray(cfg.group_modules[group]) && cfg.group_modules[group].length > 0) {
        return cfg.group_modules[group].length;
    }
    const c = cfg.group_module_count || {};
    const v = Number(c[group] !== undefined ? c[group] : c[String(group)]);
    return Number.isFinite(v) && v > 0 ? v : fallback;
}

const MODULES_G1      = modCount(1, 2);
const MODULES_G2      = modCount(2, 2);
const TOTAL_MODULES   = MODULES_G1 + MODULES_G2;
const MODULE_MAX_PWR  = Number(cfg.module_max_power_W)   || 30000;
const MODULE_MAX_CURR = Number(cfg.module_max_current_A) || 100;
const CURRENT_LIMIT_A = Number(cfg.current_limit_A)      || 400;

// พิกัดสูงสุดที่หัวนี้ทำได้ = ตอนบัสขนาน ใช้โมดูลได้ครบทุกตัว
// pm.installed_power ถูกตั้งครั้งเดียวตอน startup โดย "set min/max limits + sinexcel_cfg"
// และไม่มี branch ไหนแตะ จึงปลอดภัยกว่า pm.max_power
const STATIC_MAX_POWER   = Number(global.get('pm.installed_power'))
                        || Number(cfg.total_power_W)
                        || (TOTAL_MODULES * MODULE_MAX_PWR);
const STATIC_MAX_CURRENT = Math.min(TOTAL_MODULES * MODULE_MAX_CURR, CURRENT_LIMIT_A);
const STATIC_MAX_VOLTAGE = Number(global.get('pm.max_voltage')) || 1000;

// กันพลาดอีกชั้น: static rating ต้องไม่มีทางเป็น 0
if (!(STATIC_MAX_POWER > 0) || !(STATIC_MAX_CURRENT > 0)) {
    node.error('PE1 configuration: static rating คำนวณได้ 0 -> ตรวจ global sinexcel_cfg / pm.installed_power', msg);
    return null;   // ไม่ตอบ ดีกว่าตอบ 0 (vSECC จะถามซ้ำตอนต่อใหม่)
}

node.warn('PE1 Config Response (STATIC): maxPower=' + STATIC_MAX_POWER
        + 'W, maxCurrent=' + STATIC_MAX_CURRENT.toFixed(1) + 'A');
node.status({ fill: 'blue', shape: 'dot', text: 'static ' + (STATIC_MAX_POWER / 1000).toFixed(0) + 'kW' });

msg.payload.type = 'response';
msg.payload.payload.firmwareVersion = 'v0.0.1';
msg.payload.payload.manufacturer    = 'Vector Informatik GmbH';
msg.payload.payload.limitVoltageMin = 0;
msg.payload.payload.limitVoltageMax = STATIC_MAX_VOLTAGE;
msg.payload.payload.limitCurrentMin = 0;
msg.payload.payload.limitCurrentMax = STATIC_MAX_CURRENT;
msg.payload.payload.limitPowerMin   = 0;
msg.payload.payload.limitPowerMax   = STATIC_MAX_POWER;
msg.payload.payload.limitDischargeCurrentMin = 0;
msg.payload.payload.limitDischargeCurrentMax = 0;
msg.payload.payload.limitDischargePowerMin   = 0;
msg.payload.payload.limitDischargePowerMax   = 0;
msg.payload.payload.floatValues = true;

return msg;

// เก็บค่า EV Max Voltage จาก ChargeParameterDiscovery
var voltage = parseFloat(msg.payload);
if (!isNaN(voltage) && voltage > 0) {
    global.set("ev.max_voltage1", voltage);
    node.status({fill:"green", shape:"dot", text:"EV Max V=" + voltage});
} else {
    node.status({fill:"yellow", shape:"ring", text:"Invalid: " + msg.payload});
}
return msg;

// โผล่ใน docker logs <node-red>: จับตัวการที่ทำให้เส้นตอบตาย
var src = (msg.error && msg.error.source && msg.error.source.name) || "?";
var em  = (msg.error && msg.error.message) || "?";
node.warn("PEP-WS tab error @" + src + " :: " + em);
return null;

// Last-line validation before a message reaches the PEP WebSocket.
// Internal "values_updated" triggers use payload: {} and must never be sent
// to PEP because PEP requires every message to contain a non-empty type.
function dropInvalid(reason) {
    const count = (context.get("droppedInvalidPepMessages") || 0) + 1;
    context.set("droppedInvalidPepMessages", count);
    node.status({
        fill: "yellow",
        shape: "ring",
        text: "blocked invalid PEP message x" + count
    });
    // Keep diagnostics useful without flooding the Node-RED log.
    if (count === 1 || count % 100 === 0) {
        node.warn("Blocked invalid PEP WS message: " + reason + " (count=" + count + ")");
    }
    return null;
}

let payload = msg.payload;

if (Buffer.isBuffer(payload)) {
    payload = payload.toString("utf8");
}

if (typeof payload === "string") {
    const text = payload.trim();
    if (!text) {
        return dropInvalid("empty string");
    }
    try {
        payload = JSON.parse(text);
    } catch (err) {
        return dropInvalid("invalid JSON string");
    }
}

if (payload === null || typeof payload !== "object" || Array.isArray(payload)) {
    return dropInvalid("payload is not a JSON object");
}

if (Object.keys(payload).length === 0) {
    return dropInvalid("empty object {}");
}

if (typeof payload.type !== "string" || payload.type.trim() === "") {
    return dropInvalid("missing required key 'type'");
}

msg.payload = payload;
node.status({
    fill: "green",
    shape: "dot",
    text: "valid " + payload.type + (payload.kind ? "/" + payload.kind : "")
});
return msg;

var cp_head1 = global.get("cp_state_head1");
var cp_head2 = global.get("cp_state_head2");

var v1 = global.get("pm.measured_voltage")  || 0;
var i1 = global.get("pm.measured_current")  || 0;
var v2 = global.get("pm.measured_voltage2") || 0;
var i2 = global.get("pm.measured_current2") || 0;

// ===== FIX 16 ก.ค.: จัดสรรโมดูลต้องอิงคอนแทกเตอร์เชื่อมบัสจริง =====
// ground truth = "function 4" -> DC bypass (R6 / d_out/7)
//   ปิด  = บัส G1+G2 ขนานกัน -> โมดูลทุกกลุ่มไปช่วยหัวเดียวกันได้ (แบ่งตามสัดส่วนโมดูล)
//   เปิด = บัสแยกขาด        -> G1 ผูกหัว 1, G2 ผูกหัว 2 ตายตัว
// สูตร tie_closed ต้องเหมือน function 4 ทุกตัวอักษร ห้ามแก้ข้างเดียว
// (เดิมใช้แค่ b/c/d: อีกหัวตกไป state_e/state_f จะถูกนับว่า "ว่าง" -> หารกระแสไปอีกกลุ่ม
//  ทั้งที่บัสยังแยก -> ไฟไปไม่ถึงรถ และประกาศกำลังเกินที่จ่ายได้จริง)
var live1 = (cp_head1 === "state_b" || cp_head1 === "state_c" || cp_head1 === "state_d");
var live2 = (cp_head2 === "state_b" || cp_head2 === "state_c" || cp_head2 === "state_d");
var tie_closed = (live1 && cp_head2 === "state_a") || (live2 && cp_head1 === "state_a");
var head1_active = live1;
var head2_active = live2;

var measured_voltage, measured_current;

if (tie_closed && live2) {   // บัสขนาน: ทั้งสองกลุ่มป้อนหัวนี้
    // Head2 only — all modules contribute to head2
    measured_voltage = (v2 || v1) ? ((v2 > 0 ? v2 : v1)) : 0;
    measured_current = i1 + i2;
} else if (live2) {   // บัสแยก: มีแค่กลุ่มของตัวเองป้อน
    // Both active — G2 (i2) serves head2, G1 (i1) serves head1
    measured_voltage = v2 || 0;
    measured_current = i2;
} else {
    // ===== FIX 15 ก.ค.: หัว 2 ไม่มีรถต่ออยู่ -> คอนแทกเตอร์เปิด -> ที่หัวจ่ายต้องเป็น 0 =====
    // ห้ามรายงานค่าของกลุ่มโมดูลตัวเอง: ตอนหัว 1 ชาร์จเดี่ยว บัสขนานทำให้โมดูลกลุ่มนี้
    // ไปช่วยหัว 1 ค่าที่โมดูลอ่านได้จึงเป็นของบัสหัว 1 (เช่น 408 V / 66 A)
    // ถ้ารายงานออกไปจะกลายเป็น Present voltage/current หลอนที่หัว 2 ทั้งที่มิเตอร์วัดได้ 0
    measured_voltage = 0;
    measured_current = 0;
}

var isolation_status = global.get("imd.isolation_status2");
var imd_status = global.get("imd.status");
var pm_status = global.get("pm.status2");
var contactor_status = global.get("contactor.status2");
var operational_status = "inoperative";

if (pm_status == "operative" && imd_status == "operative") {
    operational_status = "operative";
}

// ===== COMEMSO FIX (20 ม.ค.) + hotfix 14 ก.ค.: emergency -> inoperative + contactor open =====
// เฉพาะ state_e (CP short จริง) และปุ่มฉุกเฉิน (emerActive)
// ห้ามสะท้อน state_f: vSECC ออก state_f เองทุกครั้งที่ connector inoperative (PWM 0%)
