    var evMaxVoltage = global.get("ev.max_voltage2") || 500;

    // ใช้ค่าที่น้อยกว่าระหว่าง EV Max Voltage และ EVSE Max Voltage
    var evseMaxVoltage = global.get("pm.max_voltage2") || 1000;
    var targetVoltage = Math.min(evMaxVoltage, evseMaxVoltage);

    var TargetCurrent = 0;
    global.set("pep.target_voltage2", targetVoltage);
    global.set("pep.target_current2", TargetCurrent);
    global.set("pep.charging_state2", "cableCheck");   // FIX-2A-20260814

    node.status({fill:"blue", shape:"dot", text:"CableCheck V=" + targetVoltage + " (EV Max=" + evMaxVoltage + ")"});

    msg.payload = { 
        "targetVoltage": targetVoltage,
        "targetCurrent": 0  
    };
}
else if (msg.payload.kind == "targetValues") {
    global.set("pep.target_voltage2", msg.payload.payload.targetVoltage);
    global.set("pep.target_current2", msg.payload.payload.targetCurrent);
    global.set("pep.charging_state2", String(msg.payload.payload.chargingState || ""));   // FIX-2A-20260814
}
else if (msg.payload.kind == "reset") {
    global.set("pep.target_voltage2", 0);
    global.set("pep.target_current2", 0);
    global.set("pep.charging_state2", "");   // FIX-2A-20260814
}
return msg;

