// ปัญหา: charging_session_state = VSECCLIB_SST_DIN_SessionStop มาแป๊บเดียว
// ทำให้เงื่อนไขที่ผูกกับ cp_state (state_b) อาจพลาดได้
//
// พฤติกรรมที่ต้องการ:
// - เมื่อเห็น SessionStop ให้ latch finishing = 1
// - ค้างไว้จนกว่าจะถอดสาย (cp_state = state_a) แล้วค่อย reset เป็น 0
// - เผื่อกรณี SessionStop ถูก clear เร็ว ให้ดู previous CS ด้วย

let cp = flow.get("CP1");
let cs = flow.get("CS1");

if (cp === undefined || cp === null) cp = "";
if (cs === undefined || cs === null) cs = "";

let prevCs = flow.get("prev_CS1");
if (prevCs === undefined || prevCs === null) prevCs = "";

let finishing = global.get("H1_Finishing");
if (finishing === undefined || finishing === null) finishing = 0;

const SESSION_STOP = "VSECCLIB_SST_DIN_SessionStop";

// 1) Reset เมื่อถอดสาย
if (cp === "state_a") {
    finishing = 0;
} else {
    // 2) Set เมื่อเห็น SessionStop (ไม่ผูกกับ cp_state)
    if (cs === SESSION_STOP) {
        finishing = 1;
    }
    // 3) Fallback: ถ้า SessionStop เคยมาแล้วแต่ถูก clear เร็ว (cs = "")
    else if (prevCs === SESSION_STOP && cs === "") {
        finishing = 1;
    }
}

// เก็บค่าไว้ใช้งานครั้งถัดไป
global.set("H1_Finishing", finishing);
flow.set("prev_CS1", cs);

msg.payload = finishing;
return msg;

global.set("arch2Enabled", true);
global.set("startCommanded1", false);
global.set("startCommanded2", false);
global.set("autoAuthSent1", false);
global.set("autoAuthSent2", false);
node.warn("ARCH2 ON: ตู้จะ authorize อัตโนมัติตอนเสียบสาย และกั๊กกระแสไว้ 0 A จนกว่าจะมี RemoteStart");
node.status({fill:"yellow",shape:"dot",text:"ARCH2 ON"});
return { payload: "recalc" };   // v18: เด้ง Calculate + publisher ทันที ไม่รอ tick 1 วิ

global.set("arch2Enabled", false);
global.set("startCommanded1", false);
global.set("startCommanded2", false);
node.warn("ARCH2 OFF: กลับไปด่านเดิมที่ ContractAuthentication (จะกลับมา ON เองตอน Node-RED restart)");
node.status({fill:"grey",shape:"ring",text:"ARCH2 OFF"});
return { payload: "recalc" };   // v18: เด้ง Calculate + publisher ทันที ไม่รอ tick 1 วิ

// เปิด ARCH2 ถาวร ไม่ต้องกดปุ่ม
// กู้ startCommanded จากไฟล์ เพื่อไม่ให้ Node-RED restart ไปตัดกระแสลูกค้าที่จ่ายแล้ว
let st = {};
try { st = JSON.parse(String(msg.payload || "{}")); } catch (e) { st = {}; }

global.set("arch2Enabled", true);

[1, 2].forEach(c => {
    const cp   = String(global.get("cp_state" + c) || "");
    const auth = String(global.get("auth_state_head" + c) || "pending");
    // ยอมรับสถานะ "สั่งชาร์จแล้ว" เฉพาะเมื่อรถยังต่อคอนแทกเตอร์อยู่จริง
    // ถ้าไม่มีรถ / เพิ่งเสียบ -> บังคับเป็น false (กันคันใหม่ได้ไฟฟรี)
    const live    = (cp === "state_c" || cp === "state_d");
    const started = (st["h" + c] === true) && live;

    global.set("startCommanded" + c, started);
    global.set("autoAuthSent" + c, auth === "authorized");   // อย่ายิง add_token ซ้ำ
    global.set("holdStart" + c, false);
    global.set("idleStopSent" + c, false);
    global.set("reinitDone" + c, false);
});

node.warn("ARCH2 ON (auto): H1 started=" + global.get("startCommanded1")
        + " H2 started=" + global.get("startCommanded2"));
node.status({ fill: "yellow", shape: "dot", text: "ARCH2 ON (auto)" });
return null;

const st = { h1: global.get("startCommanded1") === true,
             h2: global.get("startCommanded2") === true };
const s = JSON.stringify(st);
if (s === context.get("last")) return null;   // เขียนเฉพาะตอนเปลี่ยน กัน /data สึกหรอ
context.set("last", s);
node.status({ fill: "grey", shape: "dot", text: s });
msg.payload = s;
return msg;

// ARCH2: ยิง token ทันทีที่เสียบสาย -> ContractAuthentication ผ่านเลย ไม่มีนาฬิกา 45 วิ
// ไฟยังไม่ไหล เพราะโดนกั๊กที่ CurrentDemand (ดู Calculate Power/Current)
const cp = String(msg.payload || "").trim();

// ถอดสาย/error -> reset ทุกอย่าง (ทำก่อนเช็ค arch2 เสมอ = fail-safe)
if (cp === "state_a" || cp === "state_e" || cp === "state_f") {
    global.set("autoAuthSent1", false);
    global.set("startCommanded1", false);
    // FIX#SELFSTOP rev1: ถอดสาย/fault = จบรอบเสียบ -> ปลด latch ทุกตัว พร้อมรับคันใหม่
    global.set("socHold1", false);
    global.set("manualStop1", false);
    global.set("idleStopSent1", false);
    node.status({ fill: "grey", shape: "ring", text: "idle (" + cp + ")" });
    return null;
}

if (global.get("arch2Enabled") !== true) return null;
if (cp !== "state_b") return null;

// ===== FIX#AUTHBOUNCE rev1 (09 พ.ย. 2026): CP เด้ง b->a->b ตอนเสียบ (log 20:32:48 ห่าง 1.3 วิ) ทำให้ token ถูกส่งซ้ำ 2 ครั้ง
// ใน 0.6 วิ -> vSECC ตีความ token ซ้ำเป็น DEAUTHORIZE (ALLOWED -> NOT_ALLOWED) -> รถค้าง ContractAuthentication
// -> ไม่ส่ง token ซ้ำภายใน 2.5 วิ (ถ้าค้างจริง FIX#AUTHWD watchdog จะส่งใหม่ให้เองหลัง 3 วิ)
if (Date.now() - (Number(global.get("autoAuthTs1")) || 0) < 2500) {
    node.status({ fill: "yellow", shape: "ring", text: "token sent <2.5s ago (CP bounce) -> skip" });
    return null;
}

// ===== FIX#SELFSTOP rev1: AUTOSTART (plug-and-charge) =====
// เดิม: authorize อัตโนมัติแต่กั๊ก 0 A รอ topic/RemoteStart -> ถ้าไม่มีใครกด ก็โดน
// idle timeout ตัดที่ 120 วิ แล้วรถ retry วนไปเรื่อย (log ตู้นี้: session 162/117 วิ + ค้าง 0 A ยาว)
// ใหม่: เสียบสายแล้วสั่งชาร์จเลย ยกเว้นติด latch:
//   socHold1    = ตัดที่ 90% ไปแล้วในรอบเสียบนี้ (ห้ามชาร์จต่อจนกว่าจะถอดสาย)
//   manualStop1 = ผู้ใช้กดหยุดเอง (ปุ่ม DIN8 / หน้าจอ) -> ต้องถอดสายหรือกด Start ใหม่
const AUTOSTART = false;  // rev1.1 (21 ส.ค.): ไซต์นี้ต้องกดปุ่ม Start บนจอก่อนจ่ายไฟ (แจ้งจากหน้างาน) | true = plug-and-charge
if (AUTOSTART && global.get("socHold1") !== true && global.get("manualStop1") !== true
    && global.get("startCommanded1") !== true) {
    global.set("startCommanded1", true);
    node.warn("H1: ARCH2 AUTOSTART -> ปลดกั๊ก 0 A ทันทีที่เสียบสาย (limit ส่งใหม่ภายใน 1 วิ)");
}

const auth = String(global.get("auth_state_head1") || "pending");
if (auth === "authorized") { node.status({fill:"green",shape:"dot",text:"already authorized"}); return null; }
if (global.get("autoAuthSent1") === true) { node.status({fill:"blue",shape:"ring",text:"token sent"}); return null; }

global.set("autoAuthSent1", true);
global.set("autoAuthTs1", Date.now());   // FIX#AUTHBOUNCE / FIX#AUTHWD
node.warn("H1: ARCH2 auto-authorize ตอนเสียบสาย");
node.status({ fill: "yellow", shape: "dot", text: "auto add_token" });
return { payload: { auto: true, cp_state: cp } };

const state = String(msg.payload || "").trim();
const prev  = global.get("auth_state_head1") || "pending";
global.set("auth_state_head1", state);
node.status({ fill: state === "authorized" ? "green" : "grey", shape: "dot", text: state || "-" });

// ขอบขาขึ้นเข้าสู่ authorized -> ให้ตัว reinit ตัดสินใจทันที ไม่ต้องรอ timer
if (state === "authorized" && prev !== "authorized") return msg;
return null;

const state = String(msg.payload || "").trim();
global.set("session_state_head1", state);

const DEAD = /(SessionStop|Terminate|Stopped|Finished|WeldingDetection)/i;
const isDead = (state === "" || DEAD.test(state));

// เห็น session ที่มีชีวิตจริง -> ตั้งธง เพื่อแยก "ยังไม่เริ่ม" ออกจาก "เริ่มแล้วตาย"
if (!isDead) global.set("sessionSeen1", true);

node.status({ fill: isDead ? "red" : "green", shape: "dot", text: state || "(empty)" });
return msg;

// คำสั่งชาร์จจาก OCPP มาถึงแล้ว -> ปลดล็อกกระแส
global.set("startCommanded1", true);
global.set("manualStop1", false);   // FIX#SELFSTOP rev1: ผู้ใช้สั่ง Start เอง -> ปลด latch หยุดมือ
node.warn("H1: START COMMANDED -> ปลดกั๊ก 0 A (limit จะถูกส่งใหม่ภายใน 1 วิ)");
node.status({ fill: "green", shape: "dot", text: "start commanded @ " + new Date().toISOString() });
return { payload: "recalc" };   // v18: เด้ง Calculate + publisher ทันที ไม่รอ tick 1 วิ

global.set("startCommanded1", false);
node.warn("H1: กลับไปกั๊ก 0 A");
return { payload: "recalc" };   // v18: เด้ง Calculate + publisher ทันที ไม่รอ tick 1 วิ

// กั๊ก 0 A ได้ไม่จำกัดในทางเทคนิค (ทดสอบแล้ว 5 นาที 44 วิ ไม่มี error)
// แต่ตอนกั๊ก: คอนแทกเตอร์ปิด HV อยู่บนสาย OCPP transaction เปิดค้าง
// -> ต้องมีเพดาน ถ้าลูกค้าเดินหนีไป
const HOLD_TIMEOUT_MS = 120000;   // 2 นาที

if (global.get("arch2Enabled") !== true) { node.status({fill:"grey",shape:"ring",text:"ARCH2 OFF"}); return null; }

const cp    = String(global.get("cp_state1") || "");
const sess  = String(global.get("session_state_head1") || "");
const start = global.get("startCommanded1") === true;
const now   = Date.now();

if (cp !== "state_b" && cp !== "state_c" && cp !== "state_d") {
    global.set("holdStart1", false); global.set("idleStopSent1", false);
    node.status({fill:"grey",shape:"ring",text:"no EV"});
    return null;
}
if (start) {
    global.set("holdStart1", false);
    node.status({fill:"green",shape:"dot",text:"charging"});
    return null;
}
if (!/current[_\s-]?demand/i.test(sess)) {
    global.set("holdStart1", false);
    node.status({fill:"blue",shape:"ring",text:"รอ | " + (sess || cp)});
    return null;
}

if (!global.get("holdStart1")) global.set("holdStart1", now);
const t = Math.round((now - global.get("holdStart1")) / 1000);

if (t * 1000 >= HOLD_TIMEOUT_MS) {
    if (global.get("idleStopSent1") === true) return null;
    global.set("idleStopSent1", true);
    node.warn("H1: กั๊ก 0 A ครบ " + t + "s ไม่มี RemoteStart -> stop_charging (รถต้องถอดสายเสียบใหม่)");
    node.status({fill:"red",shape:"dot",text:"idle timeout -> stop"});
    return { payload: "1" };
}
node.status({fill:"yellow",shape:"dot",text:"HOLD 0A " + t + "/" + (HOLD_TIMEOUT_MS/1000) + "s"});
return null;

// ===== FIX#AUTHWD rev1 (09 พ.ย. 2026): ARCH2 authorization watchdog H1 =====
// เหตุ 09/11 20:32:48 (หัว 1): เสียบสายแล้ว CP เด้ง b -> a -> b ภายใน 1.3 วิ ทำให้ add_token ถูกส่ง 2 ครั้งใน 0.6 วิ
//   -> vSECC ตีความ token ซ้ำเป็น DEAUTHORIZE (log: Charging Permission ALLOWED -> NOT_ALLOWED ห่าง 140 ms)
//   -> auth_state_head1 ใน Node-RED ค้างเป็น "authorized" -> Create Token Payload ไม่ยอมส่ง token ใหม่
//   -> รถค้าง ContractAuthentication ("Authorization still pending") 75 วิ จนถอดสาย = "หัว 1 ชาร์จไม่ได้"
// แก้: ถ้า session ค้างอยู่ที่ ContractAuthentication/Authorization เกิน AUTH_STUCK_MS ทั้งที่รถยังเสียบอยู่
//   ถือว่า vSECC ไม่ได้ authorize จริง (ถ้า authorize แล้ว vSECC จะไป ChargeParameterDiscovery ภายใน <1 วิ)
//   -> ตั้ง auth_state_head1 = "pending" แล้วส่ง token ใหม่ผ่าน "Create Token Payload" (ทุก RESEND_MS, สูงสุด MAX_RESEND ครั้ง/รอบเสียบ)
// ทำงานร่วมกับ FIX#AUTHBOUNCE ใน "ARCH2: Auto-Authorize on Plug-In H1" (ไม่ส่ง token ซ้ำภายใน 2.5 วิ)
const N = 1;
const AUTH_STUCK_MS = 3000;
const RESEND_MS = 5000;
const MAX_RESEND = 5;

if (global.get("arch2Enabled") !== true) { node.status({ fill: "grey", shape: "ring", text: "ARCH2 OFF" }); return null; }

const cp   = String(global.get("cp_state" + N) || "");
const sess = String(global.get("session_state_head" + N) || "");
const auth = String(global.get("auth_state_head" + N) || "pending");
const now  = Date.now();

if (cp !== "state_b" && cp !== "state_c" && cp !== "state_d") {
    context.set("stuckSince", 0); context.set("resends", 0);
    node.status({ fill: "grey", shape: "ring", text: "no EV" });
    return null;
}
const inAuth = /ContractAuthentication|PaymentDetails|Authorization/i.test(sess) && !/ChargeParameterDiscovery|CableCheck|PreCharge|CurrentDemand/i.test(sess);
if (!inAuth) {
    context.set("stuckSince", 0);
    if (auth === "authorized") context.set("resends", 0);
    node.status({ fill: "green", shape: "dot", text: (sess || cp) + " | auth=" + auth });
    return null;
}
let since = Number(context.get("stuckSince")) || 0;
if (!since) { since = now; context.set("stuckSince", since); }
const waited = now - since;
const resends = Number(context.get("resends")) || 0;
const lastTok = Number(global.get("autoAuthTs" + N)) || 0;

if (waited < AUTH_STUCK_MS || (now - lastTok) < RESEND_MS) {
    node.status({ fill: "yellow", shape: "ring", text: "auth pending " + Math.round(waited / 1000) + "s (auth=" + auth + ")" });
    return null;
}
if (resends >= MAX_RESEND) {
    node.status({ fill: "red", shape: "dot", text: "auth stuck " + Math.round(waited / 1000) + "s, resend limit reached" });
    return null;
}
context.set("resends", resends + 1);
global.set("auth_state_head" + N, "pending");          // ปลด guard ใน Create Token Payload (สถานะ authorized เดิมไม่จริงแล้ว)
global.set("autoAuthSent" + N, true);
global.set("autoAuthTs" + N, now);
node.warn("H" + N + ": FIX#AUTHWD session ค้าง " + sess + " " + Math.round(waited / 1000) + " วิ (auth_state เดิม=" + auth
    + ") -> ส่ง add_token ใหม่ ครั้งที่ " + (resends + 1) + "/" + MAX_RESEND);
node.status({ fill: "orange", shape: "dot", text: "re-send token #" + (resends + 1) + " @ " + Math.round(waited / 1000) + "s" });
return { payload: { auto: true, watchdog: true, cp_state: cp, session_state: sess } };

var cp_state = global.get("cp_state2");
var temperature1 = global.get("temperature3");
var temperature2 = global.get("temperature4");
var target_contactor_status = global.get("pep.target_contactor_status2");

const TEMPERATURE_MIN = 0.0;
const TEMPERATURE_MAX = 50.0;

var cp_state_ok = cp_state == "state_c" || cp_state == "state_d";
var is_target_contactor_status_closed = target_contactor_status == "closed";

// ===== FIX 13 ส.ค.: อุณหภูมิเป็น advisory ไม่บิดเบือนสถานะ contactor ที่รายงาน =====
// เดิม: อุณหภูมิหลุดช่วง/เซนเซอร์หาย -> รายงาน "open" ทั้งที่ contactor ปิดจริง
// -> vSECC สับสนกลาง session; ความร้อนควรแจ้งเตือนผ่านธง pe.temp_alarm2 แทน
function tempOk(t) { return (t === undefined || t === null) ? true : (t > TEMPERATURE_MIN && t < TEMPERATURE_MAX); }
var temps_ok = tempOk(temperature1) && tempOk(temperature2);
global.set("pe.temp_alarm2", !temps_ok);
if (!temps_ok && context.get("tWarned") !== true) {
    node.warn("H2: temperature out of range (t1=" + temperature1 + ", t2=" + temperature2 + ") -> ตั้งธง pe.temp_alarm2");
    context.set("tWarned", true);
} else if (temps_ok) {
    context.set("tWarned", false);
}

return {
    payload: cp_state_ok && is_target_contactor_status_closed ? 1 : 0
};

var new_status = msg.payload == 1 ? "closed" : "open";
global.set("contactor.status2", new_status)
return msg;

// NO DELAY!
global.set("report_failure", msg.payload);
var f = msg.payload;
node.status({fill:"yellow", shape:"dot", text:f});
if (f === "pe_isolation_fault" || f === "cm_state_e" || f === "charging_generic") {
    node.warn("⚡ " + f);
    node.status({fill:"red", shape:"ring", text:f});
    return msg;
}
msg.payload = "";
return msg;

// ดึงค่าปัจจุบันจาก flow
let icp_h1 = flow.get("CP1");
let usl_state_h1 = flow.get("CS1");

// ดึงค่าก่อนหน้าจาก flow
let previous_icp_h1 = flow.get("previousCP1", undefined);  // สถานะก่อนหน้าของ CP1
let previous_usl_state_h1 = flow.get("previousCS1", undefined);  // สถานะก่อนหน้าของ CS1

// เงื่อนไขที่ 1: ถ้า (icp_h1 == 'state_b' && usl_state_h1 == 'VSECCLIB_SST_DIN_SessionStop')
if (icp_h1 == 'state_b' && usl_state_h1 == 'VSECCLIB_SST_DIN_SessionStop') {
    msg.payload = 1;
}

// เงื่อนไขที่ 3: ถ้า (icp_h1 == 'state_b' && usl_state_h1 == 'VSECCLIB_SST_DIN_WeldingDetection' และ usl_state_h1 == ไม่มีค่า)
else if (icp_h1 == 'state_b' && previous_usl_state_h1 == 'VSECCLIB_SST_DIN_SessionStop' && (usl_state_h1 == '' || usl_state_h1 == undefined)) {
    msg.payload = 1;
}
// กรณีอื่น ๆ
else {
    msg.payload = 0;
}

// อัปเดตค่าใน flow context เพื่อใช้ในการตรวจสอบในครั้งถัดไป
flow.set("previousCP1", icp_h1);
flow.set("previousCS1", usl_state_h1);

return msg;


// let icp_h2 = flow.get("CP2");
// let usl_state_h2 = flow.get("CS2");

// if (icp_h2 == 'state_b' && usl_state_h2 == 'VSECCLIB_SST_DIN_SessionStop') {
//     global.set("H2_Finishing", 1)
// }
// else if (icp_h2 == 'state_a' && usl_state_h2 == '') {
//     global.set("H2_Finishing", 0)
// }

// msg.payload = global.get("H2_Finishing");

// return msg;

// ===== FIX 13 ส.ค.: parse RemoteStart2 แบบทนรูปแบบ payload =====
// เดิม: switch เช็ค payload.remote_start == 1 (number) เท่านั้น - payload รูปแบบอื่น
// ("1", 1, {"value":1}, "start") ถูกทิ้งเงียบๆ -> startCommanded2 ไม่ถูกตั้ง
// -> ARCH2 กั๊ก limit 0 A/0 W ตลอด session = "กด remote start แล้วตู้ไม่จ่ายกระแส"
var p = msg.payload, v;
if (p && typeof p === "object") v = (p.remote_start !== undefined) ? p.remote_start : p.value;
else v = p;
if (typeof v === "string") v = v.trim().toLowerCase();
var on = (v === 1 || v === "1" || v === true || v === "true" || v === "start" || v === "on");
if (on) {
    node.status({fill:"green", shape:"dot", text:"remote start รับแล้ว @ " + new Date().toISOString()});
    return msg;
}
node.warn("RemoteStart2: payload ไม่ตรงรูปแบบ ถูกละเว้น: " + JSON.stringify(msg.payload).slice(0, 120));
node.status({fill:"red", shape:"ring", text:"payload ไม่ถูกรูปแบบ"});
return null;

// ===== GUARD (v19-port) =====
// ส่ง add_token ด้วย token เดิมซ้ำ vSECC จะตีความว่า DEAUTHORIZE แล้วหยุดชาร์จ
if ((global.get("auth_state_head2") || "pending") === "authorized") {
    node.status({ fill: "yellow", shape: "ring", text: "already authorized - skip add_token" });
    return null;
}

// สร้าง token สำหรับ authorization
// ใช้ NoAuthorization + preauthorized เมื่อปิด CSMS

// msg.payload = {
//     "idToken": "Backup",
//     "type": "NoAuthorization",
//     "preauthorized": true
// };

msg.payload = {
        "idToken": "TestToken2",
        "type": "Local",
        "preauthorized": true
};

// เก็บ token ไว้ใช้ตอน assign
flow.set("currentToken2", "TestToken2");

return msg;

// ตรวจสอบว่า token อยู่ใน unassigned_tokens หรือไม่
let tokens = msg.payload;
let currentToken = flow.get("currentToken2");

// ถ้าเป็น string ให้แปลงเป็น array
if (typeof tokens === "string") {
    try {
        tokens = JSON.parse(tokens);
    } catch(e) {
        tokens = [];
    }
}

// ตรวจสอบว่า token ของเราอยู่ในรายการ
if (Array.isArray(tokens) && tokens.includes(currentToken)) {
    msg.payload = currentToken;
    return msg;
}

return null;

// Finishing2 latch (Connector 2)
// เหมือน Finishing1 แต่ใช้ CP2 / CS2

let cp = flow.get("CP2");
let cs = flow.get("CS2");

if (cp === undefined || cp === null) cp = "";
if (cs === undefined || cs === null) cs = "";

let prevCs = flow.get("prev_CS2");
if (prevCs === undefined || prevCs === null) prevCs = "";

let finishing = global.get("H2_Finishing");
if (finishing === undefined || finishing === null) finishing = 0;

const SESSION_STOP = "VSECCLIB_SST_DIN_SessionStop";

// 1) Reset เมื่อถอดสาย
if (cp === "state_a") {
    finishing = 0;
} else {
    // 2) Set เมื่อเห็น SessionStop (ไม่ผูกกับ cp_state)
    if (cs === SESSION_STOP) {
        finishing = 1;
    }
    // 3) Fallback: ถ้า SessionStop เคยมาแล้วแต่ถูก clear เร็ว (cs = "")
    else if (prevCs === SESSION_STOP && cs === "") {
        finishing = 1;
    }
}

global.set("H2_Finishing", finishing);
flow.set("prev_CS2", cs);

msg.payload = finishing;
return msg;

// ARCH2: ยิง token ทันทีที่เสียบสาย -> ContractAuthentication ผ่านเลย ไม่มีนาฬิกา 45 วิ
// ไฟยังไม่ไหล เพราะโดนกั๊กที่ CurrentDemand (ดู Calculate Power/Current)
const cp = String(msg.payload || "").trim();

// ถอดสาย/error -> reset ทุกอย่าง (ทำก่อนเช็ค arch2 เสมอ = fail-safe)
if (cp === "state_a" || cp === "state_e" || cp === "state_f") {
    global.set("autoAuthSent2", false);
    global.set("startCommanded2", false);
    // FIX#SELFSTOP rev1: ถอดสาย/fault = จบรอบเสียบ -> ปลด latch ทุกตัว พร้อมรับคันใหม่
    global.set("socHold2", false);
    global.set("manualStop2", false);
    global.set("idleStopSent2", false);
    node.status({ fill: "grey", shape: "ring", text: "idle (" + cp + ")" });
    return null;
}

if (global.get("arch2Enabled") !== true) return null;
if (cp !== "state_b") return null;

// ===== FIX#AUTHBOUNCE rev1 (09 พ.ย. 2026): CP เด้ง b->a->b ตอนเสียบ (log 20:32:48 ห่าง 1.3 วิ) ทำให้ token ถูกส่งซ้ำ 2 ครั้ง
// ใน 0.6 วิ -> vSECC ตีความ token ซ้ำเป็น DEAUTHORIZE (ALLOWED -> NOT_ALLOWED) -> รถค้าง ContractAuthentication
// -> ไม่ส่ง token ซ้ำภายใน 2.5 วิ (ถ้าค้างจริง FIX#AUTHWD watchdog จะส่งใหม่ให้เองหลัง 3 วิ)
if (Date.now() - (Number(global.get("autoAuthTs2")) || 0) < 2500) {
    node.status({ fill: "yellow", shape: "ring", text: "token sent <2.5s ago (CP bounce) -> skip" });
    return null;
}

// ===== FIX#SELFSTOP rev1: AUTOSTART (plug-and-charge) =====
// เดิม: authorize อัตโนมัติแต่กั๊ก 0 A รอ topic/RemoteStart -> ถ้าไม่มีใครกด ก็โดน
// idle timeout ตัดที่ 120 วิ แล้วรถ retry วนไปเรื่อย (log ตู้นี้: session 162/117 วิ + ค้าง 0 A ยาว)
// ใหม่: เสียบสายแล้วสั่งชาร์จเลย ยกเว้นติด latch:
//   socHold2    = ตัดที่ 90% ไปแล้วในรอบเสียบนี้ (ห้ามชาร์จต่อจนกว่าจะถอดสาย)
//   manualStop2 = ผู้ใช้กดหยุดเอง (ปุ่ม DIN8 / หน้าจอ) -> ต้องถอดสายหรือกด Start ใหม่
const AUTOSTART = false;  // rev1.1 (21 ส.ค.): ไซต์นี้ต้องกดปุ่ม Start บนจอก่อนจ่ายไฟ (แจ้งจากหน้างาน) | true = plug-and-charge
if (AUTOSTART && global.get("socHold2") !== true && global.get("manualStop2") !== true
    && global.get("startCommanded2") !== true) {
    global.set("startCommanded2", true);
    node.warn("H2: ARCH2 AUTOSTART -> ปลดกั๊ก 0 A ทันทีที่เสียบสาย (limit ส่งใหม่ภายใน 1 วิ)");
}

const auth = String(global.get("auth_state_head2") || "pending");
if (auth === "authorized") { node.status({fill:"green",shape:"dot",text:"already authorized"}); return null; }
if (global.get("autoAuthSent2") === true) { node.status({fill:"blue",shape:"ring",text:"token sent"}); return null; }

global.set("autoAuthSent2", true);
global.set("autoAuthTs2", Date.now());   // FIX#AUTHBOUNCE / FIX#AUTHWD
node.warn("H2: ARCH2 auto-authorize ตอนเสียบสาย");
node.status({ fill: "yellow", shape: "dot", text: "auto add_token" });
return { payload: { auto: true, cp_state: cp } };

const state = String(msg.payload || "").trim();
const prev  = global.get("auth_state_head2") || "pending";
global.set("auth_state_head2", state);
node.status({ fill: state === "authorized" ? "green" : "grey", shape: "dot", text: state || "-" });

// ขอบขาขึ้นเข้าสู่ authorized -> ให้ตัว reinit ตัดสินใจทันที ไม่ต้องรอ timer
if (state === "authorized" && prev !== "authorized") return msg;
return null;

const state = String(msg.payload || "").trim();
global.set("session_state_head2", state);

const DEAD = /(SessionStop|Terminate|Stopped|Finished|WeldingDetection)/i;
const isDead = (state === "" || DEAD.test(state));

// เห็น session ที่มีชีวิตจริง -> ตั้งธง เพื่อแยก "ยังไม่เริ่ม" ออกจาก "เริ่มแล้วตาย"
if (!isDead) global.set("sessionSeen2", true);

node.status({ fill: isDead ? "red" : "green", shape: "dot", text: state || "(empty)" });
return msg;

// คำสั่งชาร์จจาก OCPP มาถึงแล้ว -> ปลดล็อกกระแส
global.set("startCommanded2", true);
global.set("manualStop2", false);   // FIX#SELFSTOP rev1: ผู้ใช้สั่ง Start เอง -> ปลด latch หยุดมือ
node.warn("H2: START COMMANDED -> ปลดกั๊ก 0 A (limit จะถูกส่งใหม่ภายใน 1 วิ)");
node.status({ fill: "green", shape: "dot", text: "start commanded @ " + new Date().toISOString() });
return { payload: "recalc" };   // v18: เด้ง Calculate + publisher ทันที ไม่รอ tick 1 วิ

global.set("startCommanded2", false);
node.warn("H2: กลับไปกั๊ก 0 A");
return { payload: "recalc" };   // v18: เด้ง Calculate + publisher ทันที ไม่รอ tick 1 วิ

// กั๊ก 0 A ได้ไม่จำกัดในทางเทคนิค (ทดสอบแล้ว 5 นาที 44 วิ ไม่มี error)
// แต่ตอนกั๊ก: คอนแทกเตอร์ปิด HV อยู่บนสาย OCPP transaction เปิดค้าง
// -> ต้องมีเพดาน ถ้าลูกค้าเดินหนีไป
const HOLD_TIMEOUT_MS = 120000;   // 2 นาที

if (global.get("arch2Enabled") !== true) { node.status({fill:"grey",shape:"ring",text:"ARCH2 OFF"}); return null; }

const cp    = String(global.get("cp_state2") || "");
const sess  = String(global.get("session_state_head2") || "");
const start = global.get("startCommanded2") === true;
const now   = Date.now();

if (cp !== "state_b" && cp !== "state_c" && cp !== "state_d") {
    global.set("holdStart2", false); global.set("idleStopSent2", false);
    node.status({fill:"grey",shape:"ring",text:"no EV"});
    return null;
}
if (start) {
    global.set("holdStart2", false);
    node.status({fill:"green",shape:"dot",text:"charging"});
    return null;
}
if (!/current[_\s-]?demand/i.test(sess)) {
    global.set("holdStart2", false);
    node.status({fill:"blue",shape:"ring",text:"รอ | " + (sess || cp)});
    return null;
}

if (!global.get("holdStart2")) global.set("holdStart2", now);
const t = Math.round((now - global.get("holdStart2")) / 1000);

if (t * 1000 >= HOLD_TIMEOUT_MS) {
    if (global.get("idleStopSent2") === true) return null;
    global.set("idleStopSent2", true);
    node.warn("H2: กั๊ก 0 A ครบ " + t + "s ไม่มี RemoteStart -> stop_charging (รถต้องถอดสายเสียบใหม่)");
    node.status({fill:"red",shape:"dot",text:"idle timeout -> stop"});
    return { payload: "1" };
}
node.status({fill:"yellow",shape:"dot",text:"HOLD 0A " + t + "/" + (HOLD_TIMEOUT_MS/1000) + "s"});
return null;

// ===== FIX#AUTHWD rev1 (09 พ.ย. 2026): ARCH2 authorization watchdog H2 =====
// เหตุ 09/11 20:32:48 (หัว 1): เสียบสายแล้ว CP เด้ง b -> a -> b ภายใน 1.3 วิ ทำให้ add_token ถูกส่ง 2 ครั้งใน 0.6 วิ
//   -> vSECC ตีความ token ซ้ำเป็น DEAUTHORIZE (log: Charging Permission ALLOWED -> NOT_ALLOWED ห่าง 140 ms)
//   -> auth_state_head2 ใน Node-RED ค้างเป็น "authorized" -> Create Token Payload ไม่ยอมส่ง token ใหม่
//   -> รถค้าง ContractAuthentication ("Authorization still pending") 75 วิ จนถอดสาย = "หัว 1 ชาร์จไม่ได้"
// แก้: ถ้า session ค้างอยู่ที่ ContractAuthentication/Authorization เกิน AUTH_STUCK_MS ทั้งที่รถยังเสียบอยู่
//   ถือว่า vSECC ไม่ได้ authorize จริง (ถ้า authorize แล้ว vSECC จะไป ChargeParameterDiscovery ภายใน <1 วิ)
//   -> ตั้ง auth_state_head2 = "pending" แล้วส่ง token ใหม่ผ่าน "Create Token Payload" (ทุก RESEND_MS, สูงสุด MAX_RESEND ครั้ง/รอบเสียบ)
// ทำงานร่วมกับ FIX#AUTHBOUNCE ใน "ARCH2: Auto-Authorize on Plug-In H2" (ไม่ส่ง token ซ้ำภายใน 2.5 วิ)
const N = 2;
const AUTH_STUCK_MS = 3000;
const RESEND_MS = 5000;
const MAX_RESEND = 5;

if (global.get("arch2Enabled") !== true) { node.status({ fill: "grey", shape: "ring", text: "ARCH2 OFF" }); return null; }

const cp   = String(global.get("cp_state" + N) || "");
const sess = String(global.get("session_state_head" + N) || "");
const auth = String(global.get("auth_state_head" + N) || "pending");
const now  = Date.now();

if (cp !== "state_b" && cp !== "state_c" && cp !== "state_d") {
    context.set("stuckSince", 0); context.set("resends", 0);
    node.status({ fill: "grey", shape: "ring", text: "no EV" });
    return null;
}
const inAuth = /ContractAuthentication|PaymentDetails|Authorization/i.test(sess) && !/ChargeParameterDiscovery|CableCheck|PreCharge|CurrentDemand/i.test(sess);
if (!inAuth) {
    context.set("stuckSince", 0);
    if (auth === "authorized") context.set("resends", 0);
    node.status({ fill: "green", shape: "dot", text: (sess || cp) + " | auth=" + auth });
    return null;
}
let since = Number(context.get("stuckSince")) || 0;
if (!since) { since = now; context.set("stuckSince", since); }
const waited = now - since;
const resends = Number(context.get("resends")) || 0;
const lastTok = Number(global.get("autoAuthTs" + N)) || 0;

if (waited < AUTH_STUCK_MS || (now - lastTok) < RESEND_MS) {
    node.status({ fill: "yellow", shape: "ring", text: "auth pending " + Math.round(waited / 1000) + "s (auth=" + auth + ")" });
    return null;
}
if (resends >= MAX_RESEND) {
    node.status({ fill: "red", shape: "dot", text: "auth stuck " + Math.round(waited / 1000) + "s, resend limit reached" });
    return null;
}
context.set("resends", resends + 1);
global.set("auth_state_head" + N, "pending");          // ปลด guard ใน Create Token Payload (สถานะ authorized เดิมไม่จริงแล้ว)
global.set("autoAuthSent" + N, true);
global.set("autoAuthTs" + N, now);
node.warn("H" + N + ": FIX#AUTHWD session ค้าง " + sess + " " + Math.round(waited / 1000) + " วิ (auth_state เดิม=" + auth
    + ") -> ส่ง add_token ใหม่ ครั้งที่ " + (resends + 1) + "/" + MAX_RESEND);
node.status({ fill: "orange", shape: "dot", text: "re-send token #" + (resends + 1) + " @ " + Math.round(waited / 1000) + "s" });
return { payload: { auto: true, watchdog: true, cp_state: cp, session_state: sess } };

msg.payload = { source_address: msg.payload.source_address, quantity: msg.payload.data[2]}
msg.topic = "System information"
msg.can_id = 0x02
return msg;

const buf = Buffer.from(msg.payload.data);
msg.payload["output_voltage"] = buf.readFloatBE(0);
msg.payload["output_current"] = buf.readFloatBE(4);
return msg;

msg.payload = { source_address: msg.payload.source_address, on: msg.payload.data[0]}
msg.topic = "Operational readiness"
msg.can_id = 0x1A
return msg;

let temp_sign_neg = msg.payload.data[4] & 0x80
let temp_value = msg.payload.data[4] & 0x7F
if (temp_sign_neg) {
    temp_value = -1 * temp_value
}

msg.payload = { source_address: msg.payload.source_address, group: msg.payload.data[2], temperature: temp_value, status_2: msg.payload.data[5], status_1: msg.payload.data[6], status_0: msg.payload.data[7] }
msg.topic = "Module status"
msg.can_id = 0x04
return msg;

let voltage = (msg.payload.data[3] | msg.payload.data[2] << 8 | msg.payload.data[1] << 16 | msg.payload.data[0] << 24) / 1000
let current = (msg.payload.data[7] | msg.payload.data[6] << 8 | msg.payload.data[5] << 16 | msg.payload.data[4] << 24) / 1000
msg.payload = { source_address: msg.payload.source_address, output_voltage: voltage, output_current: current }
msg.topic = "Set system output power"
msg.can_id = 0x1B
return msg;

let output_voltage = (msg.payload.data[1] | msg.payload.data[0] << 8) / 10
let max_current_available = (msg.payload.data[3] | msg.payload.data[2] << 8) / 10
msg.payload = { source_address: msg.payload.source_address, output_voltage: output_voltage, max_current_available: max_current_available }
msg.topic = "Set output power"
msg.can_id = 0x0C
return msg;

msg.payload = { source_address: msg.payload.source_address, output_voltage: [msg.payload.data[0], msg.payload.data[1], msg.payload.data[2], msg.payload.data[3]], output_current: [msg.payload.data[4], msg.payload.data[5], msg.payload.data[6], msg.payload.data[7]] }
msg.topic = "Module information"
msg.can_id = 0x03
return msg;

let voltage = (msg.payload.data[3] | msg.payload.data[2] << 8 | msg.payload.data[1] << 16 | msg.payload.data[0] << 24) / 1000
let current = (msg.payload.data[7] | msg.payload.data[6] << 8 | msg.payload.data[5] << 16 | msg.payload.data[4] << 24) / 1000
msg.payload = { source_address: msg.payload.source_address, output_voltage: voltage, output_current: current }
msg.topic = "Set system output power"
msg.can_id = 0x1C
return msg;

/**
 * parse_tonhe_can   [REV: TONHE-BHUTAN-2, 09 พ.ย. 2026]  (แทน parse_sinexcel_can)
 *   rev2: เพิ่ม capable_count / capable_mask_low (online และไม่ใช่ fault-OFF) ให้ Head/Group V/I แบ่งกระแสตามโมดูลที่ใช้งานได้จริง
 * ถอดรหัสเฟรม CAN จาก Tonhe charging module ตาม "Communication protocol between charging modules
 * and monitors V1.3" (29-bit extended, little-endian, monitor = 0xA0, module SA = address 1..240)
 *
 * คง contract ปลายทางเดิมของ flow นี้ทุกประการ (ชื่อ global ยังเป็น sinexcel_* เพื่อไม่ต้องแก้
 * Head/Group V/I, Calculate Power/Current, pep_ws, External Fault MQTT, Monitor):
 *   global 'sinexcel_state' = {
 *     groups: { "1": { modules: { "1": {...}, "2": {...} }, online_mask_low, online_mask_high,
 *                      online_count, capable_mask_low, capable_count, last_voltage, last_current,
 *                      present_addresses, capable_addresses, missing_addresses }, "2": {...} },
 *     unmapped: { "<CAN addr>": ts }      // โมดูลที่ตั้ง address ไม่ตรง config (ตั้งผิด/ซ้ำ)
 *   }
 *   key ของ modules = ลำดับโมดูลในกลุ่ม (1..n) เหมือนเดิม; CAN address จริงเก็บใน field addr
 *   (mapping มาจาก sinexcel_cfg.tonhe.group_addr เช่น {1:[1,2], 2:[5,6]})
 *   ส่งออก payload { source_address:"<group>", output_voltage(avg ของโมดูลที่ ON), output_current(sum),
 *                   module_subaddr, module_addr, message_id:0x0205 (synthetic), error_type:0xF0 }
 *   เฉพาะเมื่อมีค่าวัดใหม่ (status frame) -> switch group -> pm.measured_voltage/current(2)
 *
 * Tonhe uplink (PS = 0xA0 monitor, SA = module address):
 *   PF 0x01  ID 0x1801A0xx  status  : b0 state 00=OFF 01=ON 11=fault-OFF | b1-2 Vout u16LE 0.1 V
 *                                     | b3-4 Iout u16LE 0.01 A | b5-6 fault word u16LE | b7 PFC fault u8
 *   PF 0x02  ID 0x0802A0xx  confirm : b0 0x01 = รับคำสั่ง start/stop เฉพาะตัว (0x0806) แล้ว
 *   PF 0x0B  ID 0x180BA0xx  AC info : Va, Vb, Vc u16LE 0.1 V | ambient temp i16LE degC
 *   PF 0x91  ID 0x1C91A0xx  ext     : status word u16LE | fault word u16LE | 4 byte reserved
 */

const cfg = global.get('sinexcel_cfg') || {};
const th  = cfg.tonhe || {};
const MON = (th.monitor_addr !== undefined) ? (Number(th.monitor_addr) & 0xFF) : 0xA0;
const GROUP_ADDR = th.group_addr || { 1: [1, 2], 2: [5, 6] };
const freshnessMs = Number(cfg.measure_fresh_ms ?? 2000);   // ค่าวัดที่ยังนับรวมใน aggregate
const onlineMs    = Number(th.online_ms ?? 3000);           // โมดูล "online" ถ้ามีเฟรมใด ๆ ภายในเวลานี้

if (!msg.payload || msg.payload.canid === undefined || msg.payload.data === undefined) {
    return null;
}

const canid = (Number(msg.payload.canid) >>> 0) & 0x1FFFFFFF;
const PF = (canid >>> 16) & 0xFF;
const PS = (canid >>> 8) & 0xFF;      // destination address
const SA = canid & 0xFF;              // source = module address

// รับเฉพาะเฟรมที่โมดูลส่งถึง monitor (กัน echo เฟรม TX ของเราเองที่ PS = addr/0xFF, SA = 0xA0)
if (PS !== MON) return null;
if (SA === MON) return null;

let d = msg.payload.data;
if (!Buffer.isBuffer(d)) d = Buffer.from(d);
if (d.length < 8) { const t = Buffer.alloc(8, 0); d.copy(t, 0, 0, d.length); d = t; }

const now = Date.now();
let state = global.get('sinexcel_state') || { groups: {} };
if (!state.groups) state.groups = {};
if (!state.unmapped) state.unmapped = {};

// map CAN address -> (group, ลำดับในกลุ่ม)
let group = 0, subaddr = 0;
for (const gk of Object.keys(GROUP_ADDR)) {
    const idx = (GROUP_ADDR[gk] || []).map(Number).indexOf(SA);
    if (idx >= 0) { group = Number(gk); subaddr = idx + 1; break; }
}
if (!group) {
    // address ที่ไม่อยู่ใน config -> จดไว้ให้ Tonhe Fault Monitor ฟ้อง (ตั้ง address หน้าโมดูลผิด)
    state.unmapped[String(SA)] = now;
    global.set('sinexcel_state', state);
    node.status({ fill: 'yellow', shape: 'ring', text: 'unmapped Tonhe addr ' + SA + ' (PF 0x' + PF.toString(16) + ')' });
    return null;
}

function ensureGroup(g) {
    const key = String(g);
    if (!state.groups[key]) state.groups[key] = { modules: {}, last_voltage: 0, last_current: 0 };
    if (!state.groups[key].modules) state.groups[key].modules = {};
    return state.groups[key];
}
const g = ensureGroup(group);
const mkey = String(subaddr);
if (!g.modules[mkey]) g.modules[mkey] = {};
const m = g.modules[mkey];
m.addr = SA;
m.ts_any = now;

let updatedMeasurement = false;

if (PF === 0x01) {
    // ---- Charging module status (M_C_1) ----
    m.state      = d.readUInt8(0);               // 0x00 OFF / 0x01 ON / 0x11 fault-OFF
    m.voltage    = d.readUInt16LE(1) / 10.0;     // V
    m.current    = d.readUInt16LE(3) / 100.0;    // A
    m.fault_bits = d.readUInt16LE(5);            // bit0..15 (ดูตาราง Tonhe Fault Monitor)
    m.pfc_bits   = d.readUInt8(7);               // bit0..7
    m.ts_voltage = now; m.ts_current = now; m.ts_status = now;
    if (m.fault_bits || m.pfc_bits || m.state === 0x11) m.ts_fault = now;
    updatedMeasurement = true;
} else if (PF === 0x02) {
    // ---- Confirm start/stop (M_C_2) ----
    m.confirm = d.readUInt8(0); m.ts_confirm = now;
} else if (PF === 0x0B) {
    // ---- AC input / ambient (M_C_3) ----
    m.va = d.readUInt16LE(0) / 10.0;
    m.vb = d.readUInt16LE(2) / 10.0;
    m.vc = d.readUInt16LE(4) / 10.0;
    m.ambient_c = d.readInt16LE(6);
    m.ts_ac = now;
} else if (PF === 0x91) {
    // ---- Extended status / fault (M_C_4) ----
    m.ext_status = d.readUInt16LE(0);
    m.ext_fault  = d.readUInt16LE(2);
    m.ts_ext = now;
} else {
    global.set('sinexcel_state', state);
    return null;
}

// ---- online mask (bit = ลำดับโมดูลในกลุ่ม 1..n, bit0 reserved เหมือน Sinexcel) + capable/missing/present ----
const addrs = (GROUP_ADDR[group] || GROUP_ADDR[String(group)] || []).map(Number);
let maskLow = 0, capMask = 0, capCnt = 0;
const present = [], missing = [], capable = [];
for (let s = 1; s <= addrs.length; s++) {
    const mm = g.modules[String(s)];
    const fresh = !!(mm && mm.ts_any && (now - mm.ts_any) <= onlineMs);
    if (fresh) { maskLow |= (1 << s); present.push(addrs[s - 1]); }
    else missing.push(addrs[s - 1]);
    // "capable" = online และไม่ได้อยู่สถานะ fault-OFF (0x11) -> ใช้แบ่งกระแส (FIX#DYNSHARE rev1)
    if (fresh && mm.state !== 0x11) { capMask |= (1 << s); capCnt++; capable.push(addrs[s - 1]); }
}
g.online_mask_low  = maskLow >>> 0;
g.online_mask_high = 0;
g.online_count     = present.length;
g.capable_mask_low = capMask >>> 0;
g.capable_count    = capCnt;
g.present_addresses = present;
g.capable_addresses = capable;
g.missing_addresses = missing;
g.ts_update = now;

global.set('sinexcel_state', state);

if (!updatedMeasurement) return null;

// ---- aggregate ของกลุ่ม: V = เฉลี่ยเฉพาะโมดูลที่ ON (ถ้าไม่มีตัวไหน ON ใช้ทุกตัวที่ fresh), I = ผลรวม ----
// (ต่างจาก Sinexcel: โมดูล Tonhe ที่ OFF ยังส่ง status มา ถ้าเอา 0 V ของตัวที่ดับมาเฉลี่ยจะทำให้
//  EVSEPresentVoltage ต่ำกว่าจริง)
let vOnSum = 0, vOnCnt = 0, vAllSum = 0, vAllCnt = 0, iSum = 0;
for (const mod of Object.values(g.modules)) {
    const vFresh = mod.ts_voltage && (now - mod.ts_voltage) <= freshnessMs && typeof mod.voltage === 'number';
    if (vFresh) {
        vAllSum += mod.voltage; vAllCnt++;
        if (mod.state === 0x01) { vOnSum += mod.voltage; vOnCnt++; }
    }
    if (mod.ts_current && (now - mod.ts_current) <= freshnessMs && typeof mod.current === 'number') {
        iSum += mod.current;
    }
}
const vAgg = (vOnCnt > 0) ? (vOnSum / vOnCnt) : (vAllCnt > 0 ? (vAllSum / vAllCnt) : (g.last_voltage || 0));
const iAgg = iSum;
g.last_voltage = vAgg;
g.last_current = iAgg;
global.set('sinexcel_state', state);

node.status({ fill: (m.state === 0x11 || m.fault_bits || m.pfc_bits) ? 'red' : (m.state === 0x01 ? 'green' : 'grey'),
    shape: 'dot',
    text: 'G' + group + ' ' + vAgg.toFixed(1) + 'V ' + iAgg.toFixed(1) + 'A | addr' + SA
        + ' st=0x' + m.state.toString(16) + (m.fault_bits ? ' F=0x' + m.fault_bits.toString(16) : '')
        + (m.pfc_bits ? ' PFC=0x' + m.pfc_bits.toString(16) : '') });

msg.payload = {
    source_address: String(group),
    output_voltage: vAgg,
    output_current: iAgg,
    module_subaddr: subaddr,
    module_addr: SA,
    module_state: m.state,
    message_id: 0x0205,        // synthetic เพื่อ compatibility กับปลายทางเดิม
    error_type: 0xF0
};
return msg;

/**
 * Tonhe CAN-Frame creation   [REV: TONHE-BHUTAN-2, 09 พ.ย. 2026]  (แทน Sinexcel CAN-Frame creation)
 * โหนดนี้เป็น "ผู้เขียนคนเดียว" ของคำสั่งลงบัส CAN2 (vxcan1) และเก็บสถานะคำสั่งล่าสุดของแต่ละกลุ่ม
 *
 * รับ msg.payload.cmd:
 *   'setpoint' {group, voltage, current_per_module}  <- Group N Set V/I (Tonhe)
 *                 cache V/I ของกลุ่ม; ถ้ากลุ่มอยู่สถานะ RUN -> ยิง 0x0806{addr}A0 (AA + V + I) ให้ทุกโมดูลทันที
 *   'start'    {group}   <- "# ON power modules"   : RUN=true  (ยิงเฟรมเฉพาะตอนเปลี่ยนสถานะ กันเฟรมซ้ำ)
 *   'stop'     {group}   <- "# OFF power modules"  : RUN=false (ยิง 0x55 ให้ทุกโมดูลทุกครั้ง safety-first)
 *   'refresh'  {group|0} <- Tonhe keep-alive scheduler ทุก 500 ms : ยิงคำสั่งล่าสุดซ้ำให้ทุกโมดูล
 *                           (กัน CAN timeout ของโมดูล) + timing command 0x1805FFA0 ทุก ~5 s
 *   'stop_all'           : broadcast STOP 0x0803FFA0 ไปทุก address ที่ config + RUN=false ทุกกลุ่ม
 *   'timing'             : ส่ง timing command ทันที
 *   'dump'               : พิมพ์สถานะคำสั่ง + sinexcel_state ลง debug
 *   {canid, data}        : escape hatch ส่งเฟรมดิบ
 *   payload แบบเก่า (command/message_id ของ Sinexcel/Phoenix) -> ไม่ส่งอะไร (แสดง status "ignored")
 *
 * Tonhe V1.3 downlink (29-bit ext, little-endian, SA ของเรา = monitor 0xA0):
 *   C_M_24  0x0806{addr}A0  specific start/stop + V/I : b0 0xAA start / 0x55 stop | b1 0x00 (standby mode)
 *                                                       | b2-3 V u16LE 0.1 V (0-1000 V) | b4-5 I u16LE 0.01 A | b6-7 0
 *   C_M_1   0x0803FFA0      broadcast start/stop       : b0-2 address bitmask (bit0 = addr1 .. bit23 = addr24)
 *                                                       | b3 0xAA/0x55 | b4 group<<4 | multiple (0x00) | b5-7 0
 *   C_M_3   0x1805FFA0      timing command             : 8 x 0x00 ทุก 5000 ms (โมดูลทยอยส่ง status ห่างกัน 20 ms)
 *   หมายเหตุ: ไม่ใช้ C_M_2 0x1004FFA0 (broadcast parameter) เพราะสเปคจำกัด 0-750 V
 *
 * กลไกป้องกัน:
 *   - RUN ของกลุ่มเริ่มต้นเป็น "ไม่ทราบ" หลัง deploy -> refresh จะไม่ยิง STOP จนกว่าจะมีคำสั่ง start/stop/setpoint
 *     (deploy ระหว่างชาร์จจะไม่ดับโมดูล)
 *   - start ขณะ V cache <= 0 -> ไม่ยิง (โมดูล Tonhe ที่ได้ V ต่ำกว่า min จะจ่าย "แรงดันต่ำสุดของโมดูล")
 *   - stop_below_V (default 60 V): ถ้า setpoint V ต่ำกว่านี้ (เช่น WELDDROP 30 V) ถือว่าโมดูลต้อง OFF
 *     เพราะ Tonhe จ่ายไม่ต่ำกว่า min voltage ของโมดูล -> ปล่อยให้บัสลงจริงด้วย 0x55
 */

const cfg = global.get('sinexcel_cfg') || {};
const th  = cfg.tonhe || {};
const MON = (th.monitor_addr !== undefined) ? (Number(th.monitor_addr) & 0xFF) : 0xA0;
const GROUP_ADDR = th.group_addr || { 1: [1, 2], 2: [5, 6] };
const MAXV = Number(th.max_voltage_V ?? 1000);
const MAXI = Number(th.max_current_module_A ?? cfg.module_max_current_A ?? 100);
const STOP_BELOW_V = Number(th.stop_below_V ?? 60);
const TIMING_MS = Number(th.timing_period_ms ?? 5000);
const MODE_BYTE = Number(th.mode_byte ?? 0x00) & 0xFF;   // byte1 ของ 0x0806: ตาราง 9.2.4 = 0x00 (standby), ตัวอย่าง A.2.4 ใช้ 0x01

const ID_BCAST  = ((0x08 << 24) | (0x03 << 16) | (0xFF << 8) | MON) >>> 0;   // 0x0803FFA0
const ID_TIMING = ((0x18 << 24) | (0x05 << 16) | (0xFF << 8) | MON) >>> 0;   // 0x1805FFA0
function idSpecific(addr) {                                                    // 0x0806{addr}A0
    return ((0x08 << 24) | (0x06 << 16) | ((addr & 0xFF) << 8) | MON) >>> 0;
}
function frame(canid, data) {
    return { payload: { canid: canid >>> 0, ext: true, rtr: false, dlc: 8, data: Buffer.from(data) }, topic: 'tonhe_tx' };
}
function specificFrame(addr, run, vV, iA) {
    const vRaw = Math.round(Math.max(0, Math.min(MAXV, Number(vV) || 0)) * 10);
    const iRaw = Math.round(Math.max(0, Math.min(MAXI, Number(iA) || 0)) * 100);
    const b = Buffer.alloc(8, 0);
    b.writeUInt8(run ? 0xAA : 0x55, 0);
    b.writeUInt8(MODE_BYTE, 1);                // charging mode byte (default 0x00 standby ตามตาราง 9.2.4)
    b.writeUInt16LE(vRaw & 0xFFFF, 2);
    b.writeUInt16LE(iRaw & 0xFFFF, 4);
    return frame(idSpecific(addr), b);
}
function broadcastStopFrame(addrs) {
    let mask = 0;
    for (const a of addrs) if (a >= 1 && a <= 24) mask |= (1 << (a - 1));   // bit0 = addr 1
    const b = Buffer.alloc(8, 0);
    b.writeUInt8(mask & 0xFF, 0);
    b.writeUInt8((mask >>> 8) & 0xFF, 1);
    b.writeUInt8((mask >>> 16) & 0xFF, 2);
    b.writeUInt8(0x55, 3);
    b.writeUInt8(0x00, 4);                     // group 1 (default) | address multiple 0 -> addr 1-24
    return frame(ID_BCAST, b);
}
function addrList(group) {
    const a = GROUP_ADDR[group] || GROUP_ADDR[String(group)];
    return Array.isArray(a) ? a.map(Number).filter(x => x >= 1 && x <= 240) : [];
}
function allGroups() { return Object.keys(GROUP_ADDR).map(Number).filter(Boolean); }

// สถานะคำสั่งล่าสุด (ต่อกลุ่ม): run = true/false/undefined(ไม่ทราบหลัง deploy), v, i
const st = context.get('tonhe_tx') || { run: {}, v: {}, i: {}, ts: {} };
if (!st.ts) st.ts = {};

function effectiveRun(group) {
    if (st.run[group] !== true) return false;
    const v = Number(st.v[group]) || 0;
    if (v <= 0) return false;
    if (STOP_BELOW_V > 0 && v < STOP_BELOW_V) return false;
    return true;
}
function groupFrames(group) {
    const out = [];
    if (st.run[group] === undefined) return out;          // ยังไม่ทราบสถานะ -> ไม่แตะโมดูล
    const run = effectiveRun(group);
    for (const a of addrList(group)) out.push(specificFrame(a, run, st.v[group] ?? 0, st.i[group] ?? 0));
    st.ts[group] = Date.now();
    return out;
}
function timingFrameIfDue(force) {
    const now = Date.now();
    const last = context.get('tonhe_last_timing') || 0;
    if (force || (now - last) >= TIMING_MS) {
        context.set('tonhe_last_timing', now);
        return [frame(ID_TIMING, [0, 0, 0, 0, 0, 0, 0, 0])];
    }
    return [];
}

const p = (msg.payload && typeof msg.payload === 'object') ? msg.payload : {};
const cmd = p.cmd;
let group = Number(p.group ?? p.group_id ?? 0) & 0xFF;
let out = [];
let why = '';

if (cmd === 'setpoint') {
    if (!group) return null;
    st.v[group] = Math.max(0, Number(p.voltage) || 0);
    st.i[group] = Math.max(0, Number(p.current_per_module) || 0);
    if (st.run[group] !== undefined) out = out.concat(groupFrames(group));
    why = 'setpoint';
} else if (cmd === 'start') {
    if (!group) return null;
    if (!(Number(st.v[group]) > 0)) {
        node.warn('Tonhe TX: start G' + group + ' ถูกข้าม เพราะยังไม่มี setpoint V (> 0) ของกลุ่มนี้');
        return null;
    }
    const was = st.run[group];
    st.run[group] = true;
    if (was !== true) out = out.concat(groupFrames(group));   // ยิงเฉพาะตอนเปลี่ยนสถานะ (setpoint/refresh ยิงต่อเอง)
    why = 'start';
} else if (cmd === 'stop') {
    if (!group) return null;
    st.run[group] = false;
    out = out.concat(groupFrames(group));                     // ยิง 0x55 ทุกครั้ง
    why = 'stop';
} else if (cmd === 'refresh') {
    const groups = group ? [group] : allGroups();
    for (const gq of groups) out = out.concat(groupFrames(gq));
    out = out.concat(timingFrameIfDue(false));
    why = 'refresh';
} else if (cmd === 'stop_all') {
    const addrs = [];
    for (const gq of allGroups()) { st.run[gq] = false; addrs.push(...addrList(gq)); }
    out.push(broadcastStopFrame(addrs));
    for (const gq of allGroups()) out = out.concat(groupFrames(gq));
    node.warn('Tonhe TX: STOP ALL -> addr ' + addrs.join(','));
    why = 'stop_all';
} else if (cmd === 'timing') {
    out = out.concat(timingFrameIfDue(true));
    why = 'timing';
} else if (cmd === 'dump') {
    node.warn({ tonhe_tx: st, sinexcel_state: global.get('sinexcel_state'), tonhe_cfg: th });
    return null;
} else if (p.canid !== undefined && p.data !== undefined && cmd === undefined && p.command === undefined && p.message_id === undefined) {
    out.push(frame(Number(p.canid) >>> 0, p.data));
    why = 'raw';
} else {
    // payload แบบ Sinexcel / Phoenix เดิม (command, message_id ...) -> ไม่มีความหมายกับ Tonhe
    node.status({ fill: 'grey', shape: 'ring', text: 'ignored legacy payload: ' + JSON.stringify(p).slice(0, 60) });
    return null;
}

context.set('tonhe_tx', st);
global.set('tonhe_tx_state', { run: st.run, v: st.v, i: st.i, ts: st.ts, last_cmd: why, updated: Date.now() });   // ให้ Fault Monitor/heartbeat อ่าน

// node.status สรุปสถานะทุกกลุ่ม
const parts = [];
for (const gq of allGroups()) {
    const r = st.run[gq];
    parts.push('G' + gq + ' ' + (r === undefined ? '?' : (effectiveRun(gq) ? 'RUN' : 'STOP'))
        + ' ' + (Number(st.v[gq]) || 0).toFixed(0) + 'V/' + (Number(st.i[gq]) || 0).toFixed(1) + 'A x' + addrList(gq).length);
}
node.status({ fill: Object.values(st.run).some(r => r === true) ? 'green' : 'grey', shape: 'dot',
    text: parts.join(' | ') + ' [' + why + (out.length ? ' ' + out.length + 'f' : '') + ']' });

if (out.length === 0) return null;
return [out];

// Group 1 Set V/I (Tonhe)   [REV: TONHE-BHUTAN-2, 09 พ.ย. 2026]  (แทน Group 1 Set V/I (Sinexcel))
// รับ {TargetVoltage, TargetCurrent (รวมทั้งกลุ่ม)} จาก Head 1 V/I -> แบ่งกระแสต่อโมดูล
// -> ส่งคำสั่ง {cmd:'setpoint'} ให้ "Tonhe CAN-Frame creation" ซึ่งจะยิง 0x0806{addr}A0 (AA + V + I)
//    ให้ทุกโมดูลในกลุ่ม เฉพาะเมื่อกลุ่มอยู่ในสถานะ RUN (สั่งโดย "# ON / # OFF power modules")
// Tonhe: V 0.1 V/bit (0-1000 V), I 0.01 A/bit ต่อโมดูล  -> ไม่มีสูตร 1024*(I/20) ของ Sinexcel อีกแล้ว

const GROUP = 1;
const cfg = global.get('sinexcel_cfg') || {};
const th  = cfg.tonhe || {};

function getOnlineCount(group) {
    // FIX#DYNSHARE rev1 (09 พ.ย. 2026): นับเฉพาะโมดูลที่ "ใช้งานได้จริง" (online และไม่ใช่ fault-OFF 0x11)
    // ถ้า parse ยังไม่ให้ capable_count (เวอร์ชันเก่า) ค่อยถอยไปใช้ online mask เดิม
    const st = global.get('sinexcel_state') || {};
    const g = st.groups && st.groups[String(group)];
    if (!g) return 0;
    if (typeof g.capable_count === 'number') return g.capable_count;
    const low = (g.online_mask_low >>> 0) || 0;
    let cnt = 0;
    for (let i = 1; i < 32; i++) if (low & (1 << i)) cnt++;   // bit i = โมดูลลำดับที่ i ในกลุ่ม
    return cnt;
}

let voltage = Number(msg.payload?.TargetVoltage ?? 0);
let currentTotal = Number(msg.payload?.TargetCurrent ?? 0);
if (!Number.isFinite(voltage)) voltage = 0;
if (!Number.isFinite(currentTotal)) currentTotal = 0;

// จำนวนโมดูลที่แบ่งกระแสกัน: ใช้จำนวนที่ online จริง ถ้ายังไม่เห็นเลยใช้จำนวนที่ config
const online = getOnlineCount(GROUP);
let fallbackCount = 1;
if (cfg.group_module_count && (cfg.group_module_count[GROUP] !== undefined || cfg.group_module_count[String(GROUP)] !== undefined)) {
    fallbackCount = Number(cfg.group_module_count[GROUP] ?? cfg.group_module_count[String(GROUP)]);
} else if (th.group_addr && Array.isArray(th.group_addr[GROUP] || th.group_addr[String(GROUP)])) {
    fallbackCount = (th.group_addr[GROUP] || th.group_addr[String(GROUP)]).length;
} else if (cfg.group_modules && Array.isArray(cfg.group_modules[GROUP])) {
    fallbackCount = cfg.group_modules[GROUP].length;
}
if (!Number.isFinite(fallbackCount) || fallbackCount < 1) fallbackCount = 1;

const n = (online > 0) ? online : fallbackCount;
let perModule = (n > 0) ? (currentTotal / n) : 0;

// ===== clamp กันเกินพิกัด (คงแนวทาง FIX 13 ส.ค.) =====
const MOD_MAX_I = Number(th.max_current_module_A ?? cfg.module_max_current_A) || 100;
const MAX_SET_V = Number(th.max_voltage_V) || 1000;
if (voltage > MAX_SET_V) { node.warn('G' + GROUP + ': clamp setpoint V ' + voltage.toFixed(1) + ' -> ' + MAX_SET_V); voltage = MAX_SET_V; }
if (voltage < 0) voltage = 0;
if (perModule > MOD_MAX_I) { node.warn('G' + GROUP + ': clamp I/module ' + perModule.toFixed(1) + ' -> ' + MOD_MAX_I + ' A (n=' + n + ')'); perModule = MOD_MAX_I; }
if (perModule < 0) perModule = 0;

node.status({ fill: (voltage > 0) ? 'green' : 'grey', shape: 'dot',
    text: 'G' + GROUP + ' set ' + voltage.toFixed(1) + 'V ' + perModule.toFixed(1) + 'A/module x' + n + (online ? '' : ' (cfg)') });

msg.payload = {
    cmd: 'setpoint',
    group: GROUP,
    voltage: voltage,
    current_per_module: perModule,
    current_total: currentTotal,
    modules_online: online,
    modules_used: n
};
msg.topic = 'tonhe_setpoint_g' + GROUP;
return msg;

global.set("pm.measured_voltage",msg.payload.output_voltage);
global.set("pm.measured_current", msg.payload.output_current);
return msg;

// EVSE min/max limits shown to the EV over CCS.
// There is no separate cabinet-wide power cap in this flow.
// Power limits are derived only from the installed module topology, while
// optional per-head HMI/MQTT soft limits are still applied at runtime.
//
// ===== [REV: TONHE-BHUTAN-3, 10 พ.ย. 2026] เปลี่ยน Power Module จาก Sinexcel SER100040K3B -> Tonhe 30 kW =====
//   rev3: เพิ่ม pcap_v_source / noload_* (ใช้ใน Calculate Power/Current: FIX#PCAPV, FIX#NOLOAD rev2, FIX#SHARE rev2)
// Power Module topology (Tonhe, 2 + 2 x 30 kW = 120 kW):
//   Connector 1 -> Group 1 -> Tonhe CAN address 1, 2   (หน้าจอโมดูล 01H, 02H)
//   Connector 2 -> Group 2 -> Tonhe CAN address 3, 4   (หน้าจอโมดูล 03H, 04H)
//   [REV TONHE-BHUTAN-2 09/11/2026] เดิม config ไว้ 5,6 ตามเอกสาร แต่ log CAN 20:25-20:40 พบโมดูลตอบที่ address 3,4
//   และไม่มี 5,6 เลย -> หัว 2 ไม่เคยถูกสั่งงาน -> รถหัว 2 ได้กระแสครึ่งเดียว (G1 รับส่วนแบ่ง 2/4 ส่วน G2 จ่าย 0)
//   ถ้าช่างตั้ง address หน้าโมดูลใหม่เป็น 5,6 ให้แก้ group_addr ด้านล่างกลับ (Tonhe Fault Monitor จะฟ้อง 'address not in config' ถ้าไม่ตรง)
//   ทุกโมดูล: Group number G01, Running mode -A- (Automatic), Group mode -F- (Fixed), Protocol P02 (Tonhe)
//   CAN2 (vxcan1) 125 kbit/s เท่า Sinexcel เดิม -> ไม่ต้องแก้ baud rate ใน vSECC web UI
// ชื่อ global ยังคงเป็น sinexcel_cfg / sinexcel_state เพื่อไม่ต้องแก้โหนดปลายทาง (Head/Group V/I, Calculate,
// pep_ws, External Fault MQTT, Monitor) -> ส่วนของ Tonhe อยู่ในฟิลด์ cfg.tonhe
const MODULES_G1 = 2;
const MODULES_G2 = 2;
const TOTAL_MODULES = MODULES_G1 + MODULES_G2;
const MODULE_MAX_POWER   = 30000;   // 30 kW/module  <- ตรวจกับ nameplate ของโมดูล Tonhe ที่ติดตั้งจริง
const MODULE_MAX_CURRENT = 100;     // A/module (30 kW ที่ 300 V)  <- ตรวจกับ nameplate
const MODULE_MAX_VOLTAGE = 1000;    // V (ช่วงเฟรม 0x0806 = 0-1000 V)  <- ตรวจกับ nameplate (รุ่น 750 V ให้แก้เป็น 750)
const CURRENT_LIMIT_A    = 400;     // software current limit per connector (บัสขนาน 4 x 100 A = 400 A)
const TOTAL_PHYS_POWER   = TOTAL_MODULES * MODULE_MAX_POWER;  // 120 kW installed-module capacity

// Explicitly disable and clear the former cabinet ceiling so a persisted
// value cannot be reused after deploying this flow.
global.set('pm.cabinet_power_limit_enabled', false);
global.set('pm.cabinet_max_power', null);
global.set('pm.installed_power', TOTAL_PHYS_POWER);

// Force the requested per-connector current setting on startup/deploy so a
// persisted value from the previous flow cannot remain active.
global.set('limitcurrent1', CURRENT_LIMIT_A);
global.set('limitcurrent2', CURRENT_LIMIT_A);

// Per-head absolute maxima (CCS signaling). When the DC buses are tied, one
// connector can use all installed modules. Calculate Power/Current reduces
// these values to the native group capacity when the buses are split.
global.set('pm.min_voltage', 0);
global.set('pm.max_voltage', MODULE_MAX_VOLTAGE);
global.set('pm.min_current', 0);
global.set('pm.max_current',  Math.min(CURRENT_LIMIT_A, TOTAL_MODULES * MODULE_MAX_CURRENT));
global.set('pm.max_current2', Math.min(CURRENT_LIMIT_A, TOTAL_MODULES * MODULE_MAX_CURRENT));
global.set('pm.min_power', 0);
global.set('pm.max_power',  TOTAL_PHYS_POWER);
global.set('pm.max_power2', TOTAL_PHYS_POWER);

// No discharge
global.set('pm.discharge_min_current', 0);
global.set('pm.discharge_max_current', 0);
global.set('pm.discharge_min_power', 0);
global.set('pm.discharge_max_power', 0);

// ================================
// Power module CAN config (Tonhe)  -- global ชื่อเดิม sinexcel_cfg
// ================================
const sinexcel_cfg = {
    pm_brand: 'tonhe',

    // How long per-module measurements stay "fresh" (aggregate V/I)
    measure_fresh_ms: 2000,

    // ลำดับโมดูลในแต่ละกลุ่ม (1..n) = key ใน sinexcel_state.groups[g].modules และ bit ของ online mask
    // (โหนดปลายทางเดิมใช้ค่านี้ ไม่ใช่ CAN address จริง)
    group_modules: {
        1: [1, 2],
        2: [1, 2]
    },
    group_module_count: {
        1: MODULES_G1,
        2: MODULES_G2
    },

    // Module specs (reference)
    module_max_current_A: MODULE_MAX_CURRENT,
    module_max_voltage_V: MODULE_MAX_VOLTAGE,
    current_limit_A: CURRENT_LIMIT_A,
    module_max_power_W: MODULE_MAX_POWER,
    total_modules: TOTAL_MODULES,
    total_power_W: TOTAL_PHYS_POWER,
    cabinet_power_limit_enabled: false,

    // ===== Calculate Power/Current (REV TONHE-BHUTAN-3) =====
    // แรงดันที่ใช้แปลงเพดานกำลัง (kW) เป็นเพดานกระแส (A) ที่ประกาศให้รถ:
    //   'measured' = แรงดันบัสจริง x1.01 ระหว่างชาร์จ (ได้กำลังเต็มพิกัดโมดูล)  | 'max' = สูตรเดิม max(แรงดันวัด, target ของรถ)
    pcap_v_source: 'measured',
    // watchdog FIX#NOLOAD (R6 ปิดแล้วไม่มีกระแส -> veto R6) และ FIX#SHARE (กลุ่มช่วยไม่จ่าย):
    noload_trip_ms: 5000,          // อาการต้องค้างต่อเนื่องอย่างน้อยเท่านี้ (เวลาจริง)
    noload_grace_charge_ms: 8000,  // ไม่ตัดสินในช่วงนี้หลังหัวนั้นเข้า charge (Tonhe ~1-2 วิ กว่ากระแสจะขึ้น)
    noload_grace_tie_ms: 4000,     // ไม่ตัดสินในช่วงนี้หลัง R6 ปิดเสร็จ

    // ================================
    // Tonhe protocol V1.3 (ใช้โดย parse_tonhe_can / Tonhe CAN-Frame creation / Set V/I / Fault Monitor)
    // ================================
    tonhe: {
        monitor_addr: 0xA0,                       // address ของ monitor (เรา) ตามสเปค
        // CAN address จริงของโมดูล เรียงตามลำดับโมดูลในกลุ่ม: G1 ลำดับ1,2 -> addr 1,2 | G2 ลำดับ1,2 -> addr 3,4
        // (ตรวจพบจริงบนบัส 09/11/2026; เอกสารตั้งค่าเดิมเขียน 5,6)
        group_addr: { 1: [1, 2], 2: [3, 4] },
        max_voltage_V: MODULE_MAX_VOLTAGE,        // clamp setpoint V
        max_current_module_A: MODULE_MAX_CURRENT, // clamp setpoint I ต่อโมดูล
        mode_byte: 0x00,                          // byte1 ของเฟรม 0x0806 (ตาราง 9.2.4 = 0x00 standby; ตัวอย่าง A.2.4 ใช้ 0x01 -> ลอง 1 ถ้าโมดูลไม่รับคำสั่ง)
        stop_below_V: 60,                         // setpoint V ต่ำกว่านี้ (เช่น WELDDROP 30 V) -> สั่ง 0x55 ให้โมดูล OFF
                                                  // เพราะ Tonhe จ่ายไม่ต่ำกว่า min voltage ของโมดูล; ตั้ง 0 เพื่อปิดกลไกนี้
        refresh_ms: 500,                          // (อ้างอิง) inject keep-alive ยิงคำสั่งล่าสุดซ้ำทุก 500 ms
        timing_period_ms: 5000,                   // timing command 0x1805FFA0 ทุก 5 s (สเปค C_M_3)
        online_ms: 3000,                          // โมดูล online ถ้ามีเฟรมภายใน 3 s (status มาทุก 500 ms)
        stale_ms: 5000,                           // Fault Monitor: เงียบเกิน 5 s = CAN silent
        unmapped_hold_ms: 15000                   // Fault Monitor: ฟ้อง address แปลกปลอมค้างไว้ 15 s
    }
};

global.set('sinexcel_cfg', sinexcel_cfg);

// ===== FIX 13 ส.ค.: ขอบเขตปุ่ม DIN8 (vsecc/io/d_in/8/value) =====
// ตาม HAL ของ vSECC DIN8 = DIGITAL_IN_8_CONNECTOR_2_STOP (ปุ่ม stop ของหัว 2)
// และ log 10-13 ส.ค. ยืนยัน PLC ยิง pulse ท้าย session หัว 2 เป็นประจำ (35 ครั้ง)
//   false (ค่าแนะนำ): DIN8 หยุดเฉพาะหัว 2 — หัว 1 ชาร์จต่อได้
//   true: DIN8 = E-stop ทั้งตู้ (พฤติกรรมเดิม) — ใช้เมื่อไซต์ต่อสาย E-stop จริงเข้า DIN8
// ===== FIX#SELFSTOP rev1 (20 ส.ค.) =====
// io-daemon HAL ตั้งชื่อ DIN8 = DIGITAL_IN_8_CONNECTOR_2_STOP (ปุ่ม stop หัว 2)
// log ตู้นี้: กดปุ่ม 15 ครั้ง -> contactor ดับทั้ง 2 หัวภายใน ~100 ms ทุกครั้ง (หัว 1 โดนลูกหลง)
// ก่อนใช้ false ให้ยืนยันหน้างานว่าปุ่ม E-stop หัวเห็ดจริงต่อ hardwired ตัด contactor/AC โดยตรง
const ESTOP_IS_GLOBAL = true;   // FIX#ESTOP-GLOBAL rev2 (09 ก.ย. 2026): true = ปุ่ม Emergency ตัดทั้งตู้ทั้ง 2 หัว
                                //   (เหมือน flow follower)  false = หยุดเฉพาะหัว 2 เท่านั้น ห้ามใช้กับตู้ที่ DIN8 คือปุ่มฉุกเฉิน
global.set('estop_is_global', ESTOP_IS_GLOBAL);
const ESTOP_DEBOUNCE_MS = 400;  // DIN8 ต้อง LOW ต่อเนื่องเท่านี้ก่อนนับเป็นการกดจริง (กรอง pulse PLC)
global.set('estop_debounce_ms', ESTOP_DEBOUNCE_MS);
// ค่าเริ่มต้นธง per-head หลัง restart (สาย stop ปกติค้าง HIGH = 1)
if (global.get('emerstop_h1') === undefined) global.set('emerstop_h1', 1);
if (global.get('emerstop_h2') === undefined) global.set('emerstop_h2', 1);
node.status({fill:"green", shape:"dot",
    text:"Tonhe 2+2 x "+(MODULE_MAX_POWER/1000)+"kW | Installed="+(TOTAL_PHYS_POWER/1000)+"kW | CurrentLimit="+CURRENT_LIMIT_A+"A | G1 addr[1,2] G2 addr[3,4]"});
return msg;

// # ON power modules (Tonhe)   [REV: TONHE-BHUTAN-1]  (เดิม: Sinexcel 0x0230/0x0232 bitmask)
// สั่งให้ "Tonhe CAN-Frame creation" ตั้งกลุ่มเป็น RUN -> ยิง 0x0806{addr}A0 (0xAA start + V/I ล่าสุด)
// ให้ทุกโมดูลในกลุ่ม (group_id จะถูกยืนยันซ้ำโดย change node "Group_1" ถัดไป)
const DEFAULT_GROUP = 1;
const group = Number(msg.payload?.group_id ?? msg.payload?.group ?? DEFAULT_GROUP) & 0x1F;
node.status({ fill: 'green', shape: 'dot', text: 'START G' + group });
msg.payload = { cmd: 'start', group: group };
msg.topic = 'tonhe_start_g' + group;
return msg;

// # OFF power modules (Tonhe)   [REV: TONHE-BHUTAN-1]  (เดิม: Sinexcel 0x0230/0x0232 mask = 0)
// สั่งให้ "Tonhe CAN-Frame creation" ตั้งกลุ่มเป็น STOP -> ยิง 0x0806{addr}A0 (0x55 stop) ให้ทุกโมดูลในกลุ่มทันที
// และ keep-alive scheduler จะยิง 0x55 ซ้ำทุก 500 ms จนกว่าจะมีคำสั่ง START ใหม่
const DEFAULT_GROUP = 1;
const group = Number(msg.payload?.group_id ?? msg.payload?.group ?? DEFAULT_GROUP) & 0x1F;
node.status({ fill: 'grey', shape: 'ring', text: 'STOP G' + group });
msg.payload = { cmd: 'stop', group: group };
msg.topic = 'tonhe_stop_g' + group;
return msg;

const buf = Buffer.from(msg.payload.data);

// อ่านค่าแรงดันจาก buffer
const ReadingoutputVoltage = buf.readFloatBE(0);

// เก็บค่าแรงดันใน global variable
global.set("ReadingoutputVoltage", ReadingoutputVoltage);

return msg;

// Group 2 Set V/I (Tonhe)   [REV: TONHE-BHUTAN-2, 09 พ.ย. 2026]  (แทน Group 2 Set V/I (Sinexcel))
// รับ {TargetVoltage, TargetCurrent (รวมทั้งกลุ่ม)} จาก Head 2 V/I -> แบ่งกระแสต่อโมดูล
// -> ส่งคำสั่ง {cmd:'setpoint'} ให้ "Tonhe CAN-Frame creation" ซึ่งจะยิง 0x0806{addr}A0 (AA + V + I)
//    ให้ทุกโมดูลในกลุ่ม เฉพาะเมื่อกลุ่มอยู่ในสถานะ RUN (สั่งโดย "# ON / # OFF power modules")
// Tonhe: V 0.1 V/bit (0-1000 V), I 0.01 A/bit ต่อโมดูล  -> ไม่มีสูตร 1024*(I/20) ของ Sinexcel อีกแล้ว

const GROUP = 2;
const cfg = global.get('sinexcel_cfg') || {};
const th  = cfg.tonhe || {};

function getOnlineCount(group) {
    // FIX#DYNSHARE rev1 (09 พ.ย. 2026): นับเฉพาะโมดูลที่ "ใช้งานได้จริง" (online และไม่ใช่ fault-OFF 0x11)
    // ถ้า parse ยังไม่ให้ capable_count (เวอร์ชันเก่า) ค่อยถอยไปใช้ online mask เดิม
    const st = global.get('sinexcel_state') || {};
    const g = st.groups && st.groups[String(group)];
    if (!g) return 0;
    if (typeof g.capable_count === 'number') return g.capable_count;
    const low = (g.online_mask_low >>> 0) || 0;
    let cnt = 0;
    for (let i = 1; i < 32; i++) if (low & (1 << i)) cnt++;   // bit i = โมดูลลำดับที่ i ในกลุ่ม
    return cnt;
}

let voltage = Number(msg.payload?.TargetVoltage ?? 0);
let currentTotal = Number(msg.payload?.TargetCurrent ?? 0);
if (!Number.isFinite(voltage)) voltage = 0;
if (!Number.isFinite(currentTotal)) currentTotal = 0;

// จำนวนโมดูลที่แบ่งกระแสกัน: ใช้จำนวนที่ online จริง ถ้ายังไม่เห็นเลยใช้จำนวนที่ config
const online = getOnlineCount(GROUP);
let fallbackCount = 1;
if (cfg.group_module_count && (cfg.group_module_count[GROUP] !== undefined || cfg.group_module_count[String(GROUP)] !== undefined)) {
    fallbackCount = Number(cfg.group_module_count[GROUP] ?? cfg.group_module_count[String(GROUP)]);
} else if (th.group_addr && Array.isArray(th.group_addr[GROUP] || th.group_addr[String(GROUP)])) {
    fallbackCount = (th.group_addr[GROUP] || th.group_addr[String(GROUP)]).length;
} else if (cfg.group_modules && Array.isArray(cfg.group_modules[GROUP])) {
    fallbackCount = cfg.group_modules[GROUP].length;
}
if (!Number.isFinite(fallbackCount) || fallbackCount < 1) fallbackCount = 1;

const n = (online > 0) ? online : fallbackCount;
let perModule = (n > 0) ? (currentTotal / n) : 0;

// ===== clamp กันเกินพิกัด (คงแนวทาง FIX 13 ส.ค.) =====
const MOD_MAX_I = Number(th.max_current_module_A ?? cfg.module_max_current_A) || 100;
const MAX_SET_V = Number(th.max_voltage_V) || 1000;
if (voltage > MAX_SET_V) { node.warn('G' + GROUP + ': clamp setpoint V ' + voltage.toFixed(1) + ' -> ' + MAX_SET_V); voltage = MAX_SET_V; }
if (voltage < 0) voltage = 0;
if (perModule > MOD_MAX_I) { node.warn('G' + GROUP + ': clamp I/module ' + perModule.toFixed(1) + ' -> ' + MOD_MAX_I + ' A (n=' + n + ')'); perModule = MOD_MAX_I; }
if (perModule < 0) perModule = 0;

node.status({ fill: (voltage > 0) ? 'green' : 'grey', shape: 'dot',
    text: 'G' + GROUP + ' set ' + voltage.toFixed(1) + 'V ' + perModule.toFixed(1) + 'A/module x' + n + (online ? '' : ' (cfg)') });

msg.payload = {
    cmd: 'setpoint',
    group: GROUP,
    voltage: voltage,
    current_per_module: perModule,
    current_total: currentTotal,
    modules_online: online,
    modules_used: n
};
msg.topic = 'tonhe_setpoint_g' + GROUP;
return msg;

// # ON power modules (Tonhe)   [REV: TONHE-BHUTAN-1]  (เดิม: Sinexcel 0x0230/0x0232 bitmask)
// สั่งให้ "Tonhe CAN-Frame creation" ตั้งกลุ่มเป็น RUN -> ยิง 0x0806{addr}A0 (0xAA start + V/I ล่าสุด)
// ให้ทุกโมดูลในกลุ่ม (group_id จะถูกยืนยันซ้ำโดย change node "Group_2" ถัดไป)
const DEFAULT_GROUP = 2;
const group = Number(msg.payload?.group_id ?? msg.payload?.group ?? DEFAULT_GROUP) & 0x1F;
node.status({ fill: 'green', shape: 'dot', text: 'START G' + group });
msg.payload = { cmd: 'start', group: group };
msg.topic = 'tonhe_start_g' + group;
return msg;

// # OFF power modules (Tonhe)   [REV: TONHE-BHUTAN-1]  (เดิม: Sinexcel 0x0230/0x0232 mask = 0)
// สั่งให้ "Tonhe CAN-Frame creation" ตั้งกลุ่มเป็น STOP -> ยิง 0x0806{addr}A0 (0x55 stop) ให้ทุกโมดูลในกลุ่มทันที
// และ keep-alive scheduler จะยิง 0x55 ซ้ำทุก 500 ms จนกว่าจะมีคำสั่ง START ใหม่
const DEFAULT_GROUP = 2;
const group = Number(msg.payload?.group_id ?? msg.payload?.group ?? DEFAULT_GROUP) & 0x1F;
node.status({ fill: 'grey', shape: 'ring', text: 'STOP G' + group });
msg.payload = { cmd: 'stop', group: group };
msg.topic = 'tonhe_stop_g' + group;
return msg;

const buf = Buffer.alloc(8);

var voltage = global.get("pep.target_voltage");
var current = global.get("pep.target_current");

voltage = voltage != undefined ? voltage : 0;
current = current != undefined ? current : 0;

buf.writeUInt32BE(Math.round(1.15*(voltage * 1000)), 0);
buf.writeUInt32BE(Math.round(current * 1000), 4);
msg.payload = { "group_id": 1, "data": [...buf], "command": 0x1B };
return msg;

global.set("pm.measured_voltage2",msg.payload.output_voltage);
global.set("pm.measured_current2", msg.payload.output_current);
return msg;

// Set the min and max values for Head 2.
// No separate cabinet limit: the default maximum is the total installed
// module capacity when the DC buses are tied.
const cfg = global.get('sinexcel_cfg') || {};
const totalModules = Number(cfg.total_modules) || 4;
const moduleMaxCurrent = Number(cfg.module_max_current_A) || 100;
const currentLimit = Number(cfg.current_limit_A) || 400;
const moduleMaxPower = Number(cfg.module_max_power_W) || 30000;
const totalPhysicalPower = Number(cfg.total_power_W) || (totalModules * moduleMaxPower);

global.set('pm.min_voltage2', 0);
global.set('pm.max_voltage2', Number(cfg.module_max_voltage_V) || 1000);
global.set('pm.min_current2', 0);
global.set('pm.max_current2', Math.min(currentLimit, totalModules * moduleMaxCurrent));
global.set('pm.min_power2', 0);
global.set('pm.max_power2', totalPhysicalPower);
// no discharge
global.set('pm.discharge_min_current2', 0);
global.set('pm.discharge_max_current2', 0);
global.set('pm.discharge_min_power2', 0);
global.set('pm.discharge_max_power2', 0);
node.status({fill:"green", shape:"dot",
    text:"Head2: max "+Math.min(currentLimit, totalModules * moduleMaxCurrent).toFixed(1)+"A / "+(totalPhysicalPower/1000)+"kW (no cabinet cap)"});

// Controls physical Group 1 modules (Tonhe: 2 x 100 A = 200 A, 2 x 30 kW = 60 kW).  [REV TONHE-BHUTAN-1]
// Serves head1 by default; helps head2 when head2 is charging alone.
// DC buses of G1 & G2 are paralleled in hardware.
//
// FIX: เมื่อ head เดียว active ทั้ง G1 และ G2 ต้องแบ่ง target_current
// ตามสัดส่วนจำนวน module เพื่อไม่ให้รวมกันเกิน target
//   G1 share = 2/4  ,  G2 share = 2/4
//
// Physical power protection only: G1 = 2 modules x 30 kW = 60 kW. No cabinet-wide cap.

var cp_head1 = global.get("cp_state_head1");
var cp_head2 = global.get("cp_state_head2");
var voltage = 0;
var current = 0;

// Module specs and installed topology (centralized in sinexcel_cfg)
const cfg = global.get("sinexcel_cfg") || {};
function getModuleCount(group, fallback) {
    if (cfg.group_modules && Array.isArray(cfg.group_modules[group]) && cfg.group_modules[group].length > 0) {
        return cfg.group_modules[group].length;
    }
    const counts = cfg.group_module_count || {};
    const n = Number(counts[group] !== undefined ? counts[group] : counts[String(group)]);
    return Number.isFinite(n) && n > 0 ? n : fallback;
}
const MODULE_MAX_CURRENT = Number(cfg.module_max_current_A) || 100;
const MODULE_MAX_POWER   = Number(cfg.module_max_power_W) || 30000;
const MODULES_GROUP_1    = getModuleCount(1, 2);
const MODULES_GROUP_2    = getModuleCount(2, 2);
const TOTAL_MODULES      = MODULES_GROUP_1 + MODULES_GROUP_2;

// Group physical power only; there is no cabinet-wide ceiling.
const G1_PHYS_POWER     = MODULES_GROUP_1 * MODULE_MAX_POWER;   // พิกัดฟิสิคัลของกลุ่ม 1 (จำนวนโมดูล x 40 kW)

// ===== FIX 16 ก.ค.: จัดสรรโมดูลต้องอิงคอนแทกเตอร์เชื่อมบัสจริง =====
// ground truth = "function 4" -> DC bypass (R6 / d_out/7)
//   ปิด  = บัส G1+G2 ขนานกัน -> โมดูลทุกกลุ่มไปช่วยหัวเดียวกันได้ (แบ่งตามสัดส่วนโมดูล)
//   เปิด = บัสแยกขาด        -> G1 ผูกหัว 1, G2 ผูกหัว 2 ตายตัว
// สูตร tie_closed ต้องเหมือน function 4 ทุกตัวอักษร ห้ามแก้ข้างเดียว
// (เดิมใช้แค่ b/c/d: อีกหัวตกไป state_e/state_f จะถูกนับว่า "ว่าง" -> หารกระแสไปอีกกลุ่ม
//  ทั้งที่บัสยังแยก -> ไฟไปไม่ถึงรถ และประกาศกำลังเกินที่จ่ายได้จริง)
var live1 = (cp_head1 === "state_b" || cp_head1 === "state_c" || cp_head1 === "state_d");
var live2 = (cp_head2 === "state_b" || cp_head2 === "state_c" || cp_head2 === "state_d");
// ===== FIX#TIE rev1: ใช้สถานะคอนแทกเตอร์จริงจาก "function 4" ไม่ใช่ทำนายจาก CP =====
// เดิม: คำนวณเองจาก CP -> เปลี่ยนก่อน R6 ขยับจริง -> กลุ่มโมดูลถูกสั่ง 0 V (= OFF) ขณะยังจ่ายไฟ
var _tieG = global.get('dcl.tieClosed');
var tie_closed = (_tieG === undefined)
    ? ((live1 && cp_head2 === "state_a") || (live2 && cp_head1 === "state_a"))   // fallback ก่อน function 4 รันครั้งแรก
    : (_tieG === true);
// busy = กำลังจะสับ R6 หรือสับอยู่ ตรวจเองด้วย (ไม่ขึ้นกับลำดับรันของโหนด)
// ===== FIX#TIESTUCK rev1 (09 ก.ย. 2026): กันธง _tieBusy ค้างถาวร =====
// เดิม: _tieBusy เป็น true ตราบใดที่ "สถานะที่ทำนายจาก CP" ไม่ตรงกับ "สถานะจริงของ R6"
//   ถ้า function 4 สับ R6 ไม่สำเร็จ (คอนแทกเตอร์ไม่ขยับ / โหนดไม่ถูก trigger / ถูก veto)
//   ธงนี้จะค้าง true ตลอด -> กลุ่มโมดูลถูกกด CV setpoint + 0 A ไปทั้ง session
//   = อาการ "อยู่ ๆ ก็หยุดจ่ายไฟทั้งที่ยัง state ชาร์จ" โดยไม่มี fault ใด ๆ
// ใหม่: 1) tieVeto ถือเป็นส่วนหนึ่งของการทำนาย (veto = ตั้งใจไม่ขนานบัส ไม่ใช่ความผิดพลาด)
//       2) ถ้ายังไม่ตรงกันเกิน TIE_BUSY_MAX_MS ให้เลิกกด 0 A แล้วเดินต่อตามสถานะ R6 จริง
var TIE_BUSY_MAX_MS = 8000;
var _tiePred = ((live1 && cp_head2 === "state_a") || (live2 && cp_head1 === "state_a"))
               && (global.get('dcl.tieVeto') !== true);
var _tieMis = (_tieG !== undefined && _tiePred !== (_tieG === true));
if (_tieMis) {
    var _misT = Number(context.get('tieMisSince')) || 0;
    if (!_misT) { _misT = Date.now(); context.set('tieMisSince', _misT); }
    if (Date.now() - _misT > TIE_BUSY_MAX_MS) {
        _tieMis = false;
        if (context.get('tieMisWarned') !== true) {
            context.set('tieMisWarned', true);
            node.warn('FIX#TIESTUCK: R6 ไม่ตรงกับที่คาดไว้เกิน ' + (TIE_BUSY_MAX_MS / 1000)
                + ' วิ -> เลิกกดกระแส 0 A เดินต่อตามสถานะ R6 จริง (ตรวจคอนแทกเตอร์ R6 / d_out/7)');
        }
    }
} else {
    context.set('tieMisSince', 0);
    context.set('tieMisWarned', false);
}
var _tieBusy = (global.get('dcl.tieBusy') === true) || _tieMis;
var head1_active = live1;
var head2_active = live2;

// G1 physical current cap (own modules only)
var maxCurrentG1 = MODULES_GROUP_1 * MODULE_MAX_CURRENT;   // 200 A with configured Tonhe topology

// G1 fractional share when running single-head (paralleled DC buses)
// ===== FIX#DYNSHARE rev1 (09 พ.ย. 2026): แบ่งกระแสตามโมดูลที่ "ใช้งานได้จริง" ของแต่ละกลุ่ม ไม่ใช่จำนวนติดตั้ง =====
// เหตุ 09/11 20:29 (หัว 2 ชาร์จเดี่ยว, บัสขนาน R6 ปิด): G2 ไม่มีโมดูลตอบบน CAN (address ตั้งเป็น 3,4 แต่ config 5,6)
//   แต่สัดส่วนคงที่ 2/4 ยังให้ G1 จ่ายแค่ครึ่ง -> รถได้กระแส 50% ของ target ตลอด session (ratio 0.49-0.50 ทุกวินาที)
// ใหม่: share_i = capable_i / (capable_1 + capable_2)  (capable = online และไม่ใช่ fault-OFF จาก parse_tonhe_can)
//   ถ้ายังไม่เห็นโมดูลเลยทั้งสองกลุ่ม (เช่น Mag เพิ่งปิด โมดูลกำลังบูต) ใช้สัดส่วนตามจำนวนติดตั้งเหมือนเดิม
//   กลุ่มที่ไม่มีโมดูลใช้งานได้ -> share 0, อีกกลุ่มรับเต็ม (clamp ต่อโมดูล 100 A ยังบังคับใน Set V/I)
function dynCapable(group) {
    const st = global.get('sinexcel_state') || {};
    const g = st.groups && st.groups[String(group)];
    if (!g) return null;
    if (typeof g.capable_count === 'number') return g.capable_count;
    let low = (g.online_mask_low >>> 0) || 0, c = 0;
    for (let i = 1; i < 32; i++) if (low & (1 << i)) c++;
    return c;
}
var _cap1 = dynCapable(1), _cap2 = dynCapable(2);
var _dynTotal = (_cap1 || 0) + (_cap2 || 0);
var G1_FRACTION = MODULES_GROUP_1 / TOTAL_MODULES;   // ค่าตั้งต้นตามจำนวนติดตั้ง 2/4
if (_dynTotal > 0) G1_FRACTION = (_cap1 || 0) / _dynTotal;
if (_dynTotal > 0 && String(_cap1) + "/" + String(_cap2) !== context.get("dynKey")) {
    context.set("dynKey", String(_cap1) + "/" + String(_cap2));
    node.warn("G1 FIX#DYNSHARE: capable G1=" + _cap1 + " G2=" + _cap2 + " -> G1 share " + G1_FRACTION.toFixed(2));
}

// Group 1 is limited only by its installed modules (2 x 30 kW = 60 kW).
// The former proportional cabinet-share cap has been removed.
var G1_POWER_CAP = G1_PHYS_POWER;

// กลุ่มนี้รับใช้หัวไหน: บัสขนาน -> หัวที่มีรถ | บัสแยก -> หัวของตัวเองถ้ามีรถ | ไม่รับใช้ใคร -> 0
var servedHead = tie_closed ? (live1 ? 1 : 2) : (live1 ? 1 : 0);
// ===== FIX#TIE rev1: ระหว่างสับ R6 ห้ามเปลี่ยนว่ากลุ่มนี้รับใช้หัวไหน =====
// ถ้าปล่อยให้เปลี่ยนทันทีที่ CP ขยับ -> voltage = target ของหัวใหม่ (= 0 เพราะยังไม่มี session)
// -> switch TargetVoltage==0 -> "# OFF power modules" -> โมดูลดับกลางคัน ขณะอีกหัวยังชาร์จอยู่
if (_tieBusy) {
    var _sLatch = context.get('servedHeadLatch');
    if (_sLatch !== undefined && _sLatch !== null) servedHead = _sLatch;
} else {
    context.set('servedHeadLatch', servedHead);
}

// ===== V/I selection =====
if (servedHead === 1) {
    // บัสขนาน -> รับส่วนแบ่งตามจำนวนโมดูล (อีกกลุ่มช่วยส่วนที่เหลือ)
    // บัสแยก  -> รับใช้หัวตัวเองคนเดียว จ่ายเต็มจำนวน target
    voltage = global.get("pep.target_voltage") || 0;
    // FIX#SHARE rev1: ถ้ากลุ่มช่วยพิสูจน์แล้วว่าไม่จ่าย (dcl.shareDegraded) -> กลุ่มหลักรับเต็ม target
    var g1fr = tie_closed ? ((global.get('dcl.shareDegraded') === true) ? 1 : G1_FRACTION) : 1;
    current = (global.get("pep.target_current") || 0) * g1fr;
}
else if (servedHead === 2) {
    // ไปช่วยอีกหัวได้เฉพาะตอนบัสขนานเท่านั้น
    voltage = global.get("pep.target_voltage2") || 0;
    current = (global.get("pep.target_current2") || 0) * G1_FRACTION;
    // FIX#SHARE rev1: โหมด failover -> กลุ่มหลักรับเต็มแล้ว กลุ่มช่วยต้องสั่ง 0 A กันจ่ายซ้อนเกิน target
    if (global.get('dcl.shareDegraded') === true) current = 0;
}
else {
    // หัวตัวเองไม่มีรถ และบัสแยก -> กลุ่มนี้ดับ
    voltage = 0;
    current = 0;
}

// ===== G1 physical current cap =====
if (current > maxCurrentG1) {
    node.warn("G1: Current limited " + current.toFixed(1) + "A -> " + maxCurrentG1.toFixed(1) + "A (physical cap)");
    current = maxCurrentG1;
}

// ===== Group 1 physical power cap (HARD failsafe) =====
// Use the physical Group 1 DC voltage for the power calculation. The PEP
// target voltage is only the module voltage command and can be higher than
// the actual battery/bus voltage, which would otherwise reduce current twice.
const measuredVoltageG1 = Number(global.get("pm.measured_voltage")) || 0;
const voltageForPowerG1 = measuredVoltageG1 > 100 ? measuredVoltageG1 : voltage;
if (voltageForPowerG1 > 0 && current > 0) {
    if (voltageForPowerG1 * current > G1_POWER_CAP) {
        current = G1_POWER_CAP / voltageForPowerG1;
        node.warn("G1: power cap " + G1_POWER_CAP + "W @ measuredV="
            + voltageForPowerG1.toFixed(1) + "V -> I=" + current.toFixed(1) + "A");
    }
}

// Status
var tag = (servedHead === 0) ? "idle"
        : (servedHead === 2) ? "help->H2(" + G1_FRACTION.toFixed(2) + "x)"
        : tie_closed ? "H1-only(" + G1_FRACTION.toFixed(2) + "x)"
        : "H1-full";
// ===== ARCH2 hardware hold rev2 (15 ก.ค.) =====
// พิสูจน์จากหน้างานแล้วว่า "ดับโมดูล" ใช้ไม่ได้: โมดูล Sinexcel ไม่รายงานแรงดันขณะดับ (Tonhe: ต้องทดสอบว่าเฟรม status ขณะ OFF รายงานแรงดันบัสหรือไม่)
//   -> EVSEPresentVoltage = 0 ทั้งที่มิเตอร์วัดได้ 385 V -> รถ abort
//
// ทำไมสั่ง current limit = 0 A แล้วยังอาจมีกระแสค้าง:
//   setpoint แรงดัน = 437 V สูงกว่าแรงดันบัส/แบต (390 V) -> โมดูลหลุดจากโหมด CV เข้าโหมด CC
//   -> ชนกระแสขั้นต่ำประมาณ 1 A ต่อโมดูลที่เปิดอยู่
//
// วิธีนี้: คงโมดูล "ติด" ไว้ แต่กดเพดานแรงดัน (CV setpoint) ให้ต่ำกว่าแรงดันแบต
//   โมดูลจ่ายเกิน setpoint ไม่ได้ -> ดันกระแสเข้าแบตไม่ได้เลย -> 0.0 A จริง
//   และเพราะยังติดอยู่ จึงรายงานแรงดันบัสได้ตามปกติ -> EVSEPresentVoltage ถูกต้อง
var a2Served = servedHead || 1;
// servedHead === 0 -> กลุ่มนี้ดับอยู่ ห้ามให้ ARCH2 ไปตั้งแรงดันปลุกมันขึ้นมา
// FIX#TIE rev1: tieBusy ใช้กลไก hold เดียวกับ ARCH2 -> กด CV setpoint ต่ำกว่าบัส, I=0,
// โมดูลยังติดและรายงานแรงดันได้ -> กระแสตกถึง ~0 A ภายในไม่กี่ร้อย ms แล้ว function 4 จึงสับ R6
var a2Hold = (servedHead !== 0)
    && (global.get('holdActive' + a2Served) === true || _tieBusy === true);
if (a2Hold) {
    var a2Mv  = Number(global.get('pm.measured_voltage')) || 0;
    var a2Ref = Number(context.get('a2BusRef')) || 0;
    if (a2Mv > a2Ref) { a2Ref = a2Mv; context.set('a2BusRef', a2Ref); }   // จำค่าสูงสุด กันไล่ลงเป็นขั้นบันได
    if (a2Ref > 150 && a2Mv > 150) {   // ต้องยังอ่านแรงดันบัสได้ ณ ตอนนี้ด้วย (ถ้าโมดูล alarm/หาย -> เลิกกด setpoint เอง)
        voltage = Math.max(120, a2Ref - 20);   // ต่ำกว่าแบต 20 V และยัง >100 เพื่อให้ switch คงสั่ง ON
        current = 0;
    } else {
        current = 0;                            // ยังไม่รู้แรงดันบัส -> คงพฤติกรรมเดิม (limit 0 A)
    }
} else {
    context.set('a2BusRef', 0);
}

// ===== FIX 13 ส.ค.: กัน 0V self-latch (เหตุ 10 ส.ค. 15:14, warning 2,943 ครั้ง) =====
// vSECC เห็น measuredVoltage 0 ชั่วขณะ -> สั่ง targetValues 0V/0A -> เดิม flow ดับโมดูล
// -> โมดูลดับแล้วไม่รายงานแรงดัน -> 0V ค้างตลอด session (path กู้คืนเดิมเป็นสายขาด)
// แก้: ระหว่าง session ยัง active (target contactor = closed) ห้ามดับโมดูลเพราะ target 0V
// ใช้กลยุทธ์เดียวกับ ARCH2 hold: คงโมดูลติด + CV setpoint ต่ำกว่าแรงดันบัส + current 0
// -> โมดูลยังรายงานแรงดันบัสได้ -> vSECC เห็นแรงดันจริง -> ฟื้น target เอง
var kaClosed = (servedHead === 1 && global.get("pep.target_contactor_status1") === "closed")
            || (servedHead === 2 && global.get("pep.target_contactor_status2") === "closed");
if (kaClosed && voltage <= 0) {
    var kaMv = Number(global.get("pm.measured_voltage")) || 0;
    voltage = (kaMv > 150) ? Math.max(120, kaMv - 20) : 120;   // >100 เพื่อให้ switch ยังสั่ง ON
    current = 0;
    node.status({fill:"yellow", shape:"dot", text:"G1 keep-alive: target 0V ระหว่าง session -> V=" + voltage.toFixed(0) + " I=0"});
}

// ===== FIX-2A-20260814: กันกระแสค้าง ~2 A ตอนถูกสั่ง 0 A (เหตุ 14 ส.ค. 03:39-03:44) =====
// อาการ: vSECC สั่ง chargingState=charge, targetCurrent=0.0, targetVoltage=398.3
//        แต่แบตอยู่ 353.8 V -> CV setpoint สูงกว่าแบต -> โมดูลกลุ่ม 1 ไม่เคารพลิมิต 0 A
//        -> วัดได้ 2.02-2.04 A ค้างทั้ง session
// พิสูจน์จาก log 03:40:51: setpoint 398.3 -> 333.5 V ทำให้กระแส 2.04 -> 0.08 A ใน 1 วินาที
//        (คำสั่งกระแสยังเป็น 0 A เท่าเดิม คอนแทกเตอร์ยังปิด โมดูลยังติด)
// ใช้กลยุทธ์เดียวกับ ARCH2 hold ด้านบน: คงโมดูลติดไว้ (V > 100) แต่กด CV setpoint
// ให้ต่ำกว่าแรงดันบัส -> โมดูลดันกระแสเข้าแบตไม่ได้ และยังรายงานแรงดันบัสได้ตามปกติ
//
// จำกัดเฉพาะ chargingState === "charge" เท่านั้น เพราะ:
//   - cableCheck ตั้งใจใช้ 0 A พร้อมแรงดันสูง (isolation test) ห้ามกด setpoint เด็ดขาด
//   - preCharge ต้องไล่แรงดันขึ้นไปหาแบต ห้ามแตะ
//   - postCharge / target 0V มี keep-alive branch ด้านบนจัดการอยู่แล้ว
var z0State = String(global.get(servedHead === 2 ? "pep.charging_state2" : "pep.charging_state") || "");
if (servedHead !== 0 && z0State === "charge" && voltage > 0 && !(current > 0)) {
    var z0Mv = Number(global.get("pm.measured_voltage")) || 0;
    if (z0Mv > 150 && voltage > z0Mv - 20) {
        voltage = Math.max(120, z0Mv - 20);
        current = 0;
        node.warn("G1: targetCurrent=0 ระหว่าง charge -> กด CV setpoint เป็น "
            + voltage.toFixed(0) + " V (บัส " + z0Mv.toFixed(0) + " V) กันกระแสค้าง");
        node.status({fill:"yellow", shape:"dot",
            text:"G1 zero-I guard: V=" + voltage.toFixed(0) + " I=0"});
    }
}

// ===== FIX#WELDDROP rev1 (21 ส.ค.): ปล่อยบัสลงจริงช่วง WeldingDetection =====
// เหตุ 20 ส.ค. 19:35/19:55/21:33 (Tata Punch/Nexon สตาร์ทไม่ติด): หลัง stop vSECC สั่ง
// postCharge + target 0 V แต่ branch keep-alive/zero-I ด้านบน (FIX 13-14 ส.ค.) กด CV
// setpoint = max(120, บัส-20) -> โมดูลคุมบัสค้าง ~120-281 V ตลอด WeldingDetection
// (log: EVSE Present Voltage flatline 119.5 V = พื้น 120 ที่เรากดไว้เอง / 281 V = บัส-20)
// รถรอไฟลง <60 V ไม่เคยได้ -> weld-check fail -> BMS Tata latch "contactor welded"
// วิธีแก้: ช่วง postCharge/Welding/SessionStop สั่ง CV setpoint = 30 V, I = 0
//   - 30 อยู่ช่วง 1..100 -> switch ON/OFF ไม่ยิงทั้งคู่ -> โมดูลคงสถานะติด
//   - โมดูลยังติด -> รายงานแรงดันบัสจริงต่อเนื่อง (บทเรียน rev2 15 ก.ค. ห้ามดับโมดูล)
//   - bleed ภายในโมดูลดึงบัสลงหา setpoint (log 19:55: 300->119.5 V ใน 7 วิ)
// วางท้ายสุดเพื่อ override ทุก branch (a2Hold/keep-alive/zero-I) เฉพาะเฟสนี้
var wdChg  = String(global.get(servedHead === 2 ? "pep.charging_state2" : "pep.charging_state") || "");
var wdSess = String(global.get(servedHead === 2 ? "session_state_head2" : "session_state_head1") || "");
var wdMode = (servedHead !== 0) && (wdChg === "postCharge"
             || /welding[_\s-]?detection|session[_\s-]?stop/i.test(wdSess));
if (wdMode) {
    voltage = 30;    // <60 V ตามที่ EV ตรวจ; ห้ามใช้ 0 (จะ OFF โมดูล -> เสียการรายงานแรงดัน)
    current = 0;
    var wdSt = global.get('sinexcel_state') || {};
    var wdG  = wdSt.groups && wdSt.groups['1'];
    var wdMv = wdG ? (Number(wdG.last_voltage) || 0) : 0;
    var wdT0 = context.get('wdT0') || 0;
    if (!wdT0) { wdT0 = Date.now(); context.set('wdT0', wdT0); context.set('wdWarned', false); }
    if (wdMv > 60 && (Date.now() - wdT0) > 8000 && context.get('wdWarned') !== true) {
        context.set('wdWarned', true);
        global.set('pe.residual_alarm1', true);
        node.warn("G1 RESIDUAL VOLTAGE: บัสค้าง " + wdMv.toFixed(1)
            + " V หลังเข้า weld-discharge >8 วิ (รับใช้หัว " + servedHead
            + ") -> ตรวจ bleed/โมดูลกลุ่ม 1 (FIX#WELDDROP)");
    }
} else {
    if (context.get('wdT0')) { context.set('wdT0', 0); }
    if (context.get('wdWarned') === true) { context.set('wdWarned', false); global.set('pe.residual_alarm1', false); }
}

node.status({fill: (voltage > 0) ? "green" : "grey", shape: "dot",
    text: "G1(" + tag + "): V=" + voltage.toFixed(0) + " I=" + current.toFixed(1) + "A physCap=" + (G1_POWER_CAP/1000).toFixed(1) + "kW"});

