    if (!wdT0) { wdT0 = Date.now(); context.set('wdT0', wdT0); context.set('wdWarned', false); }
    if (wdMv > 60 && (Date.now() - wdT0) > 8000 && context.get('wdWarned') !== true) {
        context.set('wdWarned', true);
        global.set('pe.residual_alarm2', true);
        node.warn("G2 RESIDUAL VOLTAGE: บัสค้าง " + wdMv.toFixed(1)
            + " V หลังเข้า weld-discharge >8 วิ (รับใช้หัว " + servedHead
            + ") -> ตรวจ bleed/โมดูลกลุ่ม 2 (FIX#WELDDROP)");
    }
} else {
    if (context.get('wdT0')) { context.set('wdT0', 0); }
    if (context.get('wdWarned') === true) { context.set('wdWarned', false); global.set('pe.residual_alarm2', false); }
}

node.status({fill: (voltage > 0) ? "green" : "grey", shape: "dot",
    text: "G2(" + tag + "): V=" + voltage.toFixed(0) + " I=" + current.toFixed(1) + "A physCap=" + (G2_POWER_CAP/1000).toFixed(1) + "kW"});

