// โหนดนี้เป็น "ผู้เขียนคนเดียว" ของ dcl.tieClosed / dcl.tieBusy ห้ามให้โหนดอื่นเขียน

var TIE_DEBOUNCE_MS = 400;    // CP ต้องนิ่งเท่านี้ก่อน จึง "สับจริง" (กันคอนแทกเตอร์สั่น)
var TIE_I_MAX_A     = 5;      // กระแสรวมสองกลุ่มต้องต่ำกว่านี้ จึงสับได้ (สับแบบ cold)
var TIE_RAMP_MAX_MS = 6000;   // กันค้าง: ถ้าปลดโหลดไม่ลงภายในเวลานี้ ให้สับพร้อม warn
var TIE_SETTLE_MS   = 400;    // หลังสับ รอคอนแทกเตอร์นิ่งก่อนปล่อยกระแสกลับ

var now     = Date.now();
var desired = (msg.payload === 24);

// --- 1) debounce ค่าที่ต้องการ ---
if (desired !== context.get('wantRaw')) {
    context.set('wantRaw', desired);
    context.set('wantSince', now);
}
var stable = (now - (context.get('wantSince') || 0)) >= TIE_DEBOUNCE_MS;

// --- 2) สถานะจริงของ R6 ---
var phys = context.get('phys');
if (phys === undefined) {                 // deploy ครั้งแรก: บังคับให้ค่าปัจจุบันออกจริงหนึ่งครั้ง
    phys = null;
}
if (phys !== null) global.set('dcl.tieClosed', phys);

// --- 3) ปล่อย tieBusy เมื่อพ้นเวลา settle ---
var settleUntil = context.get('settleUntil') || 0;
if (settleUntil && now >= settleUntil) {
    context.set('settleUntil', 0);
    global.set('dcl.tieBusy', false);
}

// --- 4) สถานะตรงกันแล้ว: ไม่มีอะไรต้องทำ ---
if (phys !== null && desired === phys) {
    if (!settleUntil) global.set('dcl.tieBusy', false);
    context.set('rampSince', 0);
    node.status({fill: phys ? 'blue' : 'grey', shape: 'dot',
        text: 'R6 ' + (phys ? 'CLOSED (บัสขนาน)' : 'OPEN (บัสแยก)')});
    return null;
}

// --- 5) ครั้งแรกหลัง deploy: เขียนค่าเริ่มต้นทันที ไม่ต้องปลดโหลด ---
if (phys === null) {
    context.set('phys', desired);
    global.set('dcl.tieClosed', desired);
    global.set('dcl.tieBusy', false);
    node.warn('FIX#TIE: init R6 = ' + msg.payload);
    return msg;
}

// --- 6) ต้องเปลี่ยนสถานะ: ประกาศ tieBusy แล้วรอกระแสตก ---
var rampSince = context.get('rampSince') || 0;
if (!rampSince) {
    rampSince = now;
    context.set('rampSince', rampSince);
    global.set('dcl.tieBusy', true);
    node.warn('FIX#TIE: ขอสับ R6 ' + (phys ? '24->0 (แยกบัส)' : '0->24 (ขนานบัส)')
        + ' | ปลดโหลดก่อน (tieBusy=true)');
}
global.set('dcl.tieBusy', true);

var i1 = Math.abs(Number(global.get('pm.measured_current'))  || 0);
var i2 = Math.abs(Number(global.get('pm.measured_current2')) || 0);
var itot = i1 + i2;
var waited = now - rampSince;

// debounce: ต้องนิ่งครบเวลาก่อน จึงยอมสับจริง (กระแสถูกกดเป็น 0 ไปแล้วระหว่างรอ)
if (!stable) {
    node.status({fill: 'yellow', shape: 'ring', text: 'R6 debounce CP...'});
    return null;
}
if (itot > TIE_I_MAX_A && waited < TIE_RAMP_MAX_MS) {
    node.status({fill: 'yellow', shape: 'ring',
        text: 'R6 รอปลดโหลด I=' + itot.toFixed(1) + 'A (' + (waited / 1000).toFixed(1) + 's)'});
    return null;                          // ยังไม่สับ
}
if (itot > TIE_I_MAX_A) {
    node.warn('FIX#TIE: timeout ' + (TIE_RAMP_MAX_MS / 1000) + 's กระแสยังเหลือ '
        + itot.toFixed(1) + 'A -> สับ R6 อยู่ดี (ตรวจสอบโมดูล/คอนแทกเตอร์)');
}

// --- 7) สับจริง (กระแสใกล้ศูนย์แล้ว) ---
context.set('phys', desired);
context.set('rampSince', 0);
context.set('settleUntil', now + TIE_SETTLE_MS);
global.set('dcl.tieClosed', desired);
node.warn('FIX#TIE: สับ R6 -> ' + msg.payload + ' ที่ I=' + itot.toFixed(2) + 'A');
node.status({fill: 'green', shape: 'dot',
    text: 'R6 -> ' + (desired ? 'CLOSED' : 'OPEN') + ' @ ' + itot.toFixed(1) + 'A'});
return msg;

const CURRENT_LIMIT_A = 400;
const raw = (msg.payload && typeof msg.payload === 'object' && msg.payload.limitcurrent !== undefined)
    ? msg.payload.limitcurrent
    : msg.payload;
const requested = Number(raw);
const applied = Number.isFinite(requested) && requested > 0
    ? Math.min(requested, CURRENT_LIMIT_A)
    : CURRENT_LIMIT_A;
global.set('limitcurrent1', applied);
node.status({fill:'blue', shape:'dot', text:'Head 1 current limit '+applied+'A'});
if (msg.payload && typeof msg.payload === 'object') msg.payload.limitcurrent = applied;
else msg.payload = {limitcurrent: applied};
return msg;

const CURRENT_LIMIT_A = 400;
const raw = (msg.payload && typeof msg.payload === 'object' && msg.payload.limitcurrent !== undefined)
    ? msg.payload.limitcurrent
    : msg.payload;
const requested = Number(raw);
const applied = Number.isFinite(requested) && requested > 0
    ? Math.min(requested, CURRENT_LIMIT_A)
    : CURRENT_LIMIT_A;
global.set('limitcurrent2', applied);
node.status({fill:'blue', shape:'dot', text:'Head 2 current limit '+applied+'A'});
if (msg.payload && typeof msg.payload === 'object') msg.payload.limitcurrent = applied;
else msg.payload = {limitcurrent: applied};
return msg;

// Compute per-head power/current caps for CCS signaling.
// FIX#CONN0-SHARE rev1 (09 ก.ย. 2026): รองรับงบกำลังระดับตู้จาก
// SetChargingProfile(connectorId=0) -> ดูบล็อก CONN0 SHARE ด้านล่าง
// REV TONHE-BHUTAN-3 (10 พ.ย. 2026): FIX#NOLOAD rev2 + FIX#SHARE rev2 (ตัดสินด้วยเวลาจริง ไม่ใช่จำนวนครั้ง)
//   และ FIX#PCAPV rev1 (แปลง kW->A ด้วยแรงดันบัสจริงตอนชาร์จ) -> ดูบล็อกด้านล่าง
// No separate cabinet-wide power ceiling is applied. The maximum power is
// derived from installed modules only:
//   G1 = 2 Tonhe modules x 30 kW (Head 1 native capacity = 60 kW)   [REV TONHE-BHUTAN-1]
//   G2 = 2 Tonhe modules x 30 kW (Head 2 native capacity = 60 kW)
//   Tied DC bus = all 4 modules available to one head = 120 kW
// Optional per-head HMI/MQTT values below 400 A are respected; values above
// 400 A are clamped to the configured software current ceiling.
//
// v19-port: โหนดนี้ถูกยิงทุก 1 วิ (a2_recalc) + ตอน session_state เปลี่ยน (link)
// จึง log เฉพาะตอนเปลี่ยนโหมด และส่งต่อเฉพาะตอนค่าเปลี่ยน กัน PEP-WS ท่วม

const cfg = global.get('sinexcel_cfg') || {};
function getModuleCount(group, fallback) {
    if (cfg.group_modules && Array.isArray(cfg.group_modules[group]) && cfg.group_modules[group].length > 0) {
        return cfg.group_modules[group].length;
    }
    const counts = cfg.group_module_count || {};
    const n = Number(counts[group] !== undefined ? counts[group] : counts[String(group)]);
    return Number.isFinite(n) && n > 0 ? n : fallback;
}
const MODULES_G1 = getModuleCount(1, 2);
const MODULES_G2 = getModuleCount(2, 2);
const TOTAL_MODULES = MODULES_G1 + MODULES_G2;
const MODULE_MAX_POWER = Number(cfg.module_max_power_W) || 30000;
const TOTAL_PHYS_POWER = Number(cfg.total_power_W) || (TOTAL_MODULES * MODULE_MAX_POWER);
// พิกัดกำลังฟิสิคัลของแต่ละกลุ่ม = จำนวนโมดูล x 30 kW (Tonhe)
var G1_PHYS_POWER = MODULES_G1 * MODULE_MAX_POWER;
var G2_PHYS_POWER = MODULES_G2 * MODULE_MAX_POWER;

// User-configurable per-head soft limits (from HMI / config).
// Missing/zero values mean "no additional soft power limit" and therefore
// fall back to the installed-module capacity.
var limitpower1 = Number(global.get('limitpower1'));
var limitpower2 = Number(global.get('limitpower2'));
if (!Number.isFinite(limitpower1) || limitpower1 <= 0) limitpower1 = TOTAL_PHYS_POWER;
if (!Number.isFinite(limitpower2) || limitpower2 <= 0) limitpower2 = TOTAL_PHYS_POWER;
const CURRENT_LIMIT_A = Number(cfg.current_limit_A) || 400;
function getCurrentLimit(key) {
    const n = Number(global.get(key));
    if (!Number.isFinite(n) || n <= 0) return CURRENT_LIMIT_A;
    return Math.min(n, CURRENT_LIMIT_A);
}
var limitcurrent1 = getCurrentLimit('limitcurrent1');
var limitcurrent2 = getCurrentLimit('limitcurrent2');
// Keep context synchronized with the enforced 400 A ceiling.
global.set('limitcurrent1', limitcurrent1);
global.set('limitcurrent2', limitcurrent2);

var cp_state_head1 = global.get('cp_state_head1') || '';
var cp_state_head2 = global.get('cp_state_head2') || '';
var connector0     = global.get('connector0') || 0;

// ===== FIX 16 ก.ค.: ต้องตรงกับ bus-tie ใน "function 4" (DC bypass R6 / d_out/7) =====
// บัสขนานเฉพาะตอน "หัวหนึ่งมีรถ (b/c/d) และอีกหัว = state_a เป๊ะ" -> จึงจะใช้โมดูลครบทุกตัวได้
// นอกนั้นบัสแยก: แต่ละหัวใช้ได้แค่กลุ่มของตัวเอง (รวมกรณีอีกหัวเป็น state_e/state_f)
var isLive = function (s) { return s === 'state_b' || s === 'state_c' || s === 'state_d'; };
var live1 = isLive(cp_state_head1);
var live2 = isLive(cp_state_head2);
// ===== FIX#TIE rev1: ลิมิตที่ประกาศให้รถต้องตรงกับคอนแทกเตอร์จริง =====
var _tieG = global.get('dcl.tieClosed');
var tie_closed = (_tieG === undefined)
    ? ((live1 && cp_state_head2 === 'state_a') || (live2 && cp_state_head1 === 'state_a'))
    : (_tieG === true);
var head1_active = live1;
var head2_active = live2;

var max_power_head1, max_power_head2;
var max_current_head1, max_current_head2;
var branch;

if (tie_closed && live1) {
    // บัสขนาน + หัว 1 มีรถ -> ใช้โมดูลครบทุกตัว 200 kW
    max_power_head1 = TOTAL_PHYS_POWER;
    max_power_head2 = TOTAL_PHYS_POWER;   // pre-set เผื่อหัว 2 เสียบเข้ามา
    branch = 'h1_only';
} else if (tie_closed && live2) {
    max_power_head1 = TOTAL_PHYS_POWER;
    max_power_head2 = TOTAL_PHYS_POWER;
    branch = 'h2_only';
} else if (live1 && live2) {
    // บัสแยก + ทั้งสองหัวมีรถ -> แต่ละหัวใช้พิกัดกลุ่มของตัวเองเต็มที่
    max_power_head1 = G1_PHYS_POWER;
    max_power_head2 = G2_PHYS_POWER;
    branch = 'split_both';
} else if (live1 || live2) {
    // บัสแยก + มีหัวเดียวที่มีรถ (อีกหัวค้าง state_e/state_f)
    // แต่ละทางยังถูกจำกัดเฉพาะพิกัดโมดูลของกลุ่มตัวเอง
    max_power_head1 = G1_PHYS_POWER;
    max_power_head2 = G2_PHYS_POWER;
    branch = 'split_solo';
} else {
    // ก่อนเริ่ม session ให้ทั้งสองหัวประกาศความสามารถสูงสุดเมื่อบัสขนาน
    max_power_head1 = TOTAL_PHYS_POWER;
    max_power_head2 = TOTAL_PHYS_POWER;
    branch = 'idle';
}

// log ครั้งเดียวตอนเปลี่ยนโหมด (ไม่งั้น tick 1 วิจะ spam)
if (branch !== context.get('lastBranch')) {
    context.set('lastBranch', branch);
    if (branch === 'split_both') node.warn('บัสแยก สองหัวมีรถ -> H1=' + (max_power_head1/1000).toFixed(0) + 'kW / H2=' + (max_power_head2/1000).toFixed(0) + 'kW (module physical only)');
    else if (branch === 'h1_only') node.warn('H1 only -> all modules ' + TOTAL_PHYS_POWER + 'W available; cabinet cap disabled');
    else if (branch === 'h2_only') node.warn('H2 only -> all modules ' + TOTAL_PHYS_POWER + 'W available; cabinet cap disabled');
}

// Respect user-set soft limits
max_power_head1 = Math.min(max_power_head1, limitpower1);
max_power_head2 = Math.min(max_power_head2, limitpower2);

max_current_head1 = limitcurrent1;
max_current_head2 = limitcurrent2;

// ================= เพดานกระแสฟิสิคัลต่อหัว (v19 pattern: Math.min(HW, limit)) =================
// สองหัวพร้อมกัน: H1 ใช้ G1 = 2 โมดูล (200 A), H2 ใช้ G2 = 2 โมดูล (200 A)
// หัวเดียว: บัสขนานทั้ง 4 โมดูลช่วยกัน = 400 A/หัว
const MODULE_MAX_CURRENT = Number(cfg.module_max_current_A) || 100;
// บัสขนาน -> ใช้โมดูลได้ครบทุกตัว | บัสแยก -> ได้แค่กลุ่มของตัวเอง
var hwCurrent1 = (tie_closed ? TOTAL_MODULES : MODULES_G1) * MODULE_MAX_CURRENT;
var hwCurrent2 = (tie_closed ? TOTAL_MODULES : MODULES_G2) * MODULE_MAX_CURRENT;
max_current_head1 = Math.min(max_current_head1, hwCurrent1);
max_current_head2 = Math.min(max_current_head2, hwCurrent2);

// ===== FIX#CONN0-SHARE rev1 (09 ก.ย. 2026) — งบกำลังระดับ "ทั้งตู้" จาก OCPP =====
// SetChargingProfile(connectorId = 0, ChargePointMaxProfile) ตาม OCPP 1.6 คือเพดานของ
// charge point ทั้งตัว ไม่ใช่ของหัวใดหัวหนึ่ง -> ผลรวมสองหัวต้องไม่เกินค่านี้
//
// ที่ผิดเดิม: โหนดนี้อ่าน global 'connector0' แต่ไม่เคยเอาไปใช้ (echo ลง debug payload อย่างเดียว)
//   log 09/09 21:02:13  SetChargingProfile(conn 0, 20 kW)
//     -> C1 Power.Offered 20 kW + C2 Power.Offered 20 kW  (ตู้จ่ายได้ 40 kW)
//     -> วัดจริง 18.75 + 5.79 = 24.5 kW  เกินงบ 20 kW
//
// ใหม่ (พอร์ตจาก flow follower):
//   connector0 = 1 -> limitpower1/2 + limitcurrent1/2 คือ "งบรวมของตู้"
//        สองหัว active -> หารตามจำนวนหัวที่ active (20 kW -> หัวละ 10 kW)
//        หัวเดียว active -> หัวนั้นได้เต็มงบ (ไม่ทิ้งกำลังเปล่า)
//   connector0 = 0 -> ลิมิตเป็นของแต่ละหัวตามเดิม (TxDefaultProfile / TxProfile / HMI)
//
// นับ active ตั้งแต่ state_b (ไม่ใช่ state_c) เพื่อให้เพดานลดลงก่อนหัวที่สองเริ่มจ่ายจริง
// ไม่งั้นจะมีช่วงสั้น ๆ ที่ตู้รวมกันเกินงบตอนรถคันที่สองเข้ามา
var conn0Share = (Number(connector0) === 1);
var shareN = 1;
if (conn0Share) {
    var nAct = (head1_active ? 1 : 0) + (head2_active ? 1 : 0);
    shareN = (nAct > 1) ? nAct : 1;
    if (shareN > 1) {
        max_power_head1   = Math.min(max_power_head1,   limitpower1   / shareN);
        max_power_head2   = Math.min(max_power_head2,   limitpower2   / shareN);
        max_current_head1 = Math.min(max_current_head1, limitcurrent1 / shareN);
        max_current_head2 = Math.min(max_current_head2, limitcurrent2 / shareN);
    }
    var shKey = shareN + '|' + limitpower1 + '|' + limitpower2;
    if (shKey !== context.get('lastShare')) {
        context.set('lastShare', shKey);
        node.warn('CONN0 SHARE: งบทั้งตู้ ' + (limitpower1 / 1000).toFixed(1) + ' kW, หัว active = ' + nAct
            + ' -> H1 ' + (max_power_head1 / 1000).toFixed(1) + ' kW / H2 ' + (max_power_head2 / 1000).toFixed(1) + ' kW');
    }
} else if (context.get('lastShare') !== null) {
    context.set('lastShare', null);
}

// ===== POWERCAP -> CURRENT (พอร์ตจาก follower) =====
// pm.max_power ใช้ "ประกาศ" ให้รถผ่าน vSECC dynamicLimits เท่านั้น ตัวที่บังคับจริงทางฟิสิกส์
// คือ pm.max_current (ถูก clamp ต่อโมดูลใน Head/Group V/I) ถ้ารถไม่เคารพค่าที่ประกาศ
// เพดานกำลังจะไม่มีผลเลย จึงต้องแปลงเป็นเพดานกระแสตามแรงดันจริงของหัวนั้น: I = P / V
// ทำเฉพาะตอนมีลิมิตจาก operator/OCPP จริง ๆ เท่านั้น (ไม่แตะโหมดปกติ)
var _opP1raw = Number(global.get('limitpower1'));
var _opP2raw = Number(global.get('limitpower2'));
var _hasOp1 = conn0Share || (Number.isFinite(_opP1raw) && _opP1raw > 0);
var _hasOp2 = conn0Share || (Number.isFinite(_opP2raw) && _opP2raw > 0);
// ===== FIX#PCAPV rev1 (10 พ.ย. 2026): แปลง kW -> A ด้วย "แรงดันจริงของบัส" ระหว่างชาร์จ =====
// เดิม V = max(แรงดันวัด, target) -> รถที่ส่ง target = แรงดันสูงสุดของตัวเองตลอดช่วง CC
//   (Tesla 430.4 V ทั้ง session ขณะแบตจริง ~371 V) ได้เพดานกระแสต่ำกว่าที่โมดูลจ่ายได้ ~14%:
//   60 kW -> 138 A (= 51 kW จริง), 120 kW -> 278 A (= 103 kW จริง)   [log 09/11 21:12-21:37]
//   Head 1/2 V/I ใช้แรงดันวัดอยู่แล้ว ("target voltage ... would otherwise reduce current twice")
// ใหม่: อยู่ใน charge + แรงดันวัดสมเหตุสมผล -> V = แรงดันวัด x 1.01 (เผื่อ 1% ให้กำลังจริงไม่เกินลิมิต)
//   + hysteresis 1.5 V กัน limit กระพริบ 2 A ไปมาจาก noise ของค่าวัด
//   นอกนั้น (CableCheck/PreCharge/ค่าวัดเพี้ยน) ใช้สูตรเดิม | ตั้ง sinexcel_cfg.pcap_v_source = 'max' เพื่อกลับสูตรเดิม
var PCAP_V_SOURCE = String(cfg.pcap_v_source || 'measured');
function _capV(cn) {
    var mv = Number(global.get(cn === 2 ? 'pm.measured_voltage2' : 'pm.measured_voltage')) || 0;
    var tv = Number(global.get(cn === 2 ? 'pep.target_voltage2'  : 'pep.target_voltage'))  || 0;
    var chg = String(global.get(cn === 2 ? 'pep.charging_state2' : 'pep.charging_state') || '');
    var hk = 'pcapV' + cn;
    if (PCAP_V_SOURCE !== 'max' && chg === 'charge' && mv >= 150 && (tv <= 0 || mv >= 0.6 * tv)) {
        var vref = mv * 1.01;
        var last = Number(context.get(hk)) || 0;
        if (last > 0 && Math.abs(vref - last) < 1.5) vref = last; else context.set(hk, vref);
        return vref;
    }
    context.set(hk, 0);
    var v = Math.max(mv, tv);
    return (v > 50) ? v : 0;          // CableCheck/PreCharge แรงดันต่ำ -> ไม่แปลง
}
function _powerCapA(pW, cn, curA) {
    var v = _capV(cn);
    if (!(pW > 0) || !(v > 0)) return curA;
    var a = Math.floor((pW / v) / 2) * 2;      // ปัดลงทีละ 2 A
    if (a < 2) a = 2;                          // อย่าลงจนเป็นศูนย์ (ศูนย์ = ARCH2 hold เท่านั้น)
    return Math.min(curA, a);
}
if (_hasOp1) max_current_head1 = _powerCapA(max_power_head1, 1, max_current_head1);
if (_hasOp2) max_current_head2 = _powerCapA(max_power_head2, 2, max_current_head2);

// ===== FIX#NOLOAD rev2 / FIX#SHARE rev2 (10 พ.ย. 2026): ตัวจับเวลากลางของ watchdog =====
// โหนดนี้ไม่ได้ทำงานแค่ tick 1 วิ: ทุกข้อความ topic/limitpower1/2, limitcurrent1/2, connector0 (CP.py ส่งมาเป็นชุด
// ตอนเริ่ม/จบ transaction), cp_state และ session_state ก็ปลุกด้วย -> watchdog ที่ "นับจำนวนครั้ง" (rev1)
// นับครบ 3-5 ครั้งได้ในเสี้ยววินาที -> ต้องตัดสินด้วยเวลาจริง + ผ่อนผันหลังเข้า charge / หลัง R6 ปิด
var _wdNow = Date.now();
var WD_TRIP_MS         = Number(cfg.noload_trip_ms)         || 5000;  // อาการต้องค้างต่อเนื่องอย่างน้อยเท่านี้
var WD_GRACE_CHARGE_MS = Number(cfg.noload_grace_charge_ms) || 8000;  // หลังหัวนั้นเข้า charge (Tonhe ~1-2 วิ กว่ากระแสจะขึ้น)
var WD_GRACE_TIE_MS    = Number(cfg.noload_grace_tie_ms)    || 4000;  // หลัง R6 ปิดเสร็จ (settle แล้ว)
function _since(key, cond) {     // เวลาที่ cond เริ่มเป็นจริงครั้งล่าสุด (0 = ตอนนี้ไม่จริง)
    var s = Number(context.get(key)) || 0;
    if (cond) { if (!s) { s = _wdNow; context.set(key, s); } }
    else if (s) { s = 0; context.set(key, 0); }
    return s;
}
var _chgSince1 = _since('wdChg1', String(global.get('pep.charging_state')  || '') === 'charge');
var _chgSince2 = _since('wdChg2', String(global.get('pep.charging_state2') || '') === 'charge');
var _tieSince  = _since('wdTie', tie_closed === true && global.get('dcl.tieBusy') !== true);
function _graceOk(head) {
    var c = (head === 1) ? _chgSince1 : _chgSince2;
    return c > 0 && (_wdNow - c) >= WD_GRACE_CHARGE_MS
        && _tieSince > 0 && (_wdNow - _tieSince) >= WD_GRACE_TIE_MS;
}

// ===== FIX#SHARE rev2 (10 พ.ย. 2026; rev1 21 ส.ค.): watchdog กลุ่มช่วยไม่จ่ายกระแส =====
// เหตุ 21 ส.ค. 08:38/08:41: tie ปิด + จัดสรร G2=3/5, G1=2/5 แต่ G1 จ่าย 0 A
// (โมดูลรีบูตจาก Mag AC-cycle ระหว่าง session) -> รถได้ 18.4/30.4 A ค้างทั้ง session
// rev2: นับเวลาจริง (rev1 นับจำนวนครั้งที่โหนดถูกปลุก -> ชุด limit จาก CP.py ทำให้ครบ 5 ได้ทันทีตอนเริ่มชาร์จ
//   ขณะที่กลุ่มหนึ่งของ Tonhe ขึ้นกระแสก่อนอีกกลุ่ม) + ผ่อนผันช่วงเริ่มชาร์จ/หลังสับ R6
//   + สัดส่วนกลุ่มหลักตามโมดูลที่ใช้งานได้จริง (ตรงกับ FIX#DYNSHARE ใน Head 1/2 V/I)
// ตรวจที่นี่ที่เดียว (single writer ของ dcl.shareDegraded)
(function shareWatchdog() {
    if (tie_closed !== true) {
        if (global.get('dcl.shareDegraded') === true) node.warn('FIX#SHARE: tie เปิด -> ปลด latch failover');
        global.set('dcl.shareDegraded', false); context.set('sdSince', 0); return;
    }
    var servHead = live1 ? 1 : (live2 ? 2 : 0);
    if (servHead === 0) { global.set('dcl.shareDegraded', false); context.set('sdSince', 0); return; }
    if (global.get('dcl.shareDegraded') === true) return;   // latch จนกว่า tie จะเปิด (ถอดสาย)
    var tgt   = Number(global.get(servHead === 1 ? 'pep.target_current'  : 'pep.target_current2')) || 0;
    var chg   = String(global.get(servHead === 1 ? 'pep.charging_state'  : 'pep.charging_state2') || '');
    var iPrim = Math.abs(Number(global.get(servHead === 1 ? 'pm.measured_current'  : 'pm.measured_current2')) || 0);
    var iHelp = Math.abs(Number(global.get(servHead === 1 ? 'pm.measured_current2' : 'pm.measured_current'))  || 0);
    var nPrim = (servHead === 1 ? MODULES_G1 : MODULES_G2), nAll = TOTAL_MODULES;
    var _sg = (global.get('sinexcel_state') || {}).groups || {};
    var _cP = _sg[String(servHead)] ? _sg[String(servHead)].capable_count : undefined;
    var _cH = _sg[String(servHead === 1 ? 2 : 1)] ? _sg[String(servHead === 1 ? 2 : 1)].capable_count : undefined;
    if (typeof _cP === 'number' && typeof _cH === 'number' && (_cP + _cH) > 0) { nPrim = _cP; nAll = _cP + _cH; }
    if (nPrim >= nAll) { context.set('sdSince', 0); return; }   // กลุ่มช่วยไม่มีโมดูลใช้งานได้ -> DYNSHARE ให้กลุ่มหลักเต็มอยู่แล้ว
    var primShare = tgt * nPrim / nAll;
    // เงื่อนไข: กำลัง charge จริง, target มีนัย, กลุ่มช่วย ~0 A, ยอดรวมขาด, และกลุ่มหลัก "อัดเต็มโควตา"
    // (ข้อสุดท้ายกัน false positive ตอนรถ taper เอง: ตอนนั้นกลุ่มหลักจะต่ำกว่าโควตา)
    var cond = (chg === 'charge') && tgt >= 8 && iHelp < 1
            && (iPrim + iHelp) < 0.8 * tgt && iPrim >= 0.9 * primShare
            && global.get('dcl.tieBusy') !== true;
    if (!cond) { context.set('sdSince', 0); return; }
    var s = Number(context.get('sdSince')) || 0;
    if (!s) { s = _wdNow; context.set('sdSince', s); }
    if ((_wdNow - s) < WD_TRIP_MS || !_graceOk(servHead)) return;
    global.set('dcl.shareDegraded', true);
    node.warn('FIX#SHARE rev2: กลุ่มช่วย G' + (servHead === 1 ? 2 : 1) + ' จ่าย ' + iHelp.toFixed(1)
        + ' A ต่อเนื่อง ' + ((_wdNow - s) / 1000).toFixed(1) + ' วิ ทั้งที่ควรช่วย ~' + Math.max(0, tgt - primShare).toFixed(1)
        + ' A -> โอนโหลดให้ G' + servHead + ' เต็ม target (ตรวจ R6/โมดูลด่วน)');
})();

// ================= ARCH2: กั๊กกระแสที่ CurrentDemand (port จาก v19) =================
// กั๊กเฉพาะตอนอยู่ใน CurrentDemand เท่านั้น
// CableCheck / PreCharge ต้องใช้กระแสได้ตามปกติ ไม่งั้น isolation test กับ precharge จะล้ม
var arch2raw = global.get('arch2Enabled');
if (arch2raw === undefined) { arch2raw = true; global.set('arch2Enabled', true); } // default ON แม้ deploy โดยไม่ full restart (inject once ไม่ยิง)
var arch2 = arch2raw === true;
var inCD = function (s) { return /current[_\s-]?demand/i.test(String(s || '')); }; // ทนทั้ง CamelCase/snake_case (คู่มือ J.1.21: strings may change)
var cd1 = inCD(global.get('session_state_head1'));
var cd2 = inCD(global.get('session_state_head2'));

// fail-safe: ไม่มีค่า = ยังไม่ได้สั่ง = กั๊ก
var start1 = global.get('startCommanded1') === true;
var start2 = global.get('startCommanded2') === true;

var hold1 = arch2 && cd1 && !start1;
var hold2 = arch2 && cd2 && !start2;
// EMERGENCY: บังคับลิมิต 0 ทั้ง 2 หัว จนกว่าปุ่มจะถูกปลด
// (คอนแทกเตอร์เปิดอยู่แล้วทางฮาร์ดแวร์ อันนี้กัน recalc ส่งลิมิตย้ำก่อน vSECC teardown เสร็จ)
var emergency = global.get('emerActive') === true;
if (emergency) { max_power_head1 = 0; max_power_head2 = 0; max_current_head1 = 0; max_current_head2 = 0; }
if (hold1) { max_power_head1 = 0; max_current_head1 = 0; }
if (hold2) { max_power_head2 = 0; max_current_head2 = 0; }

// ===== ARCH2 hardware hold flags (แก้ 15 ก.ค.) =====
// โมดูลมีกระแสขั้นต่ำ (Sinexcel ~1 A/ตัว; Tonhe = min current ของโมดูล) -> ค่ารวมขึ้นกับจำนวนโมดูลที่เปิดอยู่
// ต้องให้ Head/Group V/I "ดับโมดูล" ตอนกั๊ก จึงประกาศธงไว้ที่นี่ที่เดียว
global.set('holdActive1', hold1 || emergency);
global.set('holdActive2', hold2 || emergency);

// ===== FIX 13 ส.ค.: log ตอนเริ่ม/เลิกกั๊กแต่ละหัว (เดิมเห็นแค่ node.status) =====
var holdKey = (hold1 ? '1' : '0') + (hold2 ? '1' : '0');
if (holdKey !== context.get('lastHold')) {
    context.set('lastHold', holdKey);
    if (hold1) node.warn('H1: ARCH2 HOLD 0 A (ใน CurrentDemand, ยังไม่ได้รับ RemoteStart ที่ topic/RemoteStart1)');
    if (hold2) node.warn('H2: ARCH2 HOLD 0 A (ใน CurrentDemand, ยังไม่ได้รับ RemoteStart ที่ topic/RemoteStart2)');
}


// ===== FIX#NOLOAD rev2 (10 พ.ย. 2026; rev1 09 ก.ย. 2026) — ขนานบัสแล้วหัวที่เหลือจ่ายไฟไม่ออก =====
// เหตุเดิม 2026-09-09 21:40:41: หัว 1 ถอดสายขณะหัว 2 ชาร์จ -> function 4 ปิด R6 -> หัว 2 ค้าง 0.05 A นาน 57 วิ
//   -> rev1 ตั้ง dcl.tieVeto ให้ function 4 คง R6 เปิด (บัสแยก) จนกว่าทั้งสองหัวว่าง
// เหตุ rev2 (09/11/2026 20:25:21 และ 21:32:40, หัว 1): rev1 ตัดสินผิดตอน "เริ่มชาร์จ" ทั้งที่ R6 ปกติ
//   - โมดูล Tonhe ใช้ 1.2-1.9 วิ หลัง target >= 5 A กว่ากระแสจะขึ้น
//   - ชุด limit จาก CP.py (connector0 + limitpower1/2 + limitcurrent1/2) มาถึง ~1.4 วิหลังเข้า CurrentDemand
//     ปลุกโหนดนี้หลายครั้งรวด -> nlCnt (นับจำนวนครั้ง) ถึง 3 ทันที -> tieVeto ค้างทั้ง session
//   -> R6 เปิด, หัว 1 เหลือ G1 2 โมดูล = 60 kW (138 A ≈ 51 kW) แม้หัว 2 ถอดไปแล้ว ส่วน session ที่ชุด limit
//      มาหลังกระแสไหล (หัว 1 21:12/21:31, หัว 2 ทุกรอบ) ได้ 278 A ≈ 104 kW  => "หัว 1 จ่าย kW น้อยกว่าหัว 2"
// rev2: ต้องไม่มีกระแสต่อเนื่อง >= WD_TRIP_MS ตามนาฬิกาจริง, ผ่อนผัน WD_GRACE_CHARGE_MS หลังเข้า charge
//   และ WD_GRACE_TIE_MS หลัง R6 ปิด, ไม่นับระหว่าง tieBusy (ตั้งใจกดกระแสเป็น 0 เพื่อสับ R6)
//   + บันทึกเหตุผลไว้ที่ global dcl.tieVetoReason (trace vsecc/pe/arch2 ส่งลง vsecc.log)
// โหนดนี้เป็น single writer ของ dcl.tieVeto / dcl.tieVetoReason / pe.noload_alarm
(function noLoadWatchdog() {
    var NOLOAD_MIN_TARGET_A = 5;    // ต่ำกว่านี้ถือว่ารถไม่ได้ขอไฟจริง
    var NOLOAD_MAX_MEAS_A   = 1;    // วัดได้ต่ำกว่านี้ = ไม่มีกระแสไหล

    if (!live1 && !live2) {                       // ว่างทั้งสองหัว -> พร้อมรับ session ใหม่
        if (global.get('dcl.tieVeto') === true) node.warn('FIX#NOLOAD: ทั้งสองหัวว่าง -> ปลด tieVeto');
        global.set('dcl.tieVeto', false);
        global.set('dcl.tieVetoReason', '');
        global.set('pe.noload_alarm', false);
        context.set('nlSince', 0);
        return;
    }
    var solo = (live1 && !live2) ? 1 : ((live2 && !live1) ? 2 : 0);
    if (tie_closed !== true || solo === 0 || global.get('dcl.tieVeto') === true || global.get('dcl.tieBusy') === true) {
        context.set('nlSince', 0);
        return;
    }
    var nlHold = (solo === 1) ? hold1 : hold2;    // ARCH2 กั๊กอยู่ = ตั้งใจให้ 0 A
