    }
} else {
    context.set('a2BusRef', 0);
}

node.status({fill: (voltage > 0) ? "green" : "grey", shape: "dot",
    text: "G2: V=" + voltage.toFixed(0) + " I=" + current.toFixed(1) + "A physCap=" + (G2_POWER_CAP/1000).toFixed(0) + "kW"});

msg.payload = { "TargetVoltage": voltage, "TargetCurrent": current };
return msg;

msg.payload = {
    "pm_max_power": global.get("pm.max_power"),
    "pm_max_power2": global.get("pm.max_power2"),
    "pm_max_current": global.get("pm.max_current"),
    "pm_max_current2": global.get("pm.max_current2"),
    "limitpower1": global.get("limitpower1"),
    "limitpower2": global.get("limitpower2")
};
return msg;

// Tonhe keep-alive scheduler   [REV: TONHE-BHUTAN-1]  (เดิม: Sinexcel Query Scheduler 0x0202 round-robin)
// ถูก trigger ทุก 500 ms ต่อกลุ่ม (inject "Tonhe keep-alive every 500ms" -> change "Group 1"/"Group 2")
// Tonhe ไม่ต้อง query: โมดูลส่ง status (0x1801A0xx) เองทุก 500 ms
// สิ่งที่ต้องทำแทนคือ "ยิงคำสั่งล่าสุดซ้ำ" ให้ทุกโมดูล (กัน CAN communication timeout ของโมดูล
// = ext fault bit2) และส่ง timing command 0x1805FFA0 ทุก ~5 s (rate-limit อยู่ใน Frame creation)
const group = Number(msg.payload?.group_id ?? msg.payload?.group ?? 0) & 0x1F;
if (!group) return null;
msg.payload = { cmd: 'refresh', group: group };
msg.topic = 'tonhe_refresh_g' + group;
return msg;

// PP Fault Handler H1 — COMEMSO FIX (port จาก v19)
// ปัญหาเดิม: ยิง shutdown/stop ทุกครั้งที่ได้รับ pp_state = "disconnected"
//            แต่ vSECC log: "PP state ignored since not in CCS1 case"
//            -> หัว CCS2 ค้าง "disconnected" ตลอด -> ทุกข้อความซ้ำ = สั่งซ้ำ
const PP_MONITOR_ENABLED = false;   // เปิดเฉพาะเมื่อใช้หัว CCS1 และ vSECC อ่าน PP จริง

const pp   = String(msg.payload || "").trim();
const prev = String(global.get("ppPrev1") || "");
const cp   = String(global.get("cp_state1") || "");
global.set("ppPrev1", pp);

const BAD = (s) => s === "disconnected" || s === "faulted" || s === "fault";

if (cp === "state_a") global.set("ppSeenGood1", false);   // ถอดสาย -> เริ่มนับใหม่
if (!BAD(pp)) global.set("ppSeenGood1", true);            // เคยเห็นสถานะดีในรอบเสียบนี้

if (!PP_MONITOR_ENABLED) {
    node.status({ fill: "grey", shape: "ring", text: "PP monitor ปิด (CCS2) | " + pp });
    return [null, null];
}
if (!BAD(pp)) {
    node.status({ fill: "green", shape: "dot", text: "PP OK: " + pp });
    return [null, null];
}
// disconnected ตั้งแต่แรก = ค่าตั้งต้น ไม่ใช่เหตุการณ์
if (global.get("ppSeenGood1") !== true) {
    node.status({ fill: "grey", shape: "ring", text: "PP " + pp + " (ค่าตั้งต้น)" });
    return [null, null];
}
if (BAD(prev)) return [null, null];               // ข้อความซ้ำ ไม่ใช่ขอบขาลง
if (cp !== "state_c" && cp !== "state_d") {       // ยังไม่จ่ายไฟ ไม่มีอะไรให้หยุด
    node.status({ fill: "yellow", shape: "ring", text: "PP " + pp + " แต่ cp=" + cp });
    return [null, null];
}

node.warn("🚨 PE-PP-Cut H1: " + prev + " -> " + pp + " ขณะ cp=" + cp);
node.status({ fill: "red", shape: "dot", text: "PP FAULT: " + pp });
// out1: ปิดโมดูลกลุ่ม (เส้น → OFF), out2: stop_charging -> vSECC
return [{ payload: { group_id: 1 } }, { payload: "1" }];

