// CP State_E/F Handler H1 — COMEMSO FIX (port จาก v19)
// ปัญหาเดิม: (1) ยิงทุกข้อความแม้ค่าเดิมซ้ำ -> shutdown/stop วนซ้ำตอน state ค้าง
//            (2) state_f ตอนบูต (ยังไม่มี session) ก็ยิง
const cp = String(msg.payload || "").trim();
global.set("cp_state_head1", cp);             // คงหน้าที่ setter เดิม (Calculate/status info ใช้)

const prev = String(global.get("cpePrev1") || "");
