global.set("cpePrev1", cp);

const FAULT = (s) => s === "state_e" || s === "state_f";
const LIVE  = (s) => s === "state_b" || s === "state_c" || s === "state_d";

if (!FAULT(cp)) {
    node.status({ fill: "green", shape: "dot", text: "CP " + cp });
    return [null, null];
}
if (!LIVE(prev)) {                                // เข้ามาจาก state_a/ค่าว่าง = ไม่มี session ให้หยุด
    node.status({ fill: "grey", shape: "ring", text: "CP " + cp + " (ไม่มี session)" });
    return [null, null];
}

node.warn("🚨 CP fault H1: " + prev + " -> " + cp);
node.status({ fill: "red", shape: "dot", text: "CP FAULT: " + cp });
// out1: ปิดโมดูลกลุ่ม (เส้น → OFF), out2: stop_charging -> vSECC
return [{ payload: { group_id: 1 } }, { payload: "1" }];

// CP State_E/F Handler H2 — COMEMSO FIX (port จาก v19)
// ปัญหาเดิม: (1) ยิงทุกข้อความแม้ค่าเดิมซ้ำ -> shutdown/stop วนซ้ำตอน state ค้าง
