// CP.py (plc_function.get_connector_status) ต้องรู้ว่าตอนนี้กั๊กอยู่
// v17 ประกาศธงเฉพาะตอน session = CurrentDemand -> มีหน้าต่าง ~50-80 ms ที่
// CP.py (poll 0.2 วิ) เห็น CurrentDemand ก่อนธงมาถึง = ~1 ใน 3 ของ session
// v18: ยกธงตั้งแต่เสียบสาย (state_b/c/d) จนกว่าจะมี RemoteStart -> ธงถึงก่อน CD ~45 วิ
// plc_function ใช้ธงเฉพาะตอน state_c + CurrentDemand จึงขยายได้โดยไม่กระทบสถานะอื่น
const arch2 = global.get('arch2Enabled') === true;
const live  = (cp) => cp === 'state_b' || cp === 'state_c' || cp === 'state_d';

const hold1 = arch2 && live(String(global.get('cp_state1') || '')) && global.get('startCommanded1') !== true;
const hold2 = arch2 && live(String(global.get('cp_state2') || '')) && global.get('startCommanded2') !== true;

node.status({ fill: (hold1 || hold2) ? "yellow" : "grey", shape: "dot",
              text: "H1 " + (hold1 ? "HOLD" : "-") + " | H2 " + (hold2 ? "HOLD" : "-") });

// publish เฉพาะตอนค่าเปลี่ยน (retained อยู่แล้ว)
const out = [null, null];
if (String(hold1) !== context.get('h1')) { context.set('h1', String(hold1)); out[0] = { payload: hold1 ? "1" : "0" }; }
if (String(hold2) !== context.get('h2')) { context.set('h2', String(hold2)); out[1] = { payload: hold2 ? "1" : "0" }; }
return out;

// ===== Tonhe Module Fault Monitor   [REV: TONHE-BHUTAN-2, 09 พ.ย. 2026]  (แทน Sinexcel Fault Monitor) =====
// tick ทุก 2 วิ: ถอดรหัส fault bits ของ Tonhe (status word / PFC byte / extended fault word) + ตรวจโมดูลเงียบ/หาย
// + address ที่ไม่ตรง config  -> node.warn + global pm.module_faults (ลิสต์ข้อความเหมือนเดิม)
// + global tonhe_cabinet_health (ให้ tab Monitor "build snapshot" auto-detect ยี่ห้อ Tonhe)
// output 1: MQTT vsecc/pe/module_fault (เฉพาะตอนรายการเปลี่ยน)
// output 2: MQTT vsecc/pe/tonhe_health heartbeat ทุก 30 วิ (vSECC เก็บลง vsecc.log ให้ -> ใช้วิเคราะห์ย้อนหลังได้)
// rev2 (จาก log 09/11 20:27-20:40): โมดูล Tonhe ไม่มีไฟเลี้ยงสำรอง -> ตอน Mag (AC) เปิด โมดูลจะรายงาน
//   FAULT-OFF + input undervoltage/phase loss + PFC shutdown + hardware fault (bit7 เป็น summary ของ bit8-13)
//   แล้วหายจาก CAN ใน ~30 วิ และกลับมาใน ~6 วิหลัง Mag ปิด -> ถ้ากลุ่มนั้น "ไม่มีไฟ AC" ให้รายงานเป็น
//   warning "AC off" แทน fault และไม่นับว่าโมดูลหาย
// ความหมายของ bit ตาม Tonhe protocol V1.3 ข้อ 9.1.1 / 9.1.4
const FAULT_BITS = {   // status frame byte 5-6 (u16LE)
    0: "Module input undervoltage", 1: "Module input phase loss", 2: "Module input overvoltage",
    3: "Module output overvoltage", 4: "Module output overcurrent", 5: "Module temperature high",
    6: "Module fan fault", 7: "Module hardware fault", 8: "Bus exception", 9: "SCI communication exception",
    10: "Discharge fault", 11: "PFC shutdown due to exception", 12: "Output undervoltage warning",
    13: "Output overvoltage warning", 14: "Power limit due to high temperature", 15: "Short circuit fault"
};
const FAULT_WARN_ONLY = [12, 13, 14];          // แจ้งเป็น warning ไม่นับเป็น fault
const FAULT_AC_RELATED = [0, 1, 11];           // bit ที่เกิดจากไม่มีไฟ AC เข้าโมดูล (Mag เปิด)
const PFC_BITS = {     // status frame byte 7 (u8)
    0: "PFC input overcurrent fault", 1: "Mains frequency fault", 2: "Mains imbalance fault", 3: "DCTz fault",
    4: "ADDRESS CONFLICT (ตั้ง address หน้าโมดูลซ้ำ)", 5: "Bus bias", 6: "Phase exception fault", 7: "Bus overvoltage fault"
};
const PFC_AC_RELATED = [1, 2, 6];
const EXT_BITS = {     // extended frame byte 2-3 (u16LE)
    0: "Preceding stage wave stop", 1: "Hot-plug fault", 2: "CAN communication timeout",
    4: "Relay operation fault", 6: "Internal element overtemperature", 7: "Air inlet overtemperature",
    8: "Input power limit", 9: "Power limit due to overtemperature", 10: "Discharge changeover exception",
    11: "Abnormal voltage/current balancing", 12: "Heat sink temperature differential protection",
    13: "Emergency stop", 14: "Air inlet temperature too low", 15: "Uneven current in front (double vienna)"
};
const EXT_WARN_ONLY = [8, 9];

const st  = global.get("sinexcel_state") || { groups: {} };
const cfg = global.get("sinexcel_cfg") || {};
const th  = cfg.tonhe || {};
const GROUP_ADDR = th.group_addr || { 1: [1, 2], 2: [3, 4] };
const now = Date.now();
const STALE_MS = Number(th.stale_ms ?? 5000);          // ไม่มี status เกินนี้ = เงียบ (โมดูลส่งเองทุก 500 ms)
const UNMAPPED_HOLD_MS = Number(th.unmapped_hold_ms ?? 15000);
const HEARTBEAT_MS = Number(th.health_heartbeat_ms ?? 30000);
const anyActive = (Number(global.get("pep.target_voltage")) || 0) > 100
               || (Number(global.get("pep.target_voltage2")) || 0) > 100;

// ไฟ AC เข้าโมดูลของกลุ่มนี้น่าจะมีอยู่ไหม: Mag aux contact (d_in/7 -> Mag1_status, d_in/6 -> Mag2_status) ปิด (=1)
// หรือมีรถเสียบอยู่หัวใดหัวหนึ่ง (Digital_i/o ปิด Mag ทั้งสองตัวเมื่อหัวใดหัวหนึ่ง live)
const MAG_GLOBAL = { 1: "Mag1_status", 2: "Mag2_status" };
const live = (s) => (s === "state_b" || s === "state_c" || s === "state_d");
const anyCpLive = live(String(global.get("cp_state_head1") || global.get("cp_state1") || ""))
               || live(String(global.get("cp_state_head2") || global.get("cp_state2") || ""));
function acOn(grp) {
    const fb = Number(global.get(MAG_GLOBAL[grp]));
    if (Number.isFinite(fb)) return fb === 1 || anyCpLive;
    return anyCpLive;
}

const faults = [];      // ข้อความ (เหมือนเดิม)
const warnings = [];
const expected = [], present = [], capable = [], contributing = [], missing = [];
const perAddr = {};
const acOff = {};

for (const grp of Object.keys(GROUP_ADDR)) {
    const addrs = (GROUP_ADDR[grp] || []).map(Number);
    const g = (st.groups || {})[String(grp)] || { modules: {} };
    const ac = acOn(Number(grp));
    acOff[grp] = !ac;
    if (!ac) warnings.push("G" + grp + ": AC off (Mag open) - module faults suppressed");
    addrs.forEach((addr, i) => {
        const sub = i + 1;
        const m = (g.modules || {})[String(sub)] || {};
        const tag = "G" + grp + "M" + sub + "(addr" + addr + ")";
        expected.push(addr);
        const age = m.ts_any ? (now - m.ts_any) : null;
        const isPresent = (age !== null) && age <= STALE_MS;
        let hasFault = false;
        const sink = ac ? faults : warnings;        // ไม่มี AC -> ทุกอย่างเป็น warning

        if (isPresent) present.push(addr);
        else if (anyActive && ac) {
            if (age === null) faults.push(tag + ": no CAN data");
            else faults.push(tag + ": CAN silent " + Math.round(age / 1000) + "s");
        }
        if (!isPresent) missing.push(addr);

        const fw = Number(m.fault_bits) || 0;
        const summaryOnly = ((fw & 0x3F00) !== 0);    // bit8-13 ติด -> bit7 เป็นแค่ summary (สเปคข้อ 9.1.1 note 1)
        if (m.state === 0x11) { sink.push(tag + ": module in FAULT-OFF state (0x11)"); hasFault = true; }
        for (const bit of Object.keys(FAULT_BITS)) {
            const b = Number(bit);
            if (!(fw & (1 << b))) continue;
            if (b === 7 && summaryOnly) continue;
            if (FAULT_WARN_ONLY.includes(b)) warnings.push(tag + ": " + FAULT_BITS[bit]);
            else if (!ac && FAULT_AC_RELATED.includes(b)) warnings.push(tag + ": " + FAULT_BITS[bit] + " (AC off)");
            else { sink.push(tag + ": " + FAULT_BITS[bit]); hasFault = true; }
        }
        const pw = Number(m.pfc_bits) || 0;
        for (const bit of Object.keys(PFC_BITS)) {
            const b = Number(bit);
            if (!(pw & (1 << b))) continue;
            if (!ac && PFC_AC_RELATED.includes(b)) warnings.push(tag + ": " + PFC_BITS[bit] + " (AC off)");
            else { sink.push(tag + ": " + PFC_BITS[bit]); hasFault = true; }
        }
        const xw = Number(m.ext_fault) || 0;
        for (const bit of Object.keys(EXT_BITS)) {
            const b = Number(bit);
            if (!(xw & (1 << b))) continue;
            if (EXT_WARN_ONLY.includes(b)) warnings.push(tag + ": " + EXT_BITS[bit]);
            else { sink.push(tag + ": " + EXT_BITS[bit]); hasFault = true; }
        }
        if (isPresent && !hasFault) capable.push(addr);
        if (isPresent && Number(m.current) > 0.5) contributing.push(addr);

        perAddr[String(addr)] = {
            group: Number(grp), index: sub, present: isPresent, age_ms: age, ac_on: ac,
            state: (m.state !== undefined) ? m.state : null,
            voltage: (typeof m.voltage === 'number') ? +m.voltage.toFixed(1) : null,
            current: (typeof m.current === 'number') ? +m.current.toFixed(2) : null,
            fault_bits: m.fault_bits ?? null, pfc_bits: m.pfc_bits ?? null,
            ext_status: m.ext_status ?? null, ext_fault: m.ext_fault ?? null,
            va: m.va ?? null, vb: m.vb ?? null, vc: m.vc ?? null, ambient_c: m.ambient_c ?? null
        };
    });
}

// address ที่โผล่บนบัสแต่ไม่อยู่ใน config (ตั้ง address หน้าโมดูลผิด / config ผิด) -> เป็น fault เสมอ
const unmapped = [];
for (const [a, ts] of Object.entries(st.unmapped || {})) {
    if ((now - Number(ts)) <= UNMAPPED_HOLD_MS) unmapped.push(Number(a));
}
if (unmapped.length) faults.push("Tonhe address not in config: " + unmapped.join(",") + " (expected " + expected.join(",") + ") -> แก้ sinexcel_cfg.tonhe.group_addr หรือตั้ง address หน้าโมดูลใหม่");
// กลุ่มที่ควรมีโมดูลแต่ไม่มีตัวไหนตอบเลยทั้งที่มี AC และกำลังชาร์จ -> ฟ้องชัด ๆ
for (const grp of Object.keys(GROUP_ADDR)) {
    const g = (st.groups || {})[String(grp)];
    if (anyActive && !acOff[grp] && (!g || !(Number(g.capable_count) > 0)))
        faults.push("G" + grp + ": NO CAPABLE MODULE (0/" + (GROUP_ADDR[grp] || []).length + ") -> กลุ่มนี้จ่ายกระแสไม่ได้ อีกกลุ่มรับเต็ม (FIX#DYNSHARE)");
}

const txst = global.get("tonhe_tx_state") || {};
const health = {
    ts: new Date(now).toISOString(), brand: "tonhe",
    expected_addresses: expected, present_addresses: present, capable_addresses: capable,
    contributing_addresses: contributing, missing_addresses: missing, active_unmapped_addresses: unmapped,
    all_4_can_ready: expected.length > 0 && missing.length === 0,
    all_expected_present: expected.length > 0 && missing.length === 0,
    ac_off_groups: Object.keys(acOff).filter(k => acOff[k]).map(Number),
    any_active: anyActive,
    tx: txst,
    fault_summary: faults, warning_summary: warnings, per_address: perAddr
};
global.set("tonhe_cabinet_health", health);
global.set("pm.module_faults", faults);
global.set("pm.module_warnings", warnings);

// ---- output 2: heartbeat ทุก HEARTBEAT_MS (compact) ----
