// ===== FIX#ESTOP-GLOBAL rev2 (09 ก.ย. 2026) — ทำตัวแบบ flow "follower" =====
// DIN8 = ปุ่ม Emergency หน้าตู้ (HAL เรียกพินนี้ว่า DIGITAL_IN_8_CONNECTOR_2_STOP)
//
// ที่ผิดเดิม: estop_is_global = false ทำให้
//   - ไม่เคยตั้ง emerActive -> pep_ws (create status info) ไม่เคยรายงาน inoperative
//     -> vSECC ไม่เคยสั่ง EmergencyShutdown, PWM ยังคง 100 %
//   - ไม่เคยบังคับ max_current = 0 ใน Calculate Power/Current
//   - ส่ง stop_charging เฉพาะหัว 2 -> หัว 1 ชาร์จต่อไปเฉย ๆ
//
// ใหม่ (พฤติกรรมเดียวกับ follower + ของเดิมที่ดีกว่า):
//   1) stop_charging ทั้ง 2 หัว + เคลียร์ startCommanded + ตั้ง manualStop กัน AUTOSTART
//   2) emerActive = true -> PE รายงาน inoperative + contactorsStatus "open"
//      -> vSECC ทำ emergency shutdown (PWM 0 %, state F) และลิมิตกระแสถูกบังคับเป็น 0
//   3) RE-ASSERT: ย้ำ stop_charging ทุก 2 วิ ตราบใดที่ปุ่มยังกดค้าง (สูงสุด 15 ครั้ง / 30 วิ)
//      กัน MQTT packet หาย หรือ EV ไม่ยอมจบ session ในครั้งแรก
//      (หลักการเดียวกับ FAN re-assert 300 s และ R6 refresh ในโฟลว์นี้)
//   4) RELEASE GUARD: เห็น payload = 1 เมื่อไหร่ก็ตาม เคลียร์ emerActive แม้ไม่เห็นขอบขาลงมาก่อน
//      (กัน deploy/restart ตอนปุ่มกดค้าง แล้วธงค้าง -> สถานีล็อกยาว)
//   5) คง debounce estop_debounce_ms (400 ms) กรอง pulse ปลอมจาก PLC
const RE_ASSERT_MS  = 2000;
const RE_ASSERT_MAX = 15;

const isGlobal = global.get("estop_is_global") !== false;   // undefined -> global (fail-safe)
const DB = Number(global.get("estop_debounce_ms")) || 400;

const raw = msg.payload;
const num = (typeof raw === "boolean") ? (raw ? 1 : 0) : Number(raw);
if (num !== 0 && num !== 1) return null;                    // payload ขยะ -> ไม่เปลี่ยนสถานะ

const pressed = (num === 0);
const prev    = context.get("prevPressed") === true;
context.set("prevPressed", pressed);

function sendStop() {
    if (isGlobal) node.send([{ payload: "1" }, { payload: "1" }]);
    else          node.send([null,             { payload: "1" }]);
}
function stopRepeat() {
    const r = context.get("reTimer");
    if (r) { clearInterval(r); context.set("reTimer", null); }
    context.set("reCount", 0);
}
function fireStop() {
    if (context.get("prevPressed") !== true) return;        // ปล่อยก่อนครบเวลา -> ไม่ยิง
    if (context.get("firedThisPress") === true) return;     // กันยิงซ้ำระหว่างกดค้าง
    context.set("firedThisPress", true);

    if (isGlobal) {
        global.set("emerActive", true);
        global.set("startCommanded1", false);
        global.set("startCommanded2", false);
        global.set("manualStop1", true);
        global.set("manualStop2", true);
        node.warn("🚨 EMERGENCY (global, ยืนยัน " + DB + " ms) -> stop_charging ทั้ง 2 หัว + PE inoperative");
        node.status({ fill: "red", shape: "dot", text: "E-STOP (global) @ " + new Date().toISOString() });
    } else {
        global.set("startCommanded2", false);
        global.set("manualStop2", true);
        node.warn("DIN8 (ยืนยัน " + DB + " ms): CONNECTOR_2_STOP -> stop_charging เฉพาะหัว 2");
        node.status({ fill: "yellow", shape: "dot", text: "H2 stop @ " + new Date().toISOString() });
    }
    sendStop();

    stopRepeat();
    const iv = setInterval(function () {
        if (context.get("prevPressed") !== true) { stopRepeat(); return; }
        const c = (Number(context.get("reCount")) || 0) + 1;
        context.set("reCount", c);
        if (c > RE_ASSERT_MAX) { stopRepeat(); return; }
        sendStop();
        node.status({ fill: "red", shape: "dot", text: "E-STOP re-assert #" + c });
    }, RE_ASSERT_MS);
    context.set("reTimer", iv);
}

if (!pressed) {                                             // ปล่อยปุ่ม (ไม่ต้องรอขอบ)
    stopRepeat();
    const t = context.get("dbTimer");
    if (t) { clearTimeout(t); context.set("dbTimer", null); }
    if (prev && context.get("firedThisPress") !== true) {
        const w = Date.now() - (Number(context.get("pressedAt")) || Date.now());
        if (w < DB) node.warn("DIN8: ทิ้ง pulse ปลอม กว้าง " + w + " ms (< " + DB + " ms) — ไม่สั่งหยุดชาร์จ");
    }
    context.set("firedThisPress", false);
    if (global.get("emerActive") === true) {
        global.set("emerActive", false);
        node.warn("EMERGENCY ปลดแล้ว -> พร้อมรับ session ใหม่ (ต้องถอดสาย/กด Start ก่อน)");
    }
    node.status({ fill: "grey", shape: "ring", text: "stop released" });
    return null;
}

if (!prev) {                                                // ขอบขาลง -> เริ่มจับเวลา
    context.set("firedThisPress", false);
    context.set("pressedAt", Date.now());
    const t0 = context.get("dbTimer");
    if (t0) clearTimeout(t0);
    context.set("dbTimer", setTimeout(fireStop, DB));
    node.status({ fill: "yellow", shape: "ring", text: "DIN8 LOW... รอยืนยัน " + DB + " ms" });
    return null;
}

node.status({ fill: "red", shape: "dot", text: isGlobal ? "emergency active" : "H2 stop active" });
return null;

