let stopH2 = msg.payload.StopH2 || false;

// ถ้ากดปุ่ม SelectH2 หรือ StopH2 (true)
if (selectH2 || stopH2) {
    // ตั้งค่าให้ route ไปหัว 2
    flow.set('selectedHead', 2);
    flow.set('buttonPressed', true);

    node.status({ fill: "blue", shape: "dot", text: "Head 2 Selected" });
} else {
    // ปล่อยปุ่ม
    flow.set('buttonPressed', false);
    node.status({ fill: "grey", shape: "ring", text: "Released" });
}

return null;

// อ่านค่า RFID
let rfidValue = msg.payload;

// ถ้า RFID = 0 ให้ส่งไปทั้งสองหัว
if (rfidValue === 0 || rfidValue === "0") {
    let msg1 = { payload: 0 };
    let msg2 = { payload: 0 };
    node.status({ fill: "red", shape: "dot", text: "RFID=0 → Both Heads" });
    return [msg1, msg2];
}

// อ่านค่าหัวที่เลือกและสถานะปุ่ม
let selectedHead = flow.get('selectedHead') || 0;
let buttonPressed = flow.get('buttonPressed') || false;

// ถ้าปุ่มถูกกดอยู่
if (buttonPressed) {
    if (selectedHead === 1) {
        // ส่งไปหัว 1
        node.status({ fill: "green", shape: "dot", text: "Sent to Head 1" });
        return [msg, null];
    } else if (selectedHead === 2) {
        // ส่งไปหัว 2
        node.status({ fill: "blue", shape: "dot", text: "Sent to Head 2" });
        return [null, msg];
    }
}

// ไม่มีการเลือก
node.status({ fill: "yellow", shape: "ring", text: "No head selected" });
return [null, null];

msg.payload =
{
    "H1shown" : false
}
return msg;

msg.payload =
{
    "H1shown" : true
}
return msg;

msg.payload =
{
    "H2shown" : false
}
return msg;

msg.payload =
{
    "H2shown" : true
}
return msg;

var d = msg.payload;
if (!d || d.length < 7) { node.warn("Expected 7 regs, got "+(d?d.length:0)); return [null,null,null]; }
var s = d[4];       // 0x0014 status register
var r_pos = d[2];   // 0x0012 R+ to ground (kΩ)
var r_neg = d[3];   // 0x0013 R- to ground (kΩ)

// Check status register bit1: res_valid
// bit1=1 means resistance values are valid and can be read
// bit1=0 means IMD startup not complete, DC<100V, or monitoring OFF
var res_valid = (s >> 1) & 1;

var iso_result;
var r_pos_kohm, r_neg_kohm, min_kohm;

if (r_pos === 0xFFFF) { r_pos_kohm = "INVALID"; } 
else if (r_pos === 0xEA60) { r_pos_kohm = ">10000"; } 
else { r_pos_kohm = r_pos; }

if (r_neg === 0xFFFF) { r_neg_kohm = "INVALID"; } 
else if (r_neg === 0xEA60) { r_neg_kohm = ">10000"; } 
else { r_neg_kohm = r_neg; }

if (res_valid !== 1 || r_pos === 0xFFFF || r_neg === 0xFFFF) {
    // IMD not ready: startup period, DC<100V, or monitoring off
    // Do NOT change iso_value — keep previous value (default=1 from IMD Control)
    iso_result = null;
    min_kohm = "INVALID";
} else {
    var rp = (r_pos === 0xEA60) ? 10000 : r_pos;
    var rn = (r_neg === 0xEA60) ? 10000 : r_neg;
    min_kohm = Math.min(rp, rn);
    iso_result = (min_kohm <= 100) ? 0 : 1;
}

// Write to global — ONLY if valid result AND IMD still active
if (iso_result !== null) {
    if (msg._uid === 1 && global.get("imd1_active") === true) {
        global.set("iso_value1", iso_result);
    } else if (msg._uid === 2 && global.get("imd2_active") === true) {
        global.set("iso_value2", iso_result);
    }
}

// Output 1: full parsed data
var msg1 = {payload: {
    addr: msg._uid || "?",
    voltage: (d[0]*0.1).toFixed(1)+"V",
    R_pos: r_pos_kohm + " k\u03A9",
    R_neg: r_neg_kohm + " k\u03A9",
    min_R: min_kohm + " k\u03A9",
    iso_result: iso_result !== null ? iso_result : "WAITING",
    status: "0x"+s.toString(16).padStart(4,"0"),
    mon_on: (s>>2)&1?"ON":"OFF",
    res_valid: res_valid?"YES":"NO",
    selftest: (s>>4)&1?"PASS":"FAIL",
    V_pos: d[5]===0xFFFF?"N/A":(d[5]*0.1).toFixed(1)+"V",
    V_neg: d[6]===0xFFFF?"N/A":(d[6]*0.1).toFixed(1)+"V"
}};

// Output 2: IMD#1 debug
var msg2 = null;
if (msg._uid === 1) {
    msg2 = {payload: {
        head: "IMD#1",
        R_pos: r_pos_kohm + " k\u03A9",
        R_neg: r_neg_kohm + " k\u03A9",
        min_R: min_kohm + " k\u03A9",
        iso_value1: global.get("iso_value1"),
        res_valid: res_valid?"YES":"NO",
        verdict: iso_result === null ? "\u23F3 WAITING (res_valid=NO)"
               : iso_result === 1 ? "\u2705 PASS (>100k\u03A9)" 
               : "\u274C FAIL (\u2264100k\u03A9)"
    }};
}

// Output 3: IMD#2 debug
var msg3 = null;
if (msg._uid === 2) {
    msg3 = {payload: {
        head: "IMD#2",
        R_pos: r_pos_kohm + " k\u03A9",
        R_neg: r_neg_kohm + " k\u03A9",
        min_R: min_kohm + " k\u03A9",
        iso_value2: global.get("iso_value2"),
        res_valid: res_valid?"YES":"NO",
        verdict: iso_result === null ? "\u23F3 WAITING (res_valid=NO)"
               : iso_result === 1 ? "\u2705 PASS (>100k\u03A9)" 
               : "\u274C FAIL (\u2264100k\u03A9)"
    }};
}

return [msg1, msg2, msg3];

initialize:
global.set("iso_value1", 1);
global.set("iso_value2", 1);
global.set("imd1_active", false);
global.set("imd2_active", false);

func:
msg._uid=1;
msg.payload={fc:3,unitid:1,address:16,quantity:7};
return msg;

msg._uid=2;
msg.payload={fc:3,unitid:2,address:16,quantity:7};
return msg;

// IMD#1 Auto Control based on charging session state
var state = msg.payload;
var imd1_active = global.get("imd1_active") || false;

if (state === "VSECCLIB_SST_DIN_CableCheck" && !imd1_active) {
    // CableCheck started → Turn ON IMD#1 + start polling
    global.set("imd1_active", true);
    global.set("iso_value1", 1);  // default OK, will be set to 0 if IMD detects fault

    var msgON = {payload: {value: 0x0011, fc: 6, unitid: 1, address: 258, quantity: 1}};
    var msgPoll = {payload: "start"};

    node.status({fill:"green", shape:"dot", text:"IMD#1 ON - CableCheck"});
    return [msgON, msgPoll, null];

} else if (imd1_active && (state === "" || state === undefined || state === null
    || state === "VSECCLIB_SST_DIN_NotReady" || state === "VSECCLIB_SST_ISO_NotReady")) {
    // Session ended (normal or error) → Turn OFF + reset
    global.set("imd1_active", false);
    global.set("iso_value1", 1);  // reset to OK for next session

    var msgOFF = {payload: {value: 0x0000, fc: 6, unitid: 1, address: 258, quantity: 1}};
    var msgStop = {payload: "stop"};

    node.status({fill:"grey", shape:"ring", text:"IMD#1 OFF"});
    return [msgOFF, null, msgStop];
}

return [null, null, null];

// IMD#2 Auto Control based on charging session state
var state = msg.payload;
var imd2_active = global.get("imd2_active") || false;

if (state === "VSECCLIB_SST_DIN_CableCheck" && !imd2_active) {
    // CableCheck started → Turn ON IMD#2 + start polling
    global.set("imd2_active", true);
    global.set("iso_value2", 1);  // default OK, will be set to 0 if IMD detects fault

    var msgON = {payload: {value: 0x0011, fc: 6, unitid: 2, address: 258, quantity: 1}};
    var msgPoll = {payload: "start"};

    node.status({fill:"green", shape:"dot", text:"IMD#2 ON - CableCheck"});
    return [msgON, msgPoll, null];

} else if (imd2_active && (state === "" || state === undefined || state === null
    || state === "VSECCLIB_SST_DIN_NotReady" || state === "VSECCLIB_SST_ISO_NotReady")) {
    // Session ended (normal or error) → Turn OFF + reset
    global.set("imd2_active", false);
    global.set("iso_value2", 1);  // reset to OK for next session

    var msgOFF = {payload: {value: 0x0000, fc: 6, unitid: 2, address: 258, quantity: 1}};
    var msgStop = {payload: "stop"};

    node.status({fill:"grey", shape:"ring", text:"IMD#2 OFF"});
    return [msgOFF, null, msgStop];
}

return [null, null, null];

global.set('imd1_active', true);
node.status({fill:'green',shape:'dot',text:'Polling ON'});
return null;

global.set('imd1_active', false);
node.status({fill:'grey',shape:'ring',text:'Polling OFF'});
return null;

global.set('imd2_active', true);
node.status({fill:'green',shape:'dot',text:'Polling ON'});
return null;

global.set('imd2_active', false);
node.status({fill:'grey',shape:'ring',text:'Polling OFF'});
return null;

// Gate: only pass if IMD#1 polling is active
if (global.get("imd1_active") === true) {
    msg._uid = 1;
    msg.payload = {fc: 3, unitid: 1, address: 16, quantity: 7};
    return msg;
}
return null;

// Gate: only pass if IMD#2 polling is active
if (global.get("imd2_active") === true) {
    msg._uid = 2;
    msg.payload = {fc: 3, unitid: 2, address: 16, quantity: 7};
    return msg;
}
return null;

// AUTO-DETECT charger id  --  no editing needed.
// Priority: 1) env MON_PREFIX  2) hostname c1/charger1/evse01/station3  3) raw hostname  4) "c0"+warn
function clean(s){ return String(s).trim().toLowerCase().replace(/[^a-z0-9_-]/g,""); }
let prefix = "";
const override = env.get("MON_PREFIX");
const host = env.get("HOSTNAME") || env.get("HOST") || "";
if (override) {
    prefix = clean(override);
} else if (host) {
    const m = clean(host).match(/^(?:c|ch|charger|evse|station)[-_]?(\d+)$/);
    prefix = m ? ("c" + m[1]) : clean(host);
}
if (!prefix) { prefix = "c0"; node.warn("MON: cannot auto-detect charger id - set env MON_PREFIX. Using c0."); }
flow.set("MON_PREFIX", prefix);
flow.set("mon", { conn:{}, io:{} });
node.status({ fill: (prefix === "c0" ? "yellow" : "green"), shape:"dot", text: "id = " + prefix });
return null;

// Collector: per-connector vSECC data  (topic = vsecc/connector/<n>/<leaf>)
const t = msg.topic || "";
const m = t.match(/connector\/(\d+)\/(.+)$/);
if (!m) return null;
const cn = m[1], leaf = m[2];
const map = {
  "ev/cp_state":"cp_state",
  "status/charging_session_state":"session_state",
  "status/charging_standard":"standard",
  "status/charging_authorization_state":"auth_state",
  "pe/measured_voltage":"meas_v",
  "pe/measured_current":"meas_i",
  "ev/requested_voltage":"req_v",
  "ev/requested_current":"req_i",
  "ev/soc":"soc",
  "ev/time_to_full_soc":"ttf_s",
  "em/transferred_energy":"energy",
  "em/measurement_status":"em_status",
  "ev/limits/max_voltage":"ev_max_v",
  "ev/charging_complete":"complete",
  "ev/ev_ready":"ev_ready",
  "ev/ev_error_code":"err_code",
  "ev/pp_state":"pp_state",
  "status/components/active_failures":"active_failures"
};
const key = map[leaf];
if (key === undefined) return null;
let mon = flow.get("mon") || { conn:{}, io:{} };
if (!mon.conn[cn]) mon.conn[cn] = {};
mon.conn[cn][key] = msg.payload;
mon.conn[cn]._ts = Date.now();
flow.set("mon", mon);
return null;

// Collector: I/O + temperatures  (topic = vsecc/io/...)
const t = msg.topic || "";
let mon = flow.get("mon") || { conn:{}, io:{} };
let m;
if      ((m = t.match(/t_in\/(\d+)\/temperature/))) mon.io["t"   + m[1]] = msg.payload;
else if ((m = t.match(/d_in\/(\d+)\/value/)))        mon.io["din" + m[1]] = msg.payload;
else if ((m = t.match(/d_out\/(\d+)\/value/)))       mon.io["dout"+ m[1]] = msg.payload;
else return null;
flow.set("mon", mon);
return null;

// Builder v8: snapshot + auto-detect PM brand (TonHe / Sinexcel / Phoenix CHARX). Guarded - never throws.
try {
  const mon    = flow.get("mon") || { conn:{}, io:{} };
  const prefix = flow.get("MON_PREFIX") || "c0";
  const g    = (k, d) => { const x = global.get(k); return (x === undefined || x === null) ? d : x; };
  const num  = (x) => { const n = parseFloat(x); return isNaN(n) ? null : n; };
  const sst  = (s) => (typeof s === "string") ? s.replace(/VSECCLIB_SST_(DIN|ISO)_/, "") : (s ?? null);
  const popc = (x) => { x = x >>> 0; let c = 0; while (x) { c += x & 1; x >>>= 1; } return c; };
  const len  = (a) => Array.isArray(a) ? a.length : null;

  const conns = {};
  [1, 2].forEach(i => {
    const c = mon.conn[String(i)] || {};
    const v = num(c.meas_v), a = num(c.meas_i);
    conns[i] = {
      cp_state: c.cp_state ?? null, session_state: sst(c.session_state),
      standard: c.standard ?? null, auth_state: c.auth_state ?? null,
      meas_v: v, meas_i: a,
      power_kw: (v !== null && a !== null) ? +((v * a) / 1000).toFixed(2) : null,
      req_v: num(c.req_v), req_i: num(c.req_i), soc: num(c.soc),
      ttf_min: (num(c.ttf_s) !== null) ? +(num(c.ttf_s) / 60).toFixed(1) : null,
      energy: num(c.energy), em_status: c.em_status ?? null, ev_max_v: num(c.ev_max_v),
      complete: c.complete ?? null, ev_ready: c.ev_ready ?? null, err_code: c.err_code ?? null,
      active_failures: c.active_failures ?? null, pp_state: c.pp_state ?? null,
      stale_s: c._ts ? +((Date.now() - c._ts) / 1000).toFixed(1) : null
    };
  });

  const mp1 = num(g("pm.max_power", null)), mp2 = num(g("pm.max_power2", null));
  const pm = {
    status:         g("pm.status", null),
    status2:        g("pm.status2", null),
    max_power_kw_1: (mp1 !== null) ? +(mp1 / 1000).toFixed(1) : null,
    max_power_kw_2: (mp2 !== null) ? +(mp2 / 1000).toFixed(1) : null,
    max_current_1:  num(g("pm.max_current",  null)),
    max_current_2:  num(g("pm.max_current2", null)),
    meas_v:         num(g("pm.measured_voltage",  null)),
    meas_i:         num(g("pm.measured_current",  null)),
    meas_v2:        num(g("pm.measured_voltage2", null)),
    meas_i2:        num(g("pm.measured_current2", null))
  };

  // ---- module count: AUTO-DETECT PM brand ----
  // order matters: TonHe also writes sinexcel_state, so check tonhe_cabinet_health FIRST.
  const th    = g("tonhe_cabinet_health", null);
  const sxCfg = g("sinexcel_cfg", null);
  const sx    = g("sinexcel_state", null);
  const now   = Date.now();
  let modules = null;

  if (th && typeof th === "object") {
    // ===== TonHe (live, per-address present / capable / contributing + missing) =====
    modules = {
      source: "tonhe",
      configured_total: (sxCfg && sxCfg.total_modules != null) ? num(sxCfg.total_modules) : len(th.expected_addresses),
      online_total:  len(th.present_addresses),        // seen on CAN (fresh)
      capable_total: len(th.capable_addresses),        // present & not faulted (working)
      active_total:  len(th.contributing_addresses),   // delivering current
      all_ready:     (th.all_4_can_ready ?? null),
      expected_addresses: th.expected_addresses ?? null,
      present_addresses:  th.present_addresses ?? null,
      missing_addresses:  th.missing_addresses ?? null,           // which modules dropped
      unmapped_addresses: th.active_unmapped_addresses ?? null,
      faults: (Array.isArray(th.fault_summary) && th.fault_summary.length) ? th.fault_summary : null,
      per_group: {}
    };
    if (sx && sx.groups) {
      const cnt = (sxCfg && sxCfg.group_module_count) || {};
      for (const [gk, grp] of Object.entries(sx.groups)) {
        modules.per_group[gk] = {
          configured: (cnt[gk] != null) ? num(cnt[gk]) : null,
          online: popc((grp.online_mask_low ?? 0) >>> 0) + popc((grp.online_mask_high ?? 0) >>> 0),
          voltage: +(num(grp.last_voltage) || 0).toFixed(1),
          current: +(num(grp.last_current) || 0).toFixed(1),
          missing: grp.missing_addresses ?? null
        };
      }
    }
  } else if (sx && sx.groups) {
    // ===== Sinexcel (live per-module online/active) =====
    const FRESH = Number((sxCfg && sxCfg.measure_fresh_ms) || 2000) + 1000;
    modules = { source: "sinexcel", configured_total: null, online_total: 0, active_total: 0, per_group: {} };
    if (sxCfg && sxCfg.group_module_count) {
      modules.configured_total = num(sxCfg.total_modules);
      for (const [gk, cnt] of Object.entries(sxCfg.group_module_count))
        modules.per_group[gk] = { configured: num(cnt), online: 0, reporting: 0, active: 0, voltage: null, current: null };
    }
    for (const [gk, grp] of Object.entries(sx.groups)) {
      if (!modules.per_group[gk]) modules.per_group[gk] = { configured: null, online: 0, reporting: 0, active: 0, voltage: null, current: null };
      const pg = modules.per_group[gk];
      const onlineMask = popc((grp.online_mask_low ?? 0) >>> 0) + popc((grp.online_mask_high ?? 0) >>> 0);
      let reporting = 0, active = 0;
      for (const mod of Object.values(grp.modules || {})) {
        if (mod.ts_current && (now - mod.ts_current) <= FRESH) { reporting++; if (typeof mod.current === "number" && mod.current > 0.5) active++; }
      }
      pg.online = onlineMask || reporting; pg.reporting = reporting; pg.active = active;
      pg.voltage = +(num(grp.last_voltage) || 0).toFixed(1); pg.current = +(num(grp.last_current) || 0).toFixed(1);
    }
    for (const pg of Object.values(modules.per_group)) { modules.online_total += (pg.online || 0); modules.active_total += (pg.active || 0); }
  } else if (g("pm.share_total_modules", null) !== null) {
    // ===== Phoenix CHARX (static config split) =====
    const h1 = num(g("pm.share_h1_modules", null)), h2 = num(g("pm.share_h2_modules", null));
    modules = {
      source: "phoenix_charx",
      configured_total: num(g("pm.share_total_modules", null)),
      share_mode: g("pm.share_mode", null),
      per_group: {
        "1": { configured: h1, allocated_kw: (mp1 !== null) ? +(mp1/1000).toFixed(1) : null, voltage: pm.meas_v,  current: pm.meas_i  },
        "2": { configured: h2, allocated_kw: (mp2 !== null) ? +(mp2/1000).toFixed(1) : null, voltage: pm.meas_v2, current: pm.meas_i2 }
      }
    };
  }
  pm.modules = modules;

  const tv = (k) => { const t = num(mon.io[k]); return (t === null || t < -40 || t > 150) ? null : t; };
  const tfault = [];
  ["t1","t2","t3","t4"].forEach(k => { const r = num(mon.io[k]); if (r !== null && (r < -40 || r > 150)) tfault.push(k); });
  const temps = { t1: tv("t1"), t2: tv("t2"), t3: tv("t3"), t4: tv("t4"), faulty: tfault.length ? tfault : null };

  const estopRaw = num(g("emerstop", null));
  const payload = {
    charger: prefix, ts: new Date().toISOString(),
    connectors: conns, power_module: pm,
    isolation: { iso1: num(g("iso_value1", null)), iso2: num(g("iso_value2", null)), imd_status: g("imd.status", null) },
    temps: temps,
    emergency: g("emerstop", null),
    estop_active: (estopRaw === null ? null : (estopRaw !== 1))
  };

  msg.topic = prefix + "/monitor/state";
  msg.payload = payload;
  msg.qos = 0; msg.retain = true;
  node.status({ fill:"green", shape:"dot",
    text: prefix + " | " + (modules ? modules.source : "no-pm") + " | CN1 " + (conns[1].power_kw ?? "-") + "kW" });
  return msg;
} catch (e) { node.warn("MON builder error: " + e.message); return null; }

// External Fault MQTT collector for BPC_200kW_Br2
//
// NO-GUESS RULES USED HERE:
// 1) Only values that already exist in this flow are consumed.
// 2) Sinexcel bit meanings are mapped by register + bit from the attached
//    SER100040K3B CAN protocol. Reserved bits are ignored.
//    [REV TONHE-BHUTAN-1 09/11/2026] Tonhe (protocol V1.3) registers added: fault_bits (THF, status word
//    byte 5-6), pfc_bits (THP, byte 7), ext_fault (THX, ext frame 0x1C91A0xx byte 2-3), module state 0x11
//    (FAULT_OFF). Error-ID blocks: THF 75/76, THP 77/78, THX 85/86 (group 1/2), FAULT_OFF suffix 11.
//    Sinexcel registers remain mapped (they simply never appear while Tonhe modules are installed).
// 3) PP is NOT promoted to an active error because the existing PP handlers
//    explicitly set PP_MONITOR_ENABLED=false. Its raw value is still published.
// 4) CP state_e/state_f is promoted only after a live state_b/c/d transition,
//    matching the existing CP Fault H1/H2 logic.
// 5) Undefined values are reported as unavailable, not guessed as faults.

const STATUS_TOPIC = "BPC_200kW/fault/status";
const EVENT_TOPIC  = "BPC_200kW/fault/event";
const HEARTBEAT_MS = 30000;
const STATION_ID   = "BPC_200kW";


// ===== Project error IDs (BPC-EC-1.0) =====
