function applyOcpp16(item) {
    const o = OCPP16_EVENT_MAP[item.code];
    if (!o) return item;
    item.short_message = o.info;
    item.ocpp_error_code = o.errorCode;
    item.ocpp_connector_id = o.connectorId;
    item.ocpp_send_policy = o.sendPolicy;
    item.ocpp_mapping = o.mapping;
    item.ocpp_1_6j = {
        connectorId: o.connectorId,
        errorCode: o.errorCode,
        vendorErrorCode: item.error_id || null,
        info: o.info
    };
    return item;
}

function ocppClearCandidate(item) {
    if (!item || item.ocpp_connector_id === undefined || item.ocpp_connector_id === null) return null;
    return {
        connectorId: item.ocpp_connector_id,
        errorCode: "NoError",
        vendorErrorCode: item.error_id || null,
        info: "Issue " + (item.error_id || item.code) + " cleared."
    };
}


function projectErrorId(code, severity, extra) {
    if (Object.prototype.hasOwnProperty.call(EXACT_ERROR_IDS, code)) return EXACT_ERROR_IDS[code];
    let m = String(code || "").match(/^PM_G([12])_A(\d+)_(OFFLINE|AC_OPERATION_ALARM|AC_MONITOR_SHUTDOWN|DC_SHUTDOWN|FAULT_OFF)$/);
    if (m) {
        const group = Number(m[1]);
        const addr = Number(m[2]);
        const kind = m[3];
        const block = group === 1 ? 61 : 62;
        const suffix = kind === "OFFLINE" ? 0 : kind === "AC_OPERATION_ALARM" ? 4 : kind === "AC_MONITOR_SHUTDOWN" ? 5 : kind === "FAULT_OFF" ? 11 : 20;
        const prefix = severity === "alarm" ? "A" : severity === "status" ? "S" : "F";
        return prefix + String(block).padStart(2, "0") + String(addr) + String(suffix).padStart(2, "0");
    }
    m = String(code || "").match(/^PM_G([12])_A(\d+)_(DCF1|DCF2|ACF1|ACF2|THF|THP|THX)_B(\d{2})$/);
    if (m) {
        const group = Number(m[1]);
        const addr = Number(m[2]);
        const reg = m[3];
        const bit = Number(m[4]);
        const blocks = {"DCF1_1":71,"DCF1_2":72,"DCF2_1":73,"DCF2_2":74,"ACF1_1":81,"ACF1_2":82,"ACF2_1":83,"ACF2_2":84,
                        "THF_1":75,"THF_2":76,"THP_1":77,"THP_2":78,"THX_1":85,"THX_2":86};
        const block = blocks[reg + "_" + group];
        const prefix = severity === "alarm" ? "A" : severity === "status" ? "S" : "F";
        if (block) return prefix + String(block).padStart(2, "0") + String(addr) + String(bit).padStart(2, "0");
    }
    return null;
}

const LIVE_CP = new Set(["state_b", "state_c", "state_d"]);
const FAULT_CP = new Set(["state_e", "state_f"]);

let st = context.get("faultState");
if (!st) {
    st = {
        activeFailures: {"1": [], "2": []},
        evError: {"1": "", "2": ""},
        cp: {"1": "", "2": ""},
        cpFaultLatched: {"1": "", "2": ""},
        pp: {"1": "", "2": ""},
        emergencyRaw: null,
        lastFaultMap: {},
        lastSnapshotKey: "",
        lastPublishMs: 0
    };
}

function text(v) {
    if (v === undefined || v === null) return "";
    if (typeof v === "string") return v.trim();
    if (Buffer.isBuffer(v)) return v.toString("utf8").trim();
    if (typeof v === "number" || typeof v === "boolean") return String(v);
    try { return JSON.stringify(v); } catch (e) { return String(v); }
}

function cleanFailure(v) {
    return text(v).replace(/^['\"]+|['\"]+$/g, "").trim();
}

function parseFailureList(v) {
    if (Array.isArray(v)) return [...new Set(v.map(cleanFailure).filter(Boolean))];
    if (v && typeof v === "object") {
        if (Array.isArray(v.active_failures)) {
            return [...new Set(v.active_failures.map(cleanFailure).filter(Boolean))];
        }
    }
    const s = text(v);
    if (!s) return [];
    try {
        const parsed = JSON.parse(s);
        if (Array.isArray(parsed)) {
            return [...new Set(parsed.map(cleanFailure).filter(Boolean))];
        }
    } catch (e) {
        // Continue with CSV parsing; vSECC documentation describes a CSV list.
    }
    return [...new Set(s.split(",").map(cleanFailure).filter(Boolean))];
}

function connectorFromTopic(topic) {
    const m = String(topic || "").match(/^vsecc\/connector\/(\d+)\//);
    return m ? m[1] : null;
}

function safeCode(s) {
    return String(s || "UNKNOWN")
        .toUpperCase()
        .replace(/[^A-Z0-9]+/g, "_")
        .replace(/^_+|_+$/g, "") || "UNKNOWN";
}

function finiteNumber(v) {
    if (v === undefined || v === null || (typeof v === "string" && v.trim() === "")) return null;
    const n = Number(v);
    return Number.isFinite(n) ? n : null;
}

function hex16(v) {
    return "0x" + ((Number(v) || 0) & 0xFFFF).toString(16).toUpperCase().padStart(4, "0");
}

// ---------- Update event-driven state from local vSECC MQTT ----------
const topic = String(msg.topic || "");
const connector = connectorFromTopic(topic);
if (connector === "1" || connector === "2") {
    if (topic.endsWith("/status/components/active_failures")) {
        st.activeFailures[connector] = parseFailureList(msg.payload);
    } else if (topic.endsWith("/status/components/report_failure")) {
        const f = cleanFailure(msg.payload);
        if (f) st.activeFailures[connector] = [...new Set([...(st.activeFailures[connector] || []), f])];
    } else if (topic.endsWith("/status/components/report_resolution")) {
        const f = cleanFailure(msg.payload);
        if (f) st.activeFailures[connector] = (st.activeFailures[connector] || []).filter(x => x !== f);
    } else if (topic.endsWith("/ev/ev_error_code")) {
        st.evError[connector] = text(msg.payload);
    } else if (topic.endsWith("/ev/cp_state")) {
        const cp = text(msg.payload);
        const prev = st.cp[connector] || "";
        if (cp !== prev) {
            if (FAULT_CP.has(cp) && LIVE_CP.has(prev)) {
                st.cpFaultLatched[connector] = cp;
            } else if (!FAULT_CP.has(cp)) {
                st.cpFaultLatched[connector] = "";
            }
            st.cp[connector] = cp;
        }
    } else if (topic.endsWith("/ev/pp_state")) {
        st.pp[connector] = text(msg.payload);
    }
}
if (topic === "vsecc/io/d_in/8/value") {
    st.emergencyRaw = msg.payload;
}

// Fill raw CP values on startup without inventing a fault transition.
for (const h of ["1", "2"]) {
    if (!st.cp[h]) {
        const gcp = global.get("cp_state_head" + h);
        const fallback = global.get("cp_state" + h);
        const current = (gcp !== undefined && gcp !== null) ? gcp : fallback;
        if (current !== undefined && current !== null) st.cp[h] = text(current);
    }
}

const faults = [];
const statusFlags = [];
const faultCodes = new Set();
const statusCodes = new Set();

function addFault(code, source, description, extra) {
    if (faultCodes.has(code)) return;
    faultCodes.add(code);
    const item = Object.assign({
        code,
        severity: "fault",
        source,
        description
    }, extra || {});
    item.error_id = projectErrorId(code, item.severity, item);
    if (!item.error_id) item.error_id_status = "UNMAPPED";
    applyOcpp16(item);
    faults.push(item);
}

function addStatus(code, source, description, extra) {
    if (statusCodes.has(code)) return;
    statusCodes.add(code);
    const item = Object.assign({
        code,
        severity: "status",
        source,
        description
    }, extra || {});
    item.error_id = projectErrorId(code, item.severity, item);
    if (!item.error_id) item.error_id_status = "UNMAPPED";
    statusFlags.push(item);
}

// ---------- Emergency stop (existing flow: d_in/8 is active-low) ----------
const emergencyByGlobal = global.get("emerActive") === true;
const emergencyByInput = finiteNumber(st.emergencyRaw) === 0;
if (emergencyByGlobal || emergencyByInput) {
    addFault("SYS_EMERGENCY_STOP", "vsecc/io/d_in/8/value",
        "Emergency input active (existing flow defines d_in/8 value 0 as pressed)",
        {scope: "station", raw_value: st.emergencyRaw});
}

// ---------- vSECC component failures (authoritative active set) ----------
// ================= FIX#ESD rev3 - emergency-shutdown latch demotion =================
// vSECC latches "evse_triggered_emergency_shutdown" when an emergency shutdown
// fires while an HLC session is running, and only releases it when the vehicle
// is unplugged. From charging-manager-2.log:
//   09:26:57 Emergency Shutdown triggered by: PE_OFFLINE
//   09:26:57 PWM Duty cycle: 100% (EVSE triggered emergency shutdown,
//            waiting for CP state A, then switch to 0% [CP state F])
//   09:28:37 Emergency shutdown was pending and vehicle is now plugged out. Resolving.
// The latch stayed in Active EVSE Failures long after the button was released,
// so OCPP held the connector Faulted for 1:34 / 50:52 / 26:07 / 1:43
// (log 20260811_161836, F12011). Only the head with a cable plugged in is hit,
// because with no cable CP is already state A and the latch never arms.
//
// RULE: while the emergency input is still active the latch stays a FAULT.
//       Once the button is released AND the latch is the only remaining vSECC
//       failure on that head, demote it to a STATUS flag. The connector then
//       falls back to the real PLC status (Finishing = transaction over, waiting
//       for the driver to unplug), which still blocks RemoteStartTransaction.
//       Demotion is sticky: a later unrelated failure (e.g. the pe_connection
//       blip seen at 06:52:52 in charging-manager-1.log) is reported on its own
//       merit and does not re-promote the latch, so F1x011 cannot flap.
//       Pressing the button again re-promotes it to a fault immediately.
//
// Runtime switch: global.set("fault_esd_demote_enabled", false) -> rev2 behaviour
const ESD_RAW = "evse_triggered_emergency_shutdown";
const ESD_DEMOTE_ENABLED = global.get("fault_esd_demote_enabled") !== false;
const emergencyActive = emergencyByGlobal || emergencyByInput;
EXACT_ERROR_IDS["VSECC_H1_EMERGENCY_SHUTDOWN_AWAITING_UNPLUG"] = "S11011";
EXACT_ERROR_IDS["VSECC_H2_EMERGENCY_SHUTDOWN_AWAITING_UNPLUG"] = "S12011";
if (!st.esdDemoted) st.esdDemoted = {"1": false, "2": false};

for (const h of ["1", "2"]) {
    const list = Array.isArray(st.activeFailures[h]) ? st.activeFailures[h] : [];
    const hasEsd = list.indexOf(ESD_RAW) >= 0;
    const others = list.filter(x => x !== ESD_RAW);

    if (!hasEsd) {
        st.esdDemoted[h] = false;          // vSECC released the latch (vehicle unplugged)
    } else if (emergencyActive) {
        st.esdDemoted[h] = false;          // button is pressed -> genuine emergency
    } else if (others.length === 0) {
        st.esdDemoted[h] = true;           // button released, latch alone -> demote
    }                                      // else: keep previous value (sticky)

    for (const raw of list) {
        if (ESD_DEMOTE_ENABLED && raw === ESD_RAW && st.esdDemoted[h]) {
            addStatus("VSECC_H" + h + "_EMERGENCY_SHUTDOWN_AWAITING_UNPLUG",
                "vsecc active_failures",
                "vSECC holds the emergency-shutdown latch until the vehicle is unplugged (CP state A)",
                {connector: Number(h), source_code: raw, latched: true,
                 emergency_input_active: false});
            continue;
        }
        addFault("VSECC_H" + h + "_" + safeCode(raw),
            "vsecc active_failures", "vSECC active failure: " + raw,
            {connector: Number(h), source_code: raw});
    }
}
// ================= end FIX#ESD rev3 =================

// ---------- EV error code: preserve the exact vSECC/EV raw string ----------
for (const h of ["1", "2"]) {
    const raw = st.evError[h] || "";
    if (!raw) continue;
    if (raw.endsWith("_NO_ERROR")) {
        addStatus("EV_H" + h + "_NO_ERROR", "ev_error_code", "EV reports no error",
            {connector: Number(h), source_code: raw});
    } else if (raw.endsWith("_NO_DATA")) {
        addStatus("EV_H" + h + "_NO_DATA", "ev_error_code", "EV error-code data is not available",
            {connector: Number(h), source_code: raw});
    } else {
        addFault("EV_H" + h + "_" + safeCode(raw), "ev_error_code",
            "EV error code: " + raw,
            {connector: Number(h), source_code: raw});
    }
}

// ---------- CP fault, matching the existing live -> state_e/state_f edge rule ----------
for (const h of ["1", "2"]) {
    const cpFault = st.cpFaultLatched[h];
    if (cpFault) {
        addFault("H" + h + "_CP_" + safeCode(cpFault), "cp_state",
            "CP changed from a live state (b/c/d) to " + cpFault,
            {connector: Number(h), cp_state: cpFault});
    }
}

// ---------- PP is raw-only because the existing PP monitor is disabled ----------
for (const h of ["1", "2"]) {
    if (st.pp[h] === "faulted" || st.pp[h] === "fault") {
        addStatus("H" + h + "_PP_" + safeCode(st.pp[h]) + "_MONITOR_DISABLED", "pp_state",
            "PP reports a fault-like value, but the existing flow has PP monitoring disabled",
            {connector: Number(h), pp_state: st.pp[h], monitor_enabled: false});
    }
}

// ================= FIX#SIMOVL rev1 - opt-in simulation overlay =================
// อ่านอย่างเดียว ไม่เขียน global ของระบบชาร์จ ปิดอยู่โดย default
//   global.set("fault_sim_overlay", {enabled:true, pm:{...}, imd:{...}, temp:{...}})
// pm   : {"<group>": {"<addr>": {or:{dc_fault1,dc_fault2,ac_fault1,ac_fault2},
//                               ac_op_status:<n>, offline:true}}}
// imd  : {"1"|"2": {active:true, iso_value:0}}
// temp : {"temperature1".."temperature4": <degC>}
// ถ้าไม่มี overlay หรือ enabled ไม่ใช่ true -> พฤติกรรมเท่ากับ rev3 ทุกประการ
//
// ข้อกำหนดด้านความปลอดภัยที่บังคับในโค้ดนี้
//   1. bit ของ fault ถูก OR ทับ ไม่ลบของจริง -> overlay ซ่อน fault จริงไม่ได้
//   2. online mask ถูก "เคลียร์" เท่านั้น (บังคับ offline) ไม่เคยเซ็ตให้ online
//   3. ไม่มีการเขียน sinexcel_state / imd* / iso_value* / temperature* กลับไป
//   4. ประกาศไว้ตรงนี้เพราะบล็อก IMD ด้านล่างรันก่อนส่วน Sinexcel
const SIMOVL = (function () {
    const o = global.get("fault_sim_overlay");
    return (o && typeof o === "object" && o.enabled === true) ? o : null;
})();

function simOverlaySinexcel(src, pm, cfgModules) {
    const out = {groups: {}};
    const srcGroups = src.groups || {};
    for (const k of Object.keys(srcGroups)) out.groups[k] = srcGroups[k];
    for (const g of Object.keys(pm)) {
        const base = out.groups[g] || {};
        const ng = Object.assign({}, base);
        ng.modules = Object.assign({}, base.modules || {});
        const lowKnown = base.online_mask_low !== undefined && base.online_mask_low !== null;
        // ถ้ายังไม่รู้ mask จริง ให้ถือว่าโมดูลที่ config ไว้ online ทั้งหมดก่อน
        // จะได้ไม่เผลอทำให้ทั้งกลุ่มกลายเป็น offline พร้อมกัน
        let low = lowKnown ? ((Number(base.online_mask_low) || 0) >>> 0) : 0;
        if (!lowKnown) {
            const list = Array.isArray(cfgModules[g]) ? cfgModules[g] :
                         (Array.isArray(cfgModules[Number(g)]) ? cfgModules[Number(g)] : []);
            for (const a of list) {
                const n = Number(a);
                if (n >= 1 && n <= 31) low = (low | (1 << n)) >>> 0;
            }
        }
        let touchedMask = false;
        for (const a of Object.keys(pm[g])) {
            const spec = pm[g][a] || {};
            const m = Object.assign({}, ng.modules[a] || {});
            const regs = ["dc_fault1", "dc_fault2", "ac_fault1", "ac_fault2"];
            for (const r of regs) {
                if (spec.or && spec.or[r]) {
                    m[r] = (((Number(m[r]) || 0) | (Number(spec.or[r]) || 0)) & 0xFFFF);
                }
            }
            if (spec.ac_op_status !== undefined && Number(m.ac_op_status) !== 0x0004) {
                m.ac_op_status = Number(spec.ac_op_status);
            }
            ng.modules[a] = m;
            const addr = Number(a);
            if (spec.offline === true && addr >= 1 && addr <= 31) {
                low = (low & ~(1 << addr)) >>> 0;   // เคลียร์เท่านั้น ไม่เคยเซ็ต
                touchedMask = true;
            }
        }
        if (lowKnown || touchedMask) ng.online_mask_low = low;
        out.groups[g] = ng;
    }
    return out;
}
// ================= end FIX#SIMOVL rev1 =================

