// ================= FIX#ACMASK rev1 - AC feed (Mag) gating =================
// PROBLEM (OCPP log 2026-08-11 11:14:05..11:14:10):
//   While Mag1(R1,d_out/1) / Mag2(R2,d_out/2) are open there is no AC on the
//   Sinexcel modules, so every module correctly reports AC phase loss and PFC
//   failure. The collector published them as OCPP Faulted, which is noise:
//     ACF1_B01/B02/B03 (AC phase A/B/C loss)  -> F81101.. F82303
//     DCF2_B03         (PFC failure)          -> F73103.. F74303
//   Mag only closes when a gun is plugged into a car (cp_state b/c/d).
//
// RULE (rev2): two independent conditions must BOTH hold before an AC-absence
//       code is published:
//         1. the module group's AC feed is presumed ON (Mag aux contact closed,
//            or a gun is plugged and CP is live), and
//         2. the code has stayed asserted continuously for AC_HOLD_MS.
//       rev1 used a fixed 5 s settle timer. Log 20260811_133153 shows the
//       modules need ~11-12 s from plug-in before the bits clear, so the gate
//       opened too early and produced an ~6 s burst of 20 codes, 8 times in
//       16 minutes. A persistence hold-off removes the transient entirely
//       while still reporting a genuine sustained AC loss after AC_HOLD_MS.
//       Everything else (overtemp, hardware, CAN loss, overcurrent, offline,
//       IMD, emergency stop, CP state E/F...) is untouched.
//
// Group -> Mag mapping (Digital_i/o tab):
//   group 1 <- Mag1_status  <- vsecc/io/d_in/7/value
//   group 2 <- Mag2_status  <- vsecc/io/d_in/6/value
//
// Runtime switches (no redeploy needed):
//   global.set("fault_mask_ac_enabled",  false) -> disable the whole gate
//   global.set("fault_mask_ac_extended", true)  -> also mask the EXTENDED set
//   global.set("fault_mask_ac_hold_ms", 45000) -> change the hold-off time
const AC_GATE_ENABLED  = global.get("fault_mask_ac_enabled") !== false;
const AC_GATE_EXTENDED = global.get("fault_mask_ac_extended") === true;
const AC_HOLD_MS = (Number(global.get("fault_mask_ac_hold_ms")) > 0)
    ? Number(global.get("fault_mask_ac_hold_ms")) : 30000;
const MAG_CLOSED_VALUE = 1;   // d_in aux contact: 1 = contactor closed
const MAG_GLOBAL_BY_GROUP = {"1": "Mag1_status", "2": "Mag2_status"};

// CORE = observed in the log while Mag was open. Masked by default.
const PM_BRAND_TONHE = ((global.get("sinexcel_cfg") || {}).pm_brand === "tonhe");
// Tonhe: no AC on the module -> input undervoltage / phase loss / PFC shutdown / mains freq+imbalance / phase
// exception, and (if the module has no auxiliary supply) the module disappears from CAN -> OFFLINE is gated too.
const AC_OFF_MASK_CORE = ["ACF1_B01", "ACF1_B02", "ACF1_B03", "DCF2_B03",
                          "THF_B00", "THF_B01", "THF_B11", "THP_B01", "THP_B02", "THP_B06"]
                          .concat(PM_BRAND_TONHE ? ["OFFLINE", "FAULT_OFF"] : []);   // rev2: Tonhe reports 0x11 while AC is off
// EXTENDED = same physical cause (no AC / dead DC bus) but not seen on this
// site yet. OFF by default so nothing real gets hidden.
const AC_OFF_MASK_EXTENDED = ["ACF1_B00", "ACF1_B05", "ACF2_B01", "ACF2_B05",
                              "ACF2_B06", "ACF2_B07", "DCF1_B12", "AC_OP_ALARM",
                              "THF_B08", "THP_B05", "THP_B07", "THX_B00", "THX_B02"];

if (!st.acHold || Array.isArray(st.acHold)) st.acHold = {};
delete st.acGate;   // rev1 leftover

function cpIsLive(h) {
    const v = text(st.cp[h] || global.get("cp_state" + h) || "");
    return LIVE_CP.has(v);
}

// Is the AC feed of this module group expected to be energised right now?
// Deliberately permissive: any evidence that AC should be on starts the
// hold-off clock. Being permissive here can never hide a fault, because the
// hold-off below is what actually suppresses the transient.
function acPresumedOn(groupKey) {
    const fb = finiteNumber(global.get(MAG_GLOBAL_BY_GROUP[String(groupKey)]));
    if (fb !== null && fb === MAG_CLOSED_VALUE) return true;
    // case3..case6 in Digital_i/o close BOTH Mag when either gun goes live
    return cpIsLive("1") || cpIsLive("2");
}

const acMasked = [];
const acSeen = {};
function acOffMasked(groupKey, bitKey, code) {
    if (!AC_GATE_ENABLED) return false;
    const hit = (AC_OFF_MASK_CORE.indexOf(bitKey) >= 0) ||
                (AC_GATE_EXTENDED && AC_OFF_MASK_EXTENDED.indexOf(bitKey) >= 0);
    if (!hit) return false;

    // AC feed open -> pure noise, drop it and reset the clock
    if (!acPresumedOn(groupKey)) {
        delete st.acHold[code];
        acMasked.push(code);
        return true;
    }

    // AC feed on: publish only after the code has persisted for AC_HOLD_MS
    acSeen[code] = true;
    const now = Date.now();
    if (st.acHold[code] === undefined) { st.acHold[code] = now; }
    if ((now - st.acHold[code]) < AC_HOLD_MS) { acMasked.push(code); return true; }
    return false;
}
// =============== end FIX#ACMASK rev2 ===============

const sinCfg = global.get("sinexcel_cfg") || {};
const configuredModules = sinCfg.group_modules || {1:[1,2], 2:[1,2]};
const tonheAddr = (sinCfg.tonhe && sinCfg.tonhe.group_addr) || {};   // REV TONHE-BHUTAN-1: real CAN address per group index
let sinState = global.get("sinexcel_state") || {groups:{}};
if (SIMOVL && SIMOVL.pm && typeof SIMOVL.pm === "object") {
    sinState = simOverlaySinexcel(sinState, SIMOVL.pm, configuredModules);   // FIX#SIMOVL rev1
}
const pmRaw = {groups:{}};

function bitIsSet(word, bit) {
    return ((((Number(word) || 0) >>> 0) >>> bit) & 1) === 1;
}

function decodeWord(group, addr, register, word) {
    if (word === undefined || word === null) return;
    const n = Number(word) & 0xFFFF;
    for (const def of PM_MAP[register]) {
        if (!bitIsSet(n, def.bit)) continue;
        // REV TONHE-BHUTAN-2: Tonhe 9.1.1 note 1 - bit7 (hardware fault) is also set whenever any of bit8-13 is set,
        // so it is only a real hardware fault when none of bit8-13 is present (log 09/11: bit7 + bit11 on every AC-off).
        if (register === "fault_bits" && def.bit === 7 && ((n & 0x3F00) !== 0)) continue;
        const regCode = register === "dc_fault1" ? "DCF1" :
                        register === "dc_fault2" ? "DCF2" :
                        register === "ac_fault1" ? "ACF1" :
                        register === "ac_fault2" ? "ACF2" :
                        register === "fault_bits" ? "THF" :
                        register === "pfc_bits" ? "THP" : "THX";
        const source = (regCode === "THF" || regCode === "THP" || regCode === "THX") ? "Tonhe CAN" : "Sinexcel CAN";
        const bitKey = regCode + "_B" + String(def.bit).padStart(2, "0");
        const code = "PM_G" + group + "_A" + addr + "_" + bitKey;
        if (acOffMasked(group, bitKey, code)) continue;   // FIX#ACMASK rev1
        const extra = {
            group: Number(group), module_address: Number(addr), register,
            bit: def.bit, register_value: hex16(n), name: def.key
        };
        if (def.severity === "status") {
            addStatus(code, source, def.description, extra);
        } else {
            addFault(code, source, def.description,
                Object.assign({severity: def.severity}, extra));
        }
    }
}

for (const groupKey of ["1", "2"]) {
    const groupState = (sinState.groups || {})[groupKey] || {};
    const modules = Array.isArray(configuredModules[groupKey]) ? configuredModules[groupKey] :
                    Array.isArray(configuredModules[Number(groupKey)]) ? configuredModules[Number(groupKey)] : [];
    const lowKnown = groupState.online_mask_low !== undefined && groupState.online_mask_low !== null;
    const highKnown = groupState.online_mask_high !== undefined && groupState.online_mask_high !== null;
    const lowMask = (Number(groupState.online_mask_low) || 0) >>> 0;
    const highMask = (Number(groupState.online_mask_high) || 0) >>> 0;
    pmRaw.groups[groupKey] = {
        configured_modules: modules,
        online_mask_low: lowKnown ? "0x" + lowMask.toString(16).toUpperCase().padStart(8, "0") : null,
        online_mask_high: highKnown ? "0x" + highMask.toString(16).toUpperCase().padStart(8, "0") : null,
        modules: {}
    };

    for (const rawAddr of modules) {
        const addr = Number(rawAddr);
        if (!Number.isFinite(addr)) continue;
        let online = null;
        if (addr >= 1 && addr <= 31 && lowKnown) online = (((lowMask >>> addr) & 1) === 1);
        else if (addr >= 32 && addr <= 63 && highKnown) online = (((highMask >>> (addr - 32)) & 1) === 1);
        const offlineCode = "PM_G" + groupKey + "_A" + addr + "_OFFLINE";
        if (online === false && !acOffMasked(groupKey, "OFFLINE", offlineCode)) {   // REV TONHE-BHUTAN-1: gated for Tonhe
            addFault(offlineCode, PM_BRAND_TONHE ? "Tonhe online mask" : "Sinexcel online mask",
                "Configured power module is not online in the module online mask",
                {group: Number(groupKey), module_address: addr,
                 can_address: (Array.isArray(tonheAddr[groupKey]) ? tonheAddr[groupKey][addr - 1] : undefined)});
        }

        const mod = (groupState.modules || {})[String(addr)] || {};
        pmRaw.groups[groupKey].modules[String(addr)] = {
            online,
            dc_op_status: mod.dc_op_status !== undefined ? hex16(mod.dc_op_status) : null,
            ac_op_status: mod.ac_op_status !== undefined ? hex16(mod.ac_op_status) : null,
            dc_fault1: mod.dc_fault1 !== undefined ? hex16(mod.dc_fault1) : null,
            dc_fault2: mod.dc_fault2 !== undefined ? hex16(mod.dc_fault2) : null,
            ac_fault1: mod.ac_fault1 !== undefined ? hex16(mod.ac_fault1) : null,
            ac_fault2: mod.ac_fault2 !== undefined ? hex16(mod.ac_fault2) : null,
            ts_op_status: mod.ts_op_status || null,
            ts_fault: mod.ts_fault || null,
            // Tonhe raw (REV TONHE-BHUTAN-1)
            can_address: mod.addr !== undefined ? mod.addr : null,
            state: mod.state !== undefined ? mod.state : null,
            fault_bits: mod.fault_bits !== undefined ? hex16(mod.fault_bits) : null,
            pfc_bits: mod.pfc_bits !== undefined ? hex16(mod.pfc_bits) : null,
            ext_status: mod.ext_status !== undefined ? hex16(mod.ext_status) : null,
            ext_fault: mod.ext_fault !== undefined ? hex16(mod.ext_fault) : null
        };

        decodeWord(groupKey, addr, "dc_fault1", mod.dc_fault1);
        decodeWord(groupKey, addr, "dc_fault2", mod.dc_fault2);
        decodeWord(groupKey, addr, "ac_fault1", mod.ac_fault1);
        decodeWord(groupKey, addr, "ac_fault2", mod.ac_fault2);
        // Tonhe registers (REV TONHE-BHUTAN-1)
        decodeWord(groupKey, addr, "fault_bits", mod.fault_bits);
        decodeWord(groupKey, addr, "pfc_bits", mod.pfc_bits);
        decodeWord(groupKey, addr, "ext_fault", mod.ext_fault);
        const faultOffCode = "PM_G" + groupKey + "_A" + addr + "_FAULT_OFF";
        if (Number(mod.state) === 0x11 && !acOffMasked(groupKey, "FAULT_OFF", faultOffCode)) {   // rev2: gated like AC-loss bits
            addFault(faultOffCode, "Tonhe CAN",
                "Module status byte = 0x11 (fault OFF state)",
                {group:Number(groupKey), module_address:addr, can_address: mod.addr, state:"0x11", severity:"fault"});
        }

        const acOpAlarmCode = "PM_G" + groupKey + "_A" + addr + "_AC_OPERATION_ALARM";
        if (Number(mod.ac_op_status) === 0x0004 &&
            !acOffMasked(groupKey, "AC_OP_ALARM", acOpAlarmCode)) {   // FIX#ACMASK rev1
            addFault("PM_G" + groupKey + "_A" + addr + "_AC_OPERATION_ALARM", "Sinexcel CAN",
                "AC operating status is Alarm (0x0004)",
                {group:Number(groupKey), module_address:addr, ac_op_status:"0x0004"});
        } else if (Number(mod.ac_op_status) === 0x0005) {
            addStatus("PM_G" + groupKey + "_A" + addr + "_AC_MONITOR_SHUTDOWN", "Sinexcel CAN",
                "AC operating status is Monitor shutdown (0x0005)",
                {group:Number(groupKey), module_address:addr, ac_op_status:"0x0005"});
        }
        if (Number(mod.dc_op_status) === 0x0020) {
            addStatus("PM_G" + groupKey + "_A" + addr + "_DC_SHUTDOWN", "Sinexcel CAN",
                "DC operating status is failed shutdown or command shutdown (0x0020)",
                {group:Number(groupKey), module_address:addr, dc_op_status:"0x0020"});
        }
    }
}

// FIX#ACMASK rev2: forget hold-off timers for codes that are no longer asserted
