// ===== FIX#SOC rev2 (19 ส.ค. 2026): Hard stop เมื่อ SoC ถึง 90% =====
//
// ทำไมต้องมี rev2:
//   rev1 ยืนยันด้วย "จำนวน sample ที่ >= TARGET ครบ 3 ครั้ง"
//   แต่ vSECC publish topic vsecc/connector/N/ev/soc **เฉพาะตอนค่าเปลี่ยน**
//   -> 3 sample = SoC ขยับ 3 ขั้น = ตัดที่ TARGET+2 (92%) ไม่ใช่ 90%
//   ยืนยันจาก charging-manager-2 วันที่ 2026-08-19:
//     08:44:49 SoC=90 ค้าง 219 วินาที  -> ไม่ตัด
//     08:48:28 SoC=91 ค้าง 218 วินาที  -> ไม่ตัด
//     08:52:06 SoC=92 (dwell 0.0 วิ)   -> ตัดทันทีที่ค่าเปลี่ยน
//     อีกเคส 08:58:27 92 -> 09:02:05 93 -> 09:05:43 94 ตัดที่ 94
//
// rev2 แก้เป็น: ยืนยันด้วย "เวลา" + รับ tick ทุก 1 วินาที
//   -> SoC >= TARGET ต่อเนื่องครบ CONFIRM_MS แล้วตัด ไม่ขึ้นกับจังหวะ publish
//
// อินพุต : mqtt in  vsecc/connector/1|2/ev/soc   และ  inject tick (topic = "tick")
// เอาต์พุต: [0] -> .../1/preview/stop_charging "1"   [1] -> .../2/preview/stop_charging "1"

const TARGET_SOC = 90;     // <<<<< ปรับเปอร์เซ็นต์ตรงนี้จุดเดียว
const CONFIRM_MS = 3000;   // ต้องอยู่ >= TARGET ต่อเนื่องเท่านี้ก่อนตัด (กันค่าเพี้ยนแวบเดียว)
const SOC_MIN = 1, SOC_MAX = 100;
const MAX_DROP = 20;       // ค่าดิ่งลงเกินเท่านี้ในครั้งเดียว = glitch เริ่มนับใหม่

const DEAD = /(SessionStop|Terminate|Stopped|Finished|WeldingDetection)/i;
const inCD = function (s) { return /current[_\s-]?demand/i.test(String(s || '')); };
const now  = Date.now();

function stOf(h) {
    let s = context.get('h' + h);
    if (!s) s = { latched: false, lastSoc: null, aboveSince: 0 };
    return s;
}
function put(h, s) { context.set('h' + h, s); }

// รีอาร์มเมื่อถอดสายหรือ session ตาย
function rearmIfIdle(h) {
    const cp   = String(global.get('cp_state_head' + h) || '');
    const sess = String(global.get('session_state_head' + h) || '');
    if (cp === 'state_a' || sess === '' || DEAD.test(sess)) {
        if (cp === 'state_a') global.set('socHold' + h, false);   // FIX#SELFSTOP rev1: ถอดสายเท่านั้นถึงปลด latch
        const s = stOf(h);
        if (s.latched || s.aboveSince || s.lastSoc !== null) {
            put(h, { latched: false, lastSoc: null, aboveSince: 0 });
        }
        return true;
    }
    return false;
}

function ready(h) {
    const s = stOf(h);
    if (s.latched)                                   return false;
    if (global.get('socHold' + h) === true)          return false;   // FIX#SELFSTOP rev1: ตัดไปแล้วในรอบเสียบนี้
    if (s.lastSoc === null || s.lastSoc < TARGET_SOC) return false;
    if (!s.aboveSince || (now - s.aboveSince) < CONFIRM_MS) return false;
    const cp   = String(global.get('cp_state_head' + h) || '');
    const sess = String(global.get('session_state_head' + h) || '');
    const cs   = String(global.get(h === 1 ? 'pep.charging_state' : 'pep.charging_state2') || '');
    if (!inCD(sess))                                 return false;   // ห้ามยิงตอน CableCheck/PreCharge
    if (cs !== 'charge')                             return false;
    if (cp !== 'state_c' && cp !== 'state_d')        return false;
    return true;
}

function fire(h) {
    const s = stOf(h);
    const held = ((now - s.aboveSince) / 1000).toFixed(1);
    s.latched = true;
    put(h, s);
    // ===== FIX#SELFSTOP rev1: กันรถ retry แล้วชาร์จ-ตัดวนซ้ำหลัง 90% =====
    // log ตู้นี้: หลังตัด รถต่อ session ใหม่เอง -> guard ตัดซ้ำทุก ~40-90 วิ (contactor สับถี่ทั้งวัน)
    // แก้: latch socHold ต่อรอบเสียบ + เคลียร์ startCommanded -> รอบ retry จะถูก ARCH2 กั๊ก 0 A นิ่ง ๆ
    // ปลด latch เมื่อถอดสาย (state_a) เท่านั้น
    global.set('socHold' + h, true);
    global.set('startCommanded' + h, false);
    node.warn('FIX#SOC rev2: หัว ' + h + ' SoC=' + s.lastSoc + '% >= ' + TARGET_SOC
            + '% ต่อเนื่อง ' + held + 's -> stop_charging');
    return { payload: "1" };
}

// ---- 1) รับข้อความ ----
const topic = String(msg.topic || '');
if (topic.indexOf('/ev/soc') >= 0) {
    const h = (topic.indexOf('/connector/2/') >= 0) ? 2 : 1;
    let raw = msg.payload;
    if (raw !== null && typeof raw === 'object') {
        raw = (raw.value   !== undefined) ? raw.value
            : (raw.soc     !== undefined) ? raw.soc
            : (raw.payload !== undefined) ? raw.payload : NaN;
    }
    const soc = Number(raw);
    if (!rearmIfIdle(h)) {
        const s = stOf(h);
        if (!isFinite(soc) || soc < SOC_MIN || soc > SOC_MAX) {
            s.aboveSince = 0;                      // 0 / 255 = รถไม่รายงาน -> ไม่นับ
        } else if (s.lastSoc !== null && (s.lastSoc - soc) > MAX_DROP) {
            s.lastSoc = soc; s.aboveSince = 0;     // glitch ดิ่งลง -> เริ่มนับใหม่
        } else {
            s.lastSoc = soc;
            if (soc >= TARGET_SOC) { if (!s.aboveSince) s.aboveSince = now; }
            else                   { s.aboveSince = 0; }
        }
        put(h, s);
