// Tell the button-sync node which mode we are in, so it does not force 0x8700=1.
global.set("admin_login_required", REQUIRE_LOGIN);

function lockFrame() { return Buffer.from([0x5A, 0xA5, 0x05, 0x82, 0x87, 0x00, 0x00, 0x00]); }
function unlockFrame() { return Buffer.from([0x5A, 0xA5, 0x05, 0x82, 0x87, 0x00, 0x00, 0x01]); }

// ---------- MODE B: no login required -> permanently unlocked ----------
if (!REQUIRE_LOGIN) {
    flow.set("admin_auth", true);
    flow.set("admin_session", true);
    if (context.get("lastLock") !== 1) {
        context.set("lastLock", 1);
        node.status({ fill: "green", shape: "dot", text: "NO LOGIN mode - 0x8700 = 1 (unlocked)" });
        msg.payload = unlockFrame();
        return msg;
    }
    node.status({ fill: "green", shape: "ring", text: "NO LOGIN mode (unlocked)" });
    return null;
}

