const VP_LOGIN = 0x3300;   // Login / submit
const VP_LOGOUT = 0x3400;   // Logout
const VP_CLEAR_1 = 0x7700;   // Clear PIN
const VP_CLEAR_2 = 0x3450;   // Clear PIN (2nd button)

const VP_PWD_1 = 0x3500, VP_PWD_2 = 0x3600, VP_PWD_3 = 0x3700, VP_PWD_4 = 0x7000, VP_PWD_5 = 0x7100;
const VP_PWD_6 = 0x7200, VP_PWD_7 = 0x7300, VP_PWD_8 = 0x7400, VP_PWD_9 = 0x7500, VP_PWD_0 = 0x7600;

const ALL_PWD_KEYS = [VP_PWD_1, VP_PWD_2, VP_PWD_3, VP_PWD_4, VP_PWD_5,
    VP_PWD_6, VP_PWD_7, VP_PWD_8, VP_PWD_9, VP_PWD_0];
const DIGIT_VP = {
    "0": VP_PWD_0, "1": VP_PWD_1, "2": VP_PWD_2, "3": VP_PWD_3, "4": VP_PWD_4,
    "5": VP_PWD_5, "6": VP_PWD_6, "7": VP_PWD_7, "8": VP_PWD_8, "9": VP_PWD_9
};

const CORRECT_SEQ = String(ADMIN_PASSWORD).split("").map(function (d) { return DIGIT_VP[d]; });
if (!CORRECT_SEQ.length || CORRECT_SEQ.some(function (v) { return v === undefined; })) {
    node.status({ fill: "red", shape: "ring", text: "ADMIN_PASSWORD must be digits 0-9 only" });
    node.warn("Admin Numpad: ADMIN_PASSWORD '" + ADMIN_PASSWORD + "' is invalid - digits 0-9 only.");
    return null;
}

const VALID_VPS = [VP_ADMIN_BTN, VP_LOGIN, VP_LOGOUT, VP_CLEAR_1, VP_CLEAR_2].concat(ALL_PWD_KEYS);

const vp = msg.payload && msg.payload.vp_raw;
if (!VALID_VPS.includes(vp)) return null;

function clearAdminTimers() {
    const t1 = context.get("authTimer");
    const t2 = context.get("pwdTimer");
    if (t1) clearTimeout(t1);
    if (t2) clearTimeout(t2);
    context.set("authTimer", null);
    context.set("pwdTimer", null);
}

// ---- Logout ----
if (vp === VP_LOGOUT) {
    clearAdminTimers();
    flow.set("admin_auth", false);
    flow.set("admin_session", false);
    flow.set("pwd_seq", []);
    node.status({ fill: "grey", shape: "ring", text: "Logged out -> 0x8700 = 0" });
    msg.payload = lockFrame();
    return msg;
}

// ---- Admin button: start a PIN entry session ----
if (vp === VP_ADMIN_BTN) {
    clearAdminTimers();
    flow.set("admin_auth", false);
    flow.set("pwd_seq", []);
    flow.set("admin_session", true);
    node.status({ fill: "yellow", shape: "ring", text: "Admin mode: waiting for PIN..." });

    const pwdTimer = setTimeout(function () {
        flow.set("admin_session", false);
        flow.set("admin_auth", false);
        flow.set("pwd_seq", []);
        node.status({
            fill: "grey", shape: "ring",
            text: "PIN entry timeout (" + AUTH_TIMEOUT_MINUTES + " min) -> 0x8700 = 0"
        });
        node.send({ payload: lockFrame() });
    }, PIN_ENTRY_TIMEOUT_SECONDS * 1000);
    context.set("pwdTimer", pwdTimer);
    return null;
}

// ---- everything below needs an open PIN session ----
if (!(flow.get("admin_session") || false)) return null;

// ---- Clear ----
if (vp === VP_CLEAR_1 || vp === VP_CLEAR_2) {
    flow.set("pwd_seq", []);
    node.status({ fill: "yellow", shape: "ring", text: "PIN cleared" });
    return null;
}

// ---- digit pressed ----
if (ALL_PWD_KEYS.includes(vp)) {
    const seq = flow.get("pwd_seq") || [];
    seq.push(vp);
    flow.set("pwd_seq", seq);
    node.status({
        fill: "yellow", shape: "dot",
        text: "PIN: " + seq.length + "/" + CORRECT_SEQ.length + " entered"
    });
    return null;
}

// ---- Login ----
if (vp === VP_LOGIN) {
    clearAdminTimers();
    const seq = flow.get("pwd_seq") || [];
    const ok = seq.length === CORRECT_SEQ.length &&
        seq.every(function (v, i) { return v === CORRECT_SEQ[i]; });

    if (ok) {
        flow.set("admin_auth", true);
        flow.set("admin_session", false);
        flow.set("pwd_seq", []);
        node.status({
            fill: "green", shape: "dot",
            text: "Login OK -> 0x8700 = 1 (" + AUTH_TIMEOUT_MINUTES + " min)"
        });

        const authTimer = setTimeout(function () {
            flow.set("admin_auth", false);
            node.status({ fill: "grey", shape: "ring", text: "Session expired -> 0x8700 = 0" });
            node.send({ payload: lockFrame() });
        }, AUTH_TIMEOUT_MINUTES * 60 * 1000);
        context.set("authTimer", authTimer);

        msg.payload = unlockFrame();
        return msg;
    }

    flow.set("admin_auth", false);
    flow.set("admin_session", false);
    flow.set("pwd_seq", []);
    node.status({ fill: "red", shape: "dot", text: "Wrong PIN" });
    msg.payload = lockFrame();
    return msg;
}

return null;

// ===== Robust DWIN Stream Parser (Zero Drop / Rapid Touch Fix) =====
// Accumulates serial stream, aligns to 0x5A 0xA5 header, and extracts ALL packets

let rxBuf = context.get("rxBuf") || Buffer.alloc(0);
if (msg.payload && Buffer.isBuffer(msg.payload)) {
    rxBuf = Buffer.concat([rxBuf, msg.payload]);
}

const msgs = [];

while (rxBuf.length >= 3) {
    // 1. Find DWIN Header 0x5A 0xA5
    let idx = -1;
    for (let i = 0; i < rxBuf.length - 1; i++) {
        if (rxBuf[i] === 0x5A && rxBuf[i + 1] === 0xA5) {
            idx = i;
            break;
        }
    }

    if (idx === -1) {
        rxBuf = Buffer.alloc(0); // clear garbage
        break;
    }
    if (idx > 0) {
        rxBuf = rxBuf.slice(idx); // align to header
    }
    if (rxBuf.length < 3) break;

    const pktLen = rxBuf[2]; // bytes following length byte
    const totalLen = pktLen + 3;

    if (rxBuf.length < totalLen) {
        // Incomplete frame, wait for next serial chunk
        break;
    }

    // Extract full frame
    const frame = rxBuf.slice(0, totalLen);
    rxBuf = rxBuf.slice(totalLen);

    const cmd = frame[3];
    if (cmd !== 0x83) continue; // Only process read/touch VP responses (0x83)

    const vp = (frame[4] << 8) | frame[5];
    let value = 0;

    if (pktLen >= 6 && frame.length >= 9) {
        value = (frame[7] << 8) | frame[8];
    } else if (pktLen >= 5 && frame.length >= 8) {
        value = (frame[6] << 8) | frame[7];
    }

    msgs.push({
        payload: {
            vp: "0x" + vp.toString(16).toUpperCase().padStart(4, "0"),
            vp_raw: vp,
            value: value,
            raw: frame.toString("hex").match(/.{1,2}/g).join(" ")
        }
    });
}

context.set("rxBuf", rxBuf);

if (!msgs.length) return null;

// Status of latest VP parsed
const lastPkt = msgs[msgs.length - 1].payload;
node.status({ fill: "green", shape: "dot", text: `VP:${lastPkt.vp} = ${lastPkt.value} (${msgs.length} pkts)` });

// Return array of msgs so Node-RED outputs all parsed touch frames
return [msgs];

// ===== Return Key HEAD1 (VP 0x6100) V.5 - Anti-Stuck & Fault Guard =====
const VP_RETURN_H1 = 0x6100;
const VP_ICON_H1 = 0x6000;

const val = msg.value ?? msg.payload?.value ?? msg.payload ?? 0;
if (!val || val <= 0) return null;

{
    // Gate on state: If not charging (0), unplug (5), or insulation fault (4), set selection
    const _st0 = flow.get("h1_state") ?? 1;
    if (_st0 !== 0 && _st0 !== 5 && _st0 !== 4) flow.set("selectedHead", "h1");
}

const h1_cpState = flow.get("h1_cpState") ?? "";
const h1_state = flow.get("h1_state") ?? 1;
const h1_prePlugBeforeSelect = flow.get("h1_prePlugBeforeSelect") ?? false;

const frames = [];

// Clear button ACK frame
frames.push(Buffer.from([0x5A, 0xA5, 0x05, 0x82, 0x61, 0x00, 0x00, 0x00]));

// ── STICKY SCREENS: touch must not move these ──
// 5 = Unplug (hold until car is removed)
// 0 = Charging (in progress)
// 4 = Insulation Fault (high voltage hazard! Must stay on screen until cable unplugged)
{
    const _st = flow.get("h1_state") ?? 1;
    if (_st !== 0 && _st !== 5 && _st !== 4) {
        if (flow.get("h1_chgHold")) flow.set("h1_chgHold", false);
        if (flow.get("h1_locked")) flow.set("h1_locked", false);
    } else {
        node.status({
            fill: _st === 4 ? "red" : (_st === 5 ? "orange" : "purple"), shape: "dot",
            text: "H1 touch ignored - " + (_st === 4 ? "insulation fault" : (_st === 5 ? "please unplug" : "charging"))
        });
        msg.payload = Buffer.from([0x5A, 0xA5, 0x05, 0x82, 0x61, 0x00, 0x00, 0x00]);  // ACK button only
        return msg;
    }
}

flow.set("h1_returnKeyPressed", true);
flow.set("h1_blinkToggle", true);

if (h1_cpState === "state_b" || h1_cpState === "state_c" || h1_prePlugBeforeSelect) {
    flow.set("h1_state", 3);
    flow.set("h1_prePlugBeforeSelect", false);
    frames.push(Buffer.from([0x5A, 0xA5, 0x05, 0x82, 0x60, 0x00, 0x00, 0x03]));
    node.status({ fill: "yellow", shape: "dot", text: "H1 pressed in " + h1_cpState + " → State 3" });

} else {
    flow.set("h1_state", 2);
    frames.push(Buffer.from([0x5A, 0xA5, 0x05, 0x82, 0x60, 0x00, 0x00, 0x02]));
    node.status({ fill: "yellow", shape: "dot", text: "H1 pressed → State 2" });
}

msg.payload = Buffer.concat(frames);
return msg;

