msg.payload = Buffer.concat(frames);
return msg;

function applyLang(state, lang) {
    if (state >= 1 && state <= 6) {
        if (lang === 2) return state + 6;
        if (lang === 3) return state + 12;
    }
    return state;
}

const VP_ICON_H1 = 0x6000;
const VP_ICON_H2 = 0x6200;
const STATE_BLINK_OFF = 6;

const h1r = flow.get("h1_reset") ?? 0;
if (h1r > 0) {
    flow.set("h1_reset", h1r - 1);
    flow.set("h1_blinkToggle", true);
    flow.set("h2ResetSent", false);
    node.status({ fill: "grey", shape: "ring", text: "Reset (no blink)" });
    return null;
}

const currentState = flow.get("h1_state") ?? 1;
const lang = flow.get("language_mode") ?? 1;
const frames = [];

// ถ้า H1 กำลังชาร์จ → ต้องค้าง state 0 เท่านั้น
if (currentState === 0) {
    frames.push(Buffer.from([
        0x5A, 0xA5, 0x05, 0x82,
        (VP_ICON_H1 >> 8) & 0xFF, VP_ICON_H1 & 0xFF,
        0x00, applyLang(0, lang) & 0xFF
    ]));
    msg.payload = Buffer.concat(frames);
    node.status({ fill: "green", shape: "dot", text: "Charging (state 0)" });
    return msg;
}

if (currentState !== 2 && currentState !== 3) {
    context.set("h1_blinkStart", 0);      // not blinking -> reset the idle timer
    flow.set("h1_blinkToggle", true);
    node.status({ fill: "grey", shape: "ring", text: "State " + currentState + " (no blink)" });
    return null;
}

// ── Idle-timeout: 10s on the AVAILABLE screen (state 2) -> back to Idle ──
// Preparing (state 3) is deliberately NOT timed out.
if (currentState === 2) {
    const _now = Date.now();
    const _seen = context.get("h1_blinkSeenState") ?? -1;
    let _t0 = context.get("h1_blinkStart") ?? 0;
    if (!_t0 || _seen !== currentState) {      // entered Available -> (re)start timer
        _t0 = _now;
        context.set("h1_blinkStart", _t0);
        context.set("h1_blinkSeenState", currentState);
    }
    if (_now - _t0 >= 10000) {
        context.set("h1_blinkStart", 0);
        context.set("h1_blinkSeenState", -1);
        flow.set("h1_state", 1);
        flow.set("h1_returnKeyPressed", false);   // needs a fresh touch to wake again
        flow.set("h1_blinkToggle", true);
        if (flow.get("selectedHead") === "h1") flow.set("selectedHead", "");
        msg.payload = Buffer.from([
            0x5A, 0xA5, 0x05, 0x82,
            (VP_ICON_H1 >> 8) & 0xFF, VP_ICON_H1 & 0xFF,
            0x00, applyLang(1, lang) & 0xFF
        ]);
        node.status({ fill: "blue", shape: "dot", text: "Available timeout 10s -> Idle" });
        return msg;
    }
} else {
    context.set("h1_blinkStart", 0);          // not on Available -> timer off
    context.set("h1_blinkSeenState", -1);
}

const h2_cpState = flow.get("h2_cpState") ?? "";
const h2_state_now = flow.get("h2_state") ?? 1;
const h2_locked_now = flow.get("h2_locked") ?? false;
const h2ResetSent = flow.get("h2ResetSent") ?? false;
const selectedHead = flow.get("selectedHead") ?? "";

// Protected: Charging (0), Insulation Fault (4), or Please Unplug (5)
const h2_isProtected =
    h2_locked_now ||
    h2_cpState === "state_c" ||
    h2_state_now === 0 ||
    h2_state_now === 4 ||     // Insulation Fault screen protected!
    h2_state_now === 5 ||     // on the Unplug screen -> protected too
    flow.get("h2_chgHold");   // charging head protected (chgHold survives kW dips)

// reset H2 ได้เฉพาะตอนที่ H2 ไม่ได้ชาร์จ, ไม่ติด fault, และไม่ได้อยู่หน้า unplug
if (!h2ResetSent && selectedHead === "h1" && !h2_isProtected) {
    flow.set("h2_state", 1);
    flow.set("h2_returnKeyPressed", false);
    flow.set("h2_reset", 2);
    flow.set("h2ResetSent", true);

    frames.push(Buffer.from([
        0x5A, 0xA5, 0x05, 0x82,
        (VP_ICON_H2 >> 8) & 0xFF, VP_ICON_H2 & 0xFF,
        0x00, applyLang(1, lang) & 0xFF
    ]));
}

// ── Blink speed: bigger = slower. Full on+off cycle = 2 x BLINK_MS ──
const BLINK_MS = 700;            // <-- change this number to slow/speed the blink
let toggle = flow.get("h1_blinkToggle") ?? true;
const lastT = context.get("h1_blinkLastT") ?? 0;
const now = Date.now();
if (now - lastT >= BLINK_MS) {        // only flip after BLINK_MS has passed
    toggle = !toggle;
    flow.set("h1_blinkToggle", toggle);
    context.set("h1_blinkLastT", now);
}

const sendState = toggle ? currentState : STATE_BLINK_OFF;

frames.push(Buffer.from([
    0x5A, 0xA5, 0x05, 0x82,
    (VP_ICON_H1 >> 8) & 0xFF, VP_ICON_H1 & 0xFF,
    0x00, applyLang(sendState, lang) & 0xFF
]));

msg.payload = Buffer.concat(frames);
node.status({ fill: "yellow", shape: "dot", text: "Blink: " + sendState });
return msg;

