// ===== QR Show (STEADY, no blink) — write QR text on the touched/selected side =====
// Left  = HEAD1 -> VP 0x6660 ; Right = HEAD2 -> VP 0x7770
const VP_QR_L = 0x6660;
const VP_QR_R = 0x7770;

// ---- QR content + when to show -----------------------------------------
const QR_L = "3VB-T00-301";   // HEAD1 (left) QR value
const QR_R = "3VB-T00-302";   // HEAD2 (right) QR value
const TOUCH_STATES = [2, 3];  // states where the QR appears (2=Selected, 3=Preparing)
// ------------------------------------------------------------------------

const h1 = flow.get("h1_state") ?? 1;
const h2 = flow.get("h2_state") ?? 1;

// DWIN text write: 5A A5 LEN 82 vpHi vpLo <ascii...> FF FF   (FFFF = string end / clears trailing)
function writeText(vp, text) {
    const data = Buffer.concat([Buffer.from(String(text), "ascii"), Buffer.from([0xFF, 0xFF])]);
    const len = 3 + data.length;
    const header = Buffer.from([0x5A, 0xA5, len & 0xFF, 0x82, (vp >> 8) & 0xFF, vp & 0xFF]);
    return Buffer.concat([header, data]);
}

// STEADY: write the QR text while touched/selected; write empty (clears it) otherwise
const valL = TOUCH_STATES.includes(h1) ? QR_L : "";
const valR = TOUCH_STATES.includes(h2) ? QR_R : "";

// dedup: only write when show/hide actually changes (QR stays solid, no re-sends)
const last = context.get("qrLast") || {};
const frames = [];
if (last.L !== valL) { frames.push(writeText(VP_QR_L, valL)); last.L = valL; }
if (last.R !== valR) { frames.push(writeText(VP_QR_R, valR)); last.R = valR; }
context.set("qrLast", last);

node.status({ fill: (valL || valR) ? "green" : "grey", shape: "dot",
    text: "L:" + (valL || "off") + "  R:" + (valR || "off") });

if (!frames.length) return null;
msg.payload = Buffer.concat(frames);
return msg;

function writeVP(vp, value) {
    let v = Number(value);
    if (!isFinite(v)) v = 0;
    v = Math.round(v);
    if (v < 0) v = 0;
    if (v > 65535) v = 65535;
    return Buffer.from([
        0x5A, 0xA5, 0x05, 0x82,
        (vp >> 8) & 0xFF, vp & 0xFF,
        (v >> 8) & 0xFF, v & 0xFF
    ]);
}

function writeText(vp, text, maxLen = 32) {
    const s = (text ?? "").toString().padEnd(maxLen, " ").slice(0, maxLen);
    const textBytes = Buffer.from(s, "ascii");
    const len = 3 + textBytes.length;
    const header = Buffer.from([
        0x5A, 0xA5, len & 0xFF, 0x82,
        (vp >> 8) & 0xFF, vp & 0xFF
    ]);
    return Buffer.concat([header, textBytes]);
}

const SESSION_STOP_STATES = new Set([
    "SessionStop",
    "VSECCLIB_SST_DIN_SessionStop"
]);

// ===== CONFIG: Fixed Max Power Limit (kW) =====
// Synchronized with flow context (configured in 'Max Power Fixed' node)
const FIXED_MAX_POWER_H1 = 180;

const p = msg.payload || {};
const cpState = p.cp_state1 || "";
const csState = p.cs_state1 || "";

// Fixed max power limit for HEAD1 (VP 0x1600)
const _fix1 = flow.get("maxpower_fix1") ?? global.get("maxpower_fix1");
p.powerLimit1 = (Number(_fix1) > 0) ? Number(_fix1) : FIXED_MAX_POWER_H1;

// Ensure VP 0x9800 receives 0 on insulation fault, 1 on normal
if (p.Insu1 === undefined || p.Insu1 === null) {
    p.Insu1 = flow.get("h1_insuFault") ? 0 : 1;
}

const lang = flow.get("language_mode") || 1;
const forceLang = flow.get("force_lang_state") || false;

const VP_NUM = {
    w_ccs1: 0x5100,
    soc_ccs1: 0x5200,
    tfullsoc1: 0x4000,
    tv_ccs1: 0x5300,
    v_ccs1: 0x5400,
    ta_ccs1: 0x5500,
    a_ccs1: 0x5600,
    emerstop: 0x9100,
    H1_Finishing: 0x9600,
    Insu1: 0x9800,
    powerLimit1: 0x1600
};

const VP_TEXT = {
    cp_state1: 0x5700,
    cs_state1: 0x5800
};

// Per-VP dedup. DGUS VPs are persistent in the HMI, so re-sending an
// unchanged value is pure wasted serial bandwidth. Only emit a frame for a
// VP whose value actually changed since we last sent it.
const last = context.get("lastVP") || {};
const frames = [];

// Re-send power limit upon state/screen transitions so newly loaded screens never miss it
const curH1State = flow.get("h1_state");
const lastH1State = context.get("lastH1State");
if (curH1State !== undefined && curH1State !== lastH1State) {
    context.set("lastH1State", curH1State);
    delete last["n_powerLimit1"];
}

// Periodic refresh (every 5 seconds) to ensure screen always shows power limit
let plRefreshTick = (context.get("plRefreshTick") || 0) + 1;
if (plRefreshTick >= 5) {
    plRefreshTick = 0;
    delete last["n_powerLimit1"];
}
context.set("plRefreshTick", plRefreshTick);

/* ---------- 0x3800 realtime language icon (EN=6, TH=7, BH=8) ---------- */
if (cpState === "state_c" && Number(p.w_ccs1) > 0) {
    let icon = 6;
    if (lang === 2) icon = 7;
    if (lang === 3) icon = 8;
    if (last["i_3800"] !== icon) {
        frames.push(writeVP(0x3800, icon));
        last["i_3800"] = icon;
    }
}

/* ---------- numeric ---------- */
for (const [key, vp] of Object.entries(VP_NUM)) {
    if (p[key] === undefined || p[key] === null) continue;

    let valueToSend = p[key];
    if (key === "emerstop") {
        const v = Number(p[key]);
        if (v === 0) valueToSend = lang;
        else if (v === 1) valueToSend = 0;
    }
    if (last["n_" + key] !== valueToSend) {
        frames.push(writeVP(vp, valueToSend));
        last["n_" + key] = valueToSend;
    }
}

/* ---------- text ---------- */
for (const [key, vp] of Object.entries(VP_TEXT)) {
    if (p[key] === undefined || p[key] === null) continue;
    if (last["t_" + key] !== p[key]) {
        frames.push(writeText(vp, p[key], 32));
        last["t_" + key] = p[key];
    }
}

context.set("lastVP", last);

if (!frames.length) return null;
msg.payload = Buffer.concat(frames);
return msg;

// ===== DWIN DGUS: CCS2 map payload -> VP write frames (per-VP dedup) =====
function writeVP(vp, value) {
    let v = Number(value);
    if (!isFinite(v)) v = 0;
    v = Math.round(v);
    if (v < 0) v = 0;
    if (v > 65535) v = 65535;
    return Buffer.from([
        0x5A, 0xA5, 0x05, 0x82,
        (vp >> 8) & 0xFF, vp & 0xFF,
        (v >> 8) & 0xFF, v & 0xFF
    ]);
}

function writeText(vp, text, maxLen = 32) {
    const s = (text ?? "").toString().padEnd(maxLen, " ").slice(0, maxLen);
    const textBytes = Buffer.from(s, "ascii");
    const len = 3 + textBytes.length;
    const header = Buffer.from([
        0x5A, 0xA5, len & 0xFF, 0x82,
        (vp >> 8) & 0xFF, vp & 0xFF
    ]);
    return Buffer.concat([header, textBytes]);
}

const SESSION_STOP_STATES = new Set([
    "SessionStop",
    "VSECCLIB_SST_DIN_SessionStop"
]);

// ===== CONFIG: Fixed Max Power Limit (kW) =====
// Synchronized with flow context (configured in 'Max Power Fixed' node)
const FIXED_MAX_POWER_H2 = 180;

const p = msg.payload || {};
const _fix2 = flow.get("maxpower_fix2") ?? global.get("maxpower_fix2");
p.powerLimit2 = (Number(_fix2) > 0) ? Number(_fix2) : FIXED_MAX_POWER_H2;

// Ensure VP 0x9900 receives 0 on insulation fault, 1 on normal
if (p.Insu2 === undefined || p.Insu2 === null) {
    p.Insu2 = flow.get("h2_insuFault") ? 0 : 1;
}
const cpState = p.cp_state2 || "";
const csState = p.cs_state2 || "";

// keep the original side effects (state machine reads these as fallback)
if (cpState) flow.set("h2_cpState", cpState);
if (csState) flow.set("h2_cs_state", csState);

const lang = flow.get("language_mode") || 1;
const forceLang = flow.get("force_lang_state") || false;

const VP_NUM = {
    w_ccs2: 0x5000,
    soc_ccs2: 0x1000,
    tfullsoc2: 0x4100,
    tv_ccs2: 0x1400,
    v_ccs2: 0x2200,
    ta_ccs2: 0x1800,
    a_ccs2: 0x2600,
    temp1_ccs2: 0x3000,
    temp2_ccs2: 0x3100,
    mv_ccs2: 0x2400,
    ma_ccs2: 0x2800,
    H2_Finishing: 0x9700,
    Insu2: 0x9900,
    powerLimit2: 0x1700
};

const VP_TEXT = {
    cp_state2: 0x7800,
    cs_state2: 0x8000
};

// Per-VP dedup (DGUS VPs persist in the HMI; only send real changes).
const last = context.get("lastVP") || {};
const frames = [];

// Re-send power limit upon state/screen transitions so newly loaded screens never miss it
const curH2State = flow.get("h2_state");
const lastH2State = context.get("lastH2State");
if (curH2State !== undefined && curH2State !== lastH2State) {
    context.set("lastH2State", curH2State);
    delete last["n_powerLimit2"];
}

// Periodic refresh (every 5 seconds) to ensure screen always shows power limit
let plRefreshTick2 = (context.get("plRefreshTick2") || 0) + 1;
if (plRefreshTick2 >= 5) {
    plRefreshTick2 = 0;
    delete last["n_powerLimit2"];
}
context.set("plRefreshTick2", plRefreshTick2);

/* ---------- 0x2000 realtime language icon (EN=6, TH=7, BH=8) ---------- */
if (cpState === "state_c" && Number(p.w_ccs2) > 0) {
    let chargeIcon = 6;
    if (lang === 2) chargeIcon = 7;
    if (lang === 3) chargeIcon = 8;
    if (last["i_2000"] !== chargeIcon) {
        frames.push(writeVP(0x2000, chargeIcon));
        last["i_2000"] = chargeIcon;
    }
}

/* ---------- numeric ---------- */
for (const [key, vp] of Object.entries(VP_NUM)) {
    if (p[key] === undefined || p[key] === null) continue;
    if (last["n_" + key] !== p[key]) {
        frames.push(writeVP(vp, p[key]));
        last["n_" + key] = p[key];
    }
}

/* ---------- text ---------- */
for (const [key, vp] of Object.entries(VP_TEXT)) {
    if (p[key] === undefined || p[key] === null) continue;
    if (last["t_" + key] !== p[key]) {
        frames.push(writeText(vp, p[key], 32));
        last["t_" + key] = p[key];
    }
}

context.set("lastVP", last);

if (!frames.length) return null;
msg.payload = Buffer.concat(frames);
return msg;

// =========================================================
// ===== CONFIG: Fixed Max Power Limit (kW) ================
// To change max power, simply edit the number below (no injector needed):
const FIXED_MAX_POWER = 180; // Default max power for both heads (kW)

const FIXED_MAX_POWER_H1 = FIXED_MAX_POWER; // Head 1 limit (kW) -> VP 0x1600
const FIXED_MAX_POWER_H2 = FIXED_MAX_POWER; // Head 2 limit (kW) -> VP 0x1700
// =========================================================

// Keep flow and global context updated so all nodes share the exact same value
flow.set("maxpower_fix1", FIXED_MAX_POWER_H1);
flow.set("maxpower_fix2", FIXED_MAX_POWER_H2);
global.set("maxpower_fix1", FIXED_MAX_POWER_H1);
global.set("maxpower_fix2", FIXED_MAX_POWER_H2);

function writeVP(vp, val) {
    val = Math.max(0, Math.min(65535, Math.round(Number(val) || 0)));
    return Buffer.from([
        0x5A, 0xA5, 0x05, 0x82,
        (vp >> 8) & 0xFF, vp & 0xFF,
        (val >> 8) & 0xFF, val & 0xFF
    ]);
}

const v1 = FIXED_MAX_POWER_H1;
const v2 = FIXED_MAX_POWER_H2;

const last = context.get("mpLast") || {};
const frames = [];

// Periodic heartbeat: Re-send to DWIN screen every 3 seconds to guarantee
// that if the screen reboots, changes page, or drops a packet, it always shows the max value!
const tick = ((context.get("mpTick") || 0) + 1) % 3;
context.set("mpTick", tick);
const heartbeat = (tick === 0);

if (last.h1 !== v1 || heartbeat) {
    frames.push(writeVP(0x1600, v1));
    last.h1 = v1;
}
if (last.h2 !== v2 || heartbeat) {
    frames.push(writeVP(0x1700, v2));
    last.h2 = v2;
}
context.set("mpLast", last);

node.status({
    fill: "green",
    shape: "dot",
    text: "H1=" + v1 + "kW | H2=" + v2 + "kW (FIXED" + (heartbeat ? " ⟳" : "") + ")"
});

if (!frames.length) return null;
msg.payload = Buffer.concat(frames);
return msg;

function applyLang(state, lang) {
    if (state >= 1 && state <= 6) {
        if (lang === 2) return state + 6;
        if (lang === 3) return state + 12;
    }
    return state;
}

function resetPrev() {
    context.set("prevState", -1);
    context.set("prevLang", -1);
}

function makeVP(vp, state) {
    return Buffer.from([
        0x5A, 0xA5, 0x05, 0x82,
        (vp >> 8) & 0xFF, vp & 0xFF,
        0x00, state & 0xFF
    ]);
}

const lang = flow.get("language_mode") ?? 1;
const VP_ICON = 0x6000;
const VP_EMER = 0x9100;

const p = msg.payload || {};
const cpState = p.cp_state1 || "";
const csState = p.cs_state1 || "";

let unplug = (p.H1_Finishing !== undefined && p.H1_Finishing !== null)
    ? Number(p.H1_Finishing)
    : (flow.get("h1_finishing_val") ?? 0);

let currentState = flow.get("h1_state") ?? 1;
let returnKeyPressed = flow.get("h1_returnKeyPressed") ?? false;

// 🚨 1. Detect Emergency Stop
const _emerRaw = (p.emerstop !== undefined && p.emerstop !== null) ? p.emerstop
    : (p.emerStop_9100 !== undefined && p.emerStop_9100 !== null) ? p.emerStop_9100
    : (flow.get("EmergencyStop") !== undefined && flow.get("EmergencyStop") !== null) ? flow.get("EmergencyStop")
    : null;
const isEmergency = (_emerRaw !== null && Number(_emerRaw) === 0);
flow.set("isEmergencyStop", isEmergency);
global.set("isEmergencyStop", isEmergency);

const activeCpState = cpState || flow.get("h1_cpState") || flow.get("CPStateCCS1") || "";
const activeCsState = csState || flow.get("h1_cs_state") || flow.get("SessionStateCCS1") || "";
const h1Power = (p.w_ccs1 !== undefined && p.w_ccs1 !== null) ? Number(p.w_ccs1) : (flow.get("h1_power") ?? 0);
flow.set("h1_power", h1Power);

// 🛡️ 2. Robust Multi-Channel Detection of Insulation Fault (CCS1 ONLY - STRICT SEPARATION)
const rawInsu1 = p.Insu1 ?? p.Insu_CCS1 ?? flow.get("Insu_CCS1") ?? global.get("iso_value1") ?? null;
let isInsulationFault = false;
if (rawInsu1 !== null) {
    if (rawInsu1 === 0 || rawInsu1 === "0" || rawInsu1 === false || String(rawInsu1).toLowerCase() === "fault" || String(rawInsu1).toLowerCase() === "failed") {
        isInsulationFault = true;
    }
}

const snap = global.get("external_fault_snapshot");
if (!isInsulationFault && snap && Array.isArray(snap.issues)) {
    for (const it of snap.issues) {
        // STRICTLY check Connector 1 (never match connector 2):
        const isH1 = (it.connector === 1 || it.connector === "1" ||
                      /^[FAS]11\d{3}$/i.test(String(it.error_id || "")) ||
                      /11001/.test(String(it.error_id || "")) ||
                      (!it.connector && /H1|CCS1/i.test(String(it.short_message || it.description || ""))));
        const notH2 = (it.connector !== 2 && it.connector !== "2" &&
                       !/^[FAS]12\d{3}$/i.test(String(it.error_id || "")) &&
                       !/12001/.test(String(it.error_id || "")) &&
                       !/H2|CCS2/i.test(String(it.short_message || it.description || "")));
        if (isH1 && notH2) {
            const isIso = /isolation|insulat/i.test(String(it.short_message || "")) ||
                          /isolation|insulat/i.test(String(it.description || "")) ||
                          /isolation|insulat/i.test(String(it.code || "")) ||
                          /isolation|insulat/i.test(String(it.error_id || "")) ||
                          /11001/.test(String(it.error_id || it.code || ""));
            if (isIso) {
                isInsulationFault = true;
                break;
            }
        }
    }
}

if (!isInsulationFault && /Isolation.*Fault|CableCheck.*Fault|IsoFault/i.test(activeCsState)) {
    isInsulationFault = true;
}

// 🚀 3. REMOTE START & STOP DETECTION
const isRemoteStart = (global.get("h1_remoteStarted") === true || flow.get("h1_remoteActive") === true);
const wasRemoteStart = context.get("h1_wasRemoteStart") ?? false;

const isRemoteStop = (global.get("h1_stopCommanded") === true || global.get("manualStop1") === true ||
                      flow.get("h1_stopCommanded") === true || p.remoteStop1 === 1 || p.RemoteStop1 === 1);

if (isRemoteStart && !wasRemoteStart) {
    flow.set("h1_finishing_val", 0);
    global.set("H1_Finishing", 0);
    global.set("h1_stopCommanded", false);
    global.set("manualStop1", false);
    flow.set("h1_stopCommanded", false);
    unplug = 0;
    context.set("h1_hadPower", false);
    context.set("h1_charging", true);
    context.set("h1_unplugCnt", 0);
}
context.set("h1_wasRemoteStart", isRemoteStart);

if (h1Power > 0.5 || (activeCpState === "state_c" && /CurrentDemand/.test(activeCsState))) {
    context.set("h1_hadPower", true);
}
const hadPower = (context.get("h1_hadPower") === true);

const inHandshake = /CableCheck|PreCharge|PowerDelivery|SupportedAppProtocol|SessionSetup|Authorization|ChargeParameterDiscovery/i.test(activeCsState);

// ⏱️ 4. DETECT COMPLETE, TIMEOUT, OR STOP WHILE PLUGGED:
const isComplete = (p.Complete1 === 1 || p.Complete1 === true || p.Complete1 === "true" ||
                    p.Complete_CCS1 === 1 || p.Complete_CCS1 === true || p.Complete_CCS1 === "true" ||
                    flow.get("Complete_CCS1") === 1 || flow.get("Complete_CCS1") === true);

const isSessionStop = /SessionStop|Timeout|Time_Out|Failed|WeldingDetection|Abort|Terminated/i.test(activeCsState);

const wasCharging = (context.get("h1_charging") === true || currentState === 0);
const powerDropped = (!inHandshake && hadPower && wasCharging && h1Power <= 0 && (activeCpState === "state_b" || isComplete));

const isPlugged = (activeCpState === "state_b" || activeCpState === "state_c" || activeCpState === "state_d");

const remoteStopped = isPlugged && (isRemoteStop || (wasCharging && !isRemoteStart));
const stoppedWhileCharging = (wasCharging && (powerDropped || isComplete || isSessionStop) && isPlugged);

let isFinishing = (unplug === 1 || flow.get("h1_finishing_val") === 1 || global.get("H1_Finishing") === 1 ||
                   remoteStopped || stoppedWhileCharging || (isPlugged && isComplete) || (isPlugged && isSessionStop));

if (inHandshake && !remoteStopped && !isComplete && !isSessionStop) {
    isFinishing = false;
}

if (activeCpState === "state_a") {
    unplug = 0;
}

// ── 🚨 Emergency Stop Active ─────────────────────────────
if (isEmergency) {
    let emerState = 1;
    if (lang === 2) emerState = 2;
    if (lang === 3) emerState = 3;

    context.set("h1_emerActive", true);
    const isPlg = (activeCpState !== "state_a" && activeCpState !== "");
    const frames = [makeVP(VP_EMER, emerState)];

    if (isPlg) {
        flow.set("h1_state", 5);
        global.set("h1_state", 5);
        flow.set("h1_finishing_val", 1);
        global.set("H1_Finishing", 1);
        flow.set("h1_locked", false);
        flow.set("h1_prePlugBeforeSelect", false);
        flow.set("h1_remoteActive", false);
        global.set("h1_remoteStarted", false);
        context.set("h1_charging", false);
        context.set("h1_hadPower", false);

        const s5 = applyLang(5, lang);
        if (context.get("prevState") !== 5 || context.get("prevLang") !== lang) {
            frames.push(makeVP(VP_ICON, s5));
            context.set("prevState", 5);
            context.set("prevLang", lang);
        }
        node.status({ fill: "red", shape: "dot", text: "⚠️ EmerStop: H1 Plugged -> State 5 (Please Unplug)" });
    } else {
        flow.set("h1_state", 1);
        global.set("h1_state", 1);
        flow.set("h1_returnKeyPressed", false);
        flow.set("h1_locked", false);
        flow.set("h1_remoteActive", false);
        global.set("h1_remoteStarted", false);
        context.set("h1_charging", false);
        context.set("h1_hadPower", false);

        const s1 = applyLang(1, lang);
        if (context.get("prevState") !== 1 || context.get("prevLang") !== lang) {
            frames.push(makeVP(VP_ICON, s1));
            context.set("prevState", 1);
            context.set("prevLang", lang);
        }
        node.status({ fill: "red", shape: "ring", text: "⚠️ EmerStop: H1 Unplugged -> State 1 (Idle)" });
    }

    if (!frames.length) return null;
    msg.payload = Buffer.concat(frames);
    return msg;
}

// ── Emergency Released Edge ──────────────────────────────
if (context.get("h1_emerActive")) {
    context.set("h1_emerActive", false);
    context.set("h1_emerSent", 0);
    resetPrev();
    const isPlg = (activeCpState !== "state_a" && activeCpState !== "");
    const frames = [makeVP(VP_EMER, 0)];
    if (isPlg) {
        currentState = 5;
        flow.set("h1_state", 5);
        global.set("h1_state", 5);
        flow.set("h1_finishing_val", 1);
        global.set("H1_Finishing", 1);
        frames.push(makeVP(VP_ICON, applyLang(5, lang)));
        context.set("prevState", 5);
        context.set("prevLang", lang);
        node.status({ fill: "orange", shape: "dot", text: "EmerStop released -> 0x9100=0 | Plugged -> State 5" });
    } else {
        currentState = 1;
        flow.set("h1_state", 1);
        global.set("h1_state", 1);
        frames.push(makeVP(VP_ICON, applyLang(1, lang)));
        context.set("prevState", 1);
        context.set("prevLang", lang);
        node.status({ fill: "blue", shape: "dot", text: "EmerStop released -> 0x9100=0 | Unplugged -> State 1" });
    }
    context.set("h1_emerRepaint", 3);
    msg.payload = Buffer.concat(frames);
    return msg;
}

// ── Reset Command (e.g. debug inject) ───────────────────
if ((flow.get("h1_reset") ?? 0) > 0) {
    flow.set("h1_reset", (flow.get("h1_reset") ?? 0) - 1);
    const h1_cpState_now = flow.get("h1_cpState") ?? "";
    const h1_state_now = flow.get("h1_state") ?? 1;

    // Never reset if Charging (0) OR in Insulation Fault (4)!
    if (h1_cpState_now !== "state_c" && h1_state_now !== 0 && h1_state_now !== 4) {
        flow.set("h1_state", 1);
        global.set("h1_state", 1);
        flow.set("h1_returnKeyPressed", false);
        flow.set("h1_locked", false);
        flow.set("h1_cpState", "");
        flow.set("h1_cs_state", "");
        flow.set("h1_prePlugBeforeSelect", false);
        flow.set("h1_finishing_val", 0);
        global.set("H1_Finishing", 0);
        global.set("h1_stopCommanded", false);
        global.set("manualStop1", false);
        flow.set("h1_stopCommanded", false);
        flow.set("h1_insuFault", false);
        context.set("h1_charging", false);
        context.set("h1_hadPower", false);
        resetPrev();
        node.status({ fill: "blue", shape: "dot", text: "Reset → State 1" });
        return null;
    }
    node.status({ fill: "grey", shape: "ring", text: "Reset skipped (" + (h1_state_now === 4 ? "InsuFault" : "Charging") + ")" });
    return null;
