// ── State Machine ─────────────────────────────────────────

// ── 🚨 1. INSULATION FAULT (State 4): CCS1 ONLY, INDEPENDENT CHECK & DISPLAY ──
if (isInsulationFault || currentState === 4 || flow.get("h1_insuFault")) {
    if (activeCpState === "state_a") {
