        flow.set("h1_state", 4);
        global.set("h1_state", 4);
        flow.set("h1_insuFault", true);
        flow.set("h1_locked", false);
        flow.set("h1_remoteActive", false);
        global.set("h1_remoteStarted", false);
        context.set("h1_charging", false);
        context.set("h1_hadPower", false);
        flow.set("h1_prePlugBeforeSelect", false);
        node.status({ fill: "red", shape: "dot", text: "⚠️ H1 INSULATION FAULT (State 4) | cp:" + activeCpState });
    }

// ── ⚡ 2. PLEASE UNPLUG STATE (State 5): LATCHED UNTIL PHYSICALLY UNPLUGGED (state_a) ──
} else if (currentState === 5 || isFinishing) {
    if (activeCpState === "state_a") {
        const sa = (context.get("h1_unplugCnt") ?? 0) + 1;
        context.set("h1_unplugCnt", sa);
        if (sa >= 2) {
            context.set("h1_unplugCnt", 0);
            currentState = 1;
            returnKeyPressed = false;
            flow.set("h1_locked", false);
            flow.set("h1_prePlugBeforeSelect", false);
            flow.set("h1_finishing_val", 0);
