        }
    } else {
        context.set("h1_unplugCnt", 0);
        currentState = 5;
        flow.set("h1_state", 5);
        global.set("h1_state", 5);
        flow.set("h1_finishing_val", 1);
        global.set("H1_Finishing", 1);
        context.set("h1_charging", false);
        context.set("h1_hadPower", false);
        flow.set("h1_locked", false);
        global.set("h1_remoteStarted", false);
        flow.set("h1_remoteActive", false);
        flow.set("h1_prePlugBeforeSelect", false);
        node.status({ fill: "orange", shape: "dot", text: "🔌 Stopped/Finished -> PLEASE UNPLUG (cp:" + activeCpState + ")" });
    }

// ── 3. Unplugged Edge (state_a) ──────────────────────────
} else if (activeCpState === "state_a") {
    context.set("h1_charging", false);
    context.set("h1_hadPower", false);
    flow.set("h1_locked", false);
    if (returnKeyPressed && (currentState === 2 || flow.get("h1_state") === 2)) {
        currentState = 2;
