// ── ⚡ 4. CHARGING STATE (State 0): ONLY when remote_start is active AND not finished! ──
} else if ((activeCpState === "state_b" || activeCpState === "state_c") && isRemoteStart && !isFinishing) {
    currentState = 0;
    context.set("h1_charging", true);
    flow.set("h1_locked", true);
