flow.set("h1_state", currentState);
global.set("h1_state", currentState);
flow.set("h1_returnKeyPressed", returnKeyPressed);
if (cpState) flow.set("h1_cpState", cpState);
if (cpState) global.set("h1_cpState", cpState);
if (csState) flow.set("h1_cs_state", csState);

