}

const prevState = context.get("prevState") ?? -1;
const prevLang = context.get("prevLang") ?? -1;
if (currentState === prevState && lang === prevLang) return null;

context.set("prevState", currentState);
context.set("prevLang", lang);

msg.payload = makeVP(VP_ICON, applyLang(currentState, lang));
node.status({
