});
return msg;

function applyLang(state, lang) {
    if (state >= 1 && state <= 6) {
        if (lang === 2) return state + 6;
        if (lang === 3) return state + 12;
    }
    return state;
}

function resetPrev() {
    context.set("prevState", -1);
    context.set("prevLang", -1);
}

function makeVP(vp, state) {
    return Buffer.from([
        0x5A, 0xA5, 0x05, 0x82,
        (vp >> 8) & 0xFF, vp & 0xFF,
        0x00, state & 0xFF
    ]);
}

const lang = flow.get("language_mode") ?? 1;
const VP_ICON = 0x6200;

const p = msg.payload || {};
const cpState = p.cp_state2 || "";
const csState = p.cs_state2 || "";

