                      /^[FAS]12\d{3}$/i.test(String(it.error_id || "")) ||
                      /12001/.test(String(it.error_id || "")) ||
                      (!it.connector && /H2|CCS2/i.test(String(it.short_message || it.description || ""))));
        const notH1 = (it.connector !== 1 && it.connector !== "1" &&
                       !/^[FAS]11\d{3}$/i.test(String(it.error_id || "")) &&
                       !/11001/.test(String(it.error_id || "")) &&
                       !/H1|CCS1/i.test(String(it.short_message || it.description || "")));
        if (isH2 && notH1) {
