}

flow.set("h2_state", currentState);
global.set("h2_state", currentState);
flow.set("h2_returnKeyPressed", returnKeyPressed);
if (cpState) flow.set("h2_cpState", cpState);
if (cpState) global.set("h2_cpState", cpState);
if (csState) flow.set("h2_cs_state", csState);

