function applyLang(state, lang) {
    if (state >= 1 && state <= 6) {
        if (lang === 2) return state + 6;
        if (lang === 3) return state + 12;
    }
    return state;
}

const vp = msg.payload?.vp_raw;

let langChanged = false;


/* language select */
if (vp === 37376) { //0x9200
    flow.set("language_mode", 1);
    flow.set("force_lang_state", true);
    langChanged = true;
}

if (vp === 37632) { //0x9300
    flow.set("language_mode", 2);
    flow.set("force_lang_state", true);
    langChanged = true;
}

if (vp === 37888) { //0x9400
    flow.set("language_mode", 3);
    flow.set("force_lang_state", true);
    langChanged = true;
}


/* no language event */
if (!langChanged) {
    return null;
}


const lang = flow.get("language_mode") || 1;


/* state6/7/8 */
let icon = 6;

if (lang === 2) icon = 7;
if (lang === 3) icon = 8;


const frames = [];


// Charging icon (0x3800=H1, 0x2000=H2) is language-aware (6/7/8). Write it ONLY
// to a head that is actually charging, so pressing a language button can't slap a
// charging image onto an idle / stop-button screen. The value nodes keep it in sync.
if (flow.get("h1_cpState") === "state_c") {
    frames.push(Buffer.from([0x5A, 0xA5, 0x05, 0x82, 0x38, 0x00, 0x00, icon])); // HEAD1 0x3800
}
if (flow.get("h2_cpState") === "state_c") {
    frames.push(Buffer.from([0x5A, 0xA5, 0x05, 0x82, 0x20, 0x00, 0x00, icon])); // HEAD2 0x2000
}


// ── repaint per-head STATIC state icons in the new language ──
// (blink node covers 0/2/3; we cover the static screens it skips: 1/4/5)
const st1 = flow.get("h1_state") ?? 1;
const st2 = flow.get("h2_state") ?? 1;
function headFrame(vpHi, st) {
    return Buffer.from([0x5A, 0xA5, 0x05, 0x82, vpHi, 0x00, 0x00, applyLang(st, lang) & 0xFF]);
}
if (st1 !== 0 && st1 !== 2 && st1 !== 3) frames.push(headFrame(0x60, st1)); // HEAD1 0x6000
if (st2 !== 0 && st2 !== 2 && st2 !== 3) frames.push(headFrame(0x62, st2)); // HEAD2 0x6200

