msg.payload = Buffer.concat(frames);

msg.hex = msg.payload
    .toString("hex")
    .match(/.{1,2}/g)
    .join(" ");

return msg;

// STOP icon (0x8010 H1 / 0x8110 H2): 1 when Charging (state 0) AND RFID-started.
// CHARGE icon (0x3800 H1 / 0x2000 H2): TH(lang2)=8, EN(else)=9, while cs_state == CurrentDemand.
const VP_STOP = { 1: 0x8010, 2: 0x8110 };
function w(vp, val) {
    val = Math.max(0, Math.min(65535, Math.round(Number(val) || 0)));
    return Buffer.from([0x5A, 0xA5, 0x05, 0x82, (vp >> 8) & 0xFF, vp & 0xFF, (val >> 8) & 0xFF, val & 0xFF]);
}
const lang = flow.get("language_mode") || 1;
const last = context.get("last") || {};
const frames = [];
const info = {};
[1, 2].forEach(n => {
    const st = flow.get("h" + n + "_state") ?? 1;
    const cs = flow.get("h" + n + "_cs_state") || "";
    let rfid = global.get("h" + n + "_rfidSession") ?? false;
    let pend = context.get("pend" + n) || 0;
    if (rfid && st !== 0 && st !== 3) pend++; else pend = 0;
    if (rfid && (st === 4 || st === 5 || pend >= 120)) { rfid = false; pend = 0; global.set("h" + n + "_rfidSession", false); }
    context.set("pend" + n, pend);

    const stopVal = (rfid && st === 0) ? 1 : 0;
    if (last["s" + n] !== stopVal) { frames.push(w(VP_STOP[n], stopVal)); last["s" + n] = stopVal; }

    // charge icon now handled by the value nodes (0x3800/0x2000) — this node only does the stop icon
    info[n] = "st" + st + "/rfid" + (rfid ? 1 : 0) + "/stop" + stopVal;
});
context.set("last", last);
node.status({ fill: "grey", shape: "dot", text: "H1 " + info[1] + "   H2 " + info[2] });
if (!frames.length) return null;
msg.payload = Buffer.concat(frames);
return msg;

const p = msg.payload || {};
const head = Number(p.head);
if (head !== 1 && head !== 2) return null;
const action = (p.action || "start").toString().toLowerCase();
if (action === "start") { global.set("h" + head + "_rfidSession", true);  node.status({ fill: "green",  shape: "dot", text: "H" + head + " RFID ON  " + (p.idTag||"") }); }
else if (action === "stop") { global.set("h" + head + "_rfidSession", false); node.status({ fill: "orange", shape: "ring", text: "H" + head + " RFID OFF" }); }
return null;

global.set("h1_rfidSession", true);
global.set("h2_rfidSession", true);
node.status({ fill: "blue", shape: "dot", text: "forced h1+h2 RFID flags ON" });
return null;

// ===== Fix frozen screen (stuck on state 5 / Unplug) =====
// Clears the finishing/unplug latch that pins the state icon on 5, resets both heads to
// Idle (state 1), and writes the Idle icon now. The state machine re-renders from live
// telemetry on the next tick (charging head returns to charging automatically).
function applyLang(state, lang) {
    if (state >= 1 && state <= 6) { if (lang === 2) return state + 6; if (lang === 3) return state + 12; }
    return state;
}
function w(vp, val) { return Buffer.from([0x5A, 0xA5, 0x05, 0x82, (vp >> 8) & 0xFF, vp & 0xFF, (val >> 8) & 0xFF, val & 0xFF]); }
const lang = flow.get("language_mode") || 1;
global.set("H1_Finishing", 0);
global.set("H2_Finishing", 0);
["h1", "h2"].forEach(h => {
    flow.set(h + "_finishing_val", 0);
    flow.set(h + "_state", 1);
    flow.set(h + "_locked", false);
    flow.set(h + "_returnKeyPressed", false);
    flow.set(h + "_cs_state", "");
});
const idle = applyLang(1, lang);
msg.payload = Buffer.concat([ w(0x6000, idle), w(0x6200, idle) ]);   // both heads -> Idle icon
node.status({ fill: "blue", shape: "dot", text: "Unfroze -> both heads Idle (icon " + idle + ")" });
return msg;

function applyLang(state, lang) {
    if (state >= 1 && state <= 6) {
        if (lang === 2) return state + 6;
        if (lang === 3) return state + 12;
    }
    return state;
}

function resetPrev() {
    context.set("prevState", -1);
    context.set("prevLang", -1);
}

function makeVP(vp, state) {
    return Buffer.from([
        0x5A, 0xA5, 0x05, 0x82,
        (vp >> 8) & 0xFF, vp & 0xFF,
        0x00, state & 0xFF
    ]);
}

const lang = flow.get("language_mode") ?? 1;
const VP_ICON = 0x6000;
const VP_EMER = 0x9100;

const p = msg.payload || {};
const cpState = p.cp_state1 || "";
const csState = p.cs_state1 || "";

let unplug = (p.H1_Finishing !== undefined && p.H1_Finishing !== null)
    ? Number(p.H1_Finishing)
    : (flow.get("h1_finishing_val") ?? 0);

let currentState = flow.get("h1_state") ?? 1;
let returnKeyPressed = flow.get("h1_returnKeyPressed") ?? false;

// 🚨 1. Detect Emergency Stop
const _emerRaw = (p.emerstop !== undefined && p.emerstop !== null) ? p.emerstop
    : (p.emerStop_9100 !== undefined && p.emerStop_9100 !== null) ? p.emerStop_9100
    : (flow.get("EmergencyStop") !== undefined && flow.get("EmergencyStop") !== null) ? flow.get("EmergencyStop")
    : null;
const isEmergency = (_emerRaw !== null && Number(_emerRaw) === 0);
flow.set("isEmergencyStop", isEmergency);
global.set("isEmergencyStop", isEmergency);

const activeCpState = cpState || flow.get("h1_cpState") || flow.get("CPStateCCS1") || "";
const activeCsState = csState || flow.get("h1_cs_state") || flow.get("SessionStateCCS1") || "";
const h1Power = (p.w_ccs1 !== undefined && p.w_ccs1 !== null) ? Number(p.w_ccs1) : (flow.get("h1_power") ?? 0);
flow.set("h1_power", h1Power);

// 🛡️ 2. Robust Multi-Channel Detection of Insulation Fault (CCS1 ONLY - STRICT SEPARATION)
const rawInsu1 = p.Insu1 ?? p.Insu_CCS1 ?? flow.get("Insu_CCS1") ?? global.get("iso_value1") ?? null;
let isInsulationFault = false;
if (rawInsu1 !== null) {
    if (rawInsu1 === 0 || rawInsu1 === "0" || rawInsu1 === false || String(rawInsu1).toLowerCase() === "fault" || String(rawInsu1).toLowerCase() === "failed") {
        isInsulationFault = true;
    }
}

const snap = global.get("external_fault_snapshot");
if (!isInsulationFault && snap && Array.isArray(snap.issues)) {
    for (const it of snap.issues) {
        // STRICTLY check Connector 1 (never match connector 2):
        const isH1 = (it.connector === 1 || it.connector === "1" ||
                      /^[FAS]11\d{3}$/i.test(String(it.error_id || "")) ||
                      /11001/.test(String(it.error_id || "")) ||
                      (!it.connector && /H1|CCS1/i.test(String(it.short_message || it.description || ""))));
        const notH2 = (it.connector !== 2 && it.connector !== "2" &&
                       !/^[FAS]12\d{3}$/i.test(String(it.error_id || "")) &&
                       !/12001/.test(String(it.error_id || "")) &&
                       !/H2|CCS2/i.test(String(it.short_message || it.description || "")));
        if (isH1 && notH2) {
            const isIso = /isolation|insulat/i.test(String(it.short_message || "")) ||
                          /isolation|insulat/i.test(String(it.description || "")) ||
                          /isolation|insulat/i.test(String(it.code || "")) ||
                          /isolation|insulat/i.test(String(it.error_id || "")) ||
                          /11001/.test(String(it.error_id || it.code || ""));
            if (isIso) {
                isInsulationFault = true;
                break;
            }
        }
    }
}

if (!isInsulationFault && /Isolation.*Fault|CableCheck.*Fault|IsoFault/i.test(activeCsState)) {
    isInsulationFault = true;
}

// 🚀 3. REMOTE START & STOP DETECTION
const isRemoteStart = (global.get("h1_remoteStarted") === true || flow.get("h1_remoteActive") === true);
const wasRemoteStart = context.get("h1_wasRemoteStart") ?? false;

const isRemoteStop = (global.get("h1_stopCommanded") === true || global.get("manualStop1") === true ||
                      flow.get("h1_stopCommanded") === true || p.remoteStop1 === 1 || p.RemoteStop1 === 1);

if (isRemoteStart && !wasRemoteStart) {
    flow.set("h1_finishing_val", 0);
    global.set("H1_Finishing", 0);
    global.set("h1_stopCommanded", false);
    global.set("manualStop1", false);
    flow.set("h1_stopCommanded", false);
