    context.set("h1_hadPower", false);
    context.set("h1_charging", true);
    context.set("h1_unplugCnt", 0);
}
context.set("h1_wasRemoteStart", isRemoteStart);

if (h1Power > 0.5 || (activeCpState === "state_c" && /CurrentDemand/.test(activeCsState))) {
    context.set("h1_hadPower", true);
}
const hadPower = (context.get("h1_hadPower") === true);

const inHandshake = /CableCheck|PreCharge|PowerDelivery|SupportedAppProtocol|SessionSetup|Authorization|ChargeParameterDiscovery/i.test(activeCsState);

// ⏱️ 4. DETECT COMPLETE, TIMEOUT, OR STOP WHILE PLUGGED:
const isComplete = (p.Complete1 === 1 || p.Complete1 === true || p.Complete1 === "true" ||
