const stoppedWhileCharging = (wasCharging && (powerDropped || isComplete || isSessionStop) && isPlugged);

let isFinishing = (unplug === 1 || flow.get("h1_finishing_val") === 1 || global.get("H1_Finishing") === 1 ||
