        global.set("h1_state", 5);
        flow.set("h1_finishing_val", 1);
        global.set("H1_Finishing", 1);
        context.set("h1_charging", false);
        context.set("h1_hadPower", false);
        flow.set("h1_locked", false);
        global.set("h1_remoteStarted", false);
        flow.set("h1_remoteActive", false);
        flow.set("h1_prePlugBeforeSelect", false);
