        currentState = 1;
        returnKeyPressed = false;
        flow.set("h1_remoteActive", false);
        global.set("h1_remoteStarted", false);
        flow.set("h1_finishing_val", 0);
        global.set("H1_Finishing", 0);
        global.set("h1_stopCommanded", false);
        global.set("manualStop1", false);
        flow.set("h1_stopCommanded", false);
        flow.set("h1_cs_state", "");
        node.status({ fill: "blue", shape: "dot", text: "State 1 (Idle / Unplugged)" });
    }
    flow.set("h1_prePlugBeforeSelect", false);

// ── ⚡ 4. CHARGING STATE (State 0): ONLY when remote_start is active AND not finished! ──
} else if ((activeCpState === "state_b" || activeCpState === "state_c") && isRemoteStart && !isFinishing) {
    currentState = 0;
    context.set("h1_charging", true);
    flow.set("h1_locked", true);
    flow.set("h1_prePlugBeforeSelect", false);
    node.status({ fill: "green", shape: "dot", text: "⚡ State 0 Charging (RemoteStart Active kW=" + h1Power + ")" });

// ── 5. Plugged In Before Remote Start (State 3 - Preparing) ──
} else if (activeCpState === "state_b" || activeCpState === "state_c") {
    context.set("h1_charging", false);
    flow.set("h1_locked", false);
    if (flow.get("selectedHead") === "h2") {
        currentState = 1;
    } else {
        currentState = 3;
        flow.set("selectedHead", "h1");
    }
    flow.set("h1_prePlugBeforeSelect", false);
    node.status({ fill: "yellow", shape: "dot", text: `Plugged (${activeCpState}) -> State 3 (Preparing)` });
}

flow.set("h1_state", currentState);
global.set("h1_state", currentState);
flow.set("h1_returnKeyPressed", returnKeyPressed);
if (cpState) flow.set("h1_cpState", cpState);
if (cpState) global.set("h1_cpState", cpState);
if (csState) flow.set("h1_cs_state", csState);

let _repaint = context.get("h1_emerRepaint") ?? 0;
if (_repaint > 0) {
    context.set("h1_emerRepaint", _repaint - 1);
    resetPrev();
}

const prevState = context.get("prevState") ?? -1;
const prevLang = context.get("prevLang") ?? -1;
if (currentState === prevState && lang === prevLang) return null;

context.set("prevState", currentState);
context.set("prevLang", lang);

msg.payload = makeVP(VP_ICON, applyLang(currentState, lang));
node.status({
    fill: currentState === 4 ? "red" : (currentState === 0 ? "green" : (currentState === 5 ? "orange" : "blue")),
    shape: "dot",
    text: "State " + currentState + " | cp: " + activeCpState + " | cs: " + activeCsState
});
return msg;

function applyLang(state, lang) {
    if (state >= 1 && state <= 6) {
        if (lang === 2) return state + 6;
        if (lang === 3) return state + 12;
    }
    return state;
}

function resetPrev() {
    context.set("prevState", -1);
    context.set("prevLang", -1);
}

function makeVP(vp, state) {
    return Buffer.from([
        0x5A, 0xA5, 0x05, 0x82,
        (vp >> 8) & 0xFF, vp & 0xFF,
        0x00, state & 0xFF
    ]);
}

const lang = flow.get("language_mode") ?? 1;
const VP_ICON = 0x6200;

const p = msg.payload || {};
const cpState = p.cp_state2 || "";
const csState = p.cs_state2 || "";

let unplug = (p.H2_Finishing !== undefined && p.H2_Finishing !== null)
    ? Number(p.H2_Finishing)
    : (flow.get("h2_finishing_val") ?? 0);

let currentState = flow.get("h2_state") ?? 1;
let returnKeyPressed = flow.get("h2_returnKeyPressed") ?? false;

const isEmergency = (flow.get("isEmergencyStop") === true || global.get("isEmergencyStop") === true);

const activeCpState = cpState || flow.get("h2_cpState") || flow.get("CPStateCCS2") || "";
const activeCsState = csState || flow.get("h2_cs_state") || flow.get("SessionStateCCS2") || "";
const h2Power = (p.w_ccs2 !== undefined && p.w_ccs2 !== null) ? Number(p.w_ccs2) : (flow.get("h2_power") ?? 0);
flow.set("h2_power", h2Power);

// 🛡️ 2. Robust Multi-Channel Detection of Insulation Fault (CCS2 ONLY - STRICT SEPARATION)
const rawInsu2 = p.Insu2 ?? p.Insu_CCS2 ?? flow.get("Insu_CCS2") ?? global.get("iso_value2") ?? null;
let isInsulationFault = false;
if (rawInsu2 !== null) {
    if (rawInsu2 === 0 || rawInsu2 === "0" || rawInsu2 === false || String(rawInsu2).toLowerCase() === "fault" || String(rawInsu2).toLowerCase() === "failed") {
        isInsulationFault = true;
    }
}

const snap = global.get("external_fault_snapshot");
if (!isInsulationFault && snap && Array.isArray(snap.issues)) {
    for (const it of snap.issues) {
        // STRICTLY check Connector 2 (never match connector 1):
        const isH2 = (it.connector === 2 || it.connector === "2" ||
                      /^[FAS]12\d{3}$/i.test(String(it.error_id || "")) ||
                      /12001/.test(String(it.error_id || "")) ||
                      (!it.connector && /H2|CCS2/i.test(String(it.short_message || it.description || ""))));
        const notH1 = (it.connector !== 1 && it.connector !== "1" &&
                       !/^[FAS]11\d{3}$/i.test(String(it.error_id || "")) &&
                       !/11001/.test(String(it.error_id || "")) &&
                       !/H1|CCS1/i.test(String(it.short_message || it.description || "")));
        if (isH2 && notH1) {
            const isIso = /isolation|insulat/i.test(String(it.short_message || "")) ||
                          /isolation|insulat/i.test(String(it.description || "")) ||
                          /isolation|insulat/i.test(String(it.code || "")) ||
                          /isolation|insulat/i.test(String(it.error_id || "")) ||
                          /12001/.test(String(it.error_id || it.code || ""));
            if (isIso) {
                isInsulationFault = true;
                break;
            }
        }
    }
}

if (!isInsulationFault && /Isolation.*Fault|CableCheck.*Fault|IsoFault/i.test(activeCsState)) {
    isInsulationFault = true;
}

// 🚀 3. REMOTE START & STOP DETECTION
const isRemoteStart = (global.get("h2_remoteStarted") === true || flow.get("h2_remoteActive") === true);
const wasRemoteStart = context.get("h2_wasRemoteStart") ?? false;

const isRemoteStop = (global.get("h2_stopCommanded") === true || global.get("manualStop2") === true ||
                      flow.get("h2_stopCommanded") === true || p.remoteStop2 === 1 || p.RemoteStop2 === 1);

if (isRemoteStart && !wasRemoteStart) {
    flow.set("h2_finishing_val", 0);
    global.set("H2_Finishing", 0);
    global.set("h2_stopCommanded", false);
    global.set("manualStop2", false);
    flow.set("h2_stopCommanded", false);
    unplug = 0;
    context.set("h2_hadPower", false);
    context.set("h2_charging", true);
    context.set("h2_unplugCnt", 0);
}
context.set("h2_wasRemoteStart", isRemoteStart);

if (h2Power > 0.5 || (activeCpState === "state_c" && /CurrentDemand/.test(activeCsState))) {
    context.set("h2_hadPower", true);
}
const hadPower = (context.get("h2_hadPower") === true);

const inHandshake = /CableCheck|PreCharge|PowerDelivery|SupportedAppProtocol|SessionSetup|Authorization|ChargeParameterDiscovery/i.test(activeCsState);

// ⏱️ 4. DETECT COMPLETE, TIMEOUT, OR STOP WHILE PLUGGED:
const isComplete = (p.Complete2 === 1 || p.Complete2 === true || p.Complete2 === "true" ||
                    p.Complete_CCS2 === 1 || p.Complete_CCS2 === true || p.Complete_CCS2 === "true" ||
                    flow.get("Complete_CCS2") === 1 || flow.get("Complete_CCS2") === true);

const isSessionStop = /SessionStop|Timeout|Time_Out|Failed|WeldingDetection|Abort|Terminated/i.test(activeCsState);

const wasCharging = (context.get("h2_charging") === true || currentState === 0);
const powerDropped = (!inHandshake && hadPower && wasCharging && h2Power <= 0 && (activeCpState === "state_b" || isComplete));

const isPlugged = (activeCpState === "state_b" || activeCpState === "state_c" || activeCpState === "state_d");

const remoteStopped = isPlugged && (isRemoteStop || (wasCharging && !isRemoteStart));
const stoppedWhileCharging = (wasCharging && (powerDropped || isComplete || isSessionStop) && isPlugged);

let isFinishing = (unplug === 1 || flow.get("h2_finishing_val") === 1 || global.get("H2_Finishing") === 1 ||
                   remoteStopped || stoppedWhileCharging || (isPlugged && isComplete) || (isPlugged && isSessionStop));

if (inHandshake && !remoteStopped && !isComplete && !isSessionStop) {
    isFinishing = false;
}

if (activeCpState === "state_a") {
    unplug = 0;
}

// ── 🚨 Emergency Stop Active ─────────────────────────────
if (isEmergency) {
    context.set("h2_emerActive", true);
    const isPlg = (activeCpState !== "state_a" && activeCpState !== "");
    const frames = [];

    if (isPlg) {
        flow.set("h2_state", 5);
        global.set("h2_state", 5);
        flow.set("h2_finishing_val", 1);
        global.set("H2_Finishing", 1);
        flow.set("h2_locked", false);
        flow.set("h2_prePlugBeforeSelect", false);
        flow.set("h2_remoteActive", false);
        global.set("h2_remoteStarted", false);
        context.set("h2_charging", false);
        context.set("h2_hadPower", false);

        const s5 = applyLang(5, lang);
        if (context.get("prevState") !== 5 || context.get("prevLang") !== lang) {
            frames.push(makeVP(VP_ICON, s5));
            context.set("prevState", 5);
            context.set("prevLang", lang);
        }
        node.status({ fill: "red", shape: "dot", text: "⚠️ EmerStop: H2 Plugged -> State 5 (Please Unplug)" });
    } else {
        flow.set("h2_state", 1);
        global.set("h2_state", 1);
        flow.set("h2_returnKeyPressed", false);
        flow.set("h2_locked", false);
        flow.set("h2_remoteActive", false);
        global.set("h2_remoteStarted", false);
        context.set("h2_charging", false);
        context.set("h2_hadPower", false);

        const s1 = applyLang(1, lang);
        if (context.get("prevState") !== 1 || context.get("prevLang") !== lang) {
            frames.push(makeVP(VP_ICON, s1));
            context.set("prevState", 1);
            context.set("prevLang", lang);
        }
        node.status({ fill: "red", shape: "ring", text: "⚠️ EmerStop: H2 Unplugged -> State 1 (Idle)" });
    }

    if (!frames.length) return null;
    msg.payload = Buffer.concat(frames);
    return msg;
}

// ── Emergency Released Edge ──────────────────────────────
if (context.get("h2_emerActive")) {
    context.set("h2_emerActive", false);
    resetPrev();
    const isPlg = (activeCpState !== "state_a" && activeCpState !== "");
    const frames = [];
    if (isPlg) {
        currentState = 5;
        flow.set("h2_state", 5);
        global.set("h2_state", 5);
        flow.set("h2_finishing_val", 1);
        global.set("H2_Finishing", 1);
        frames.push(makeVP(VP_ICON, applyLang(5, lang)));
        context.set("prevState", 5);
        context.set("prevLang", lang);
        node.status({ fill: "orange", shape: "dot", text: "EmerStop released -> Plugged -> State 5" });
    } else {
        currentState = 1;
        flow.set("h2_state", 1);
        global.set("h2_state", 1);
        frames.push(makeVP(VP_ICON, applyLang(1, lang)));
        context.set("prevState", 1);
        context.set("prevLang", lang);
        node.status({ fill: "blue", shape: "dot", text: "EmerStop released -> Unplugged -> State 1" });
    }
    context.set("h2_emerRepaint", 3);
    if (!frames.length) return null;
    msg.payload = Buffer.concat(frames);
    return msg;
}

// ── Reset Command ─────────────────────────────────────────
if ((flow.get("h2_reset") ?? 0) > 0) {
    flow.set("h2_reset", (flow.get("h2_reset") ?? 0) - 1);
    const h2_cpState_now = flow.get("h2_cpState") ?? "";
    const h2_state_now = flow.get("h2_state") ?? 1;

    // Never reset if Charging (0) OR in Insulation Fault (4)!
    if (h2_cpState_now !== "state_c" && h2_state_now !== 0 && h2_state_now !== 4) {
        flow.set("h2_state", 1);
        global.set("h2_state", 1);
        flow.set("h2_returnKeyPressed", false);
        flow.set("h2_locked", false);
        flow.set("h2_cpState", "");
        flow.set("h2_cs_state", "");
        flow.set("h2_prePlugBeforeSelect", false);
        flow.set("h2_finishing_val", 0);
        global.set("H2_Finishing", 0);
        global.set("h2_stopCommanded", false);
        global.set("manualStop2", false);
        flow.set("h2_stopCommanded", false);
        flow.set("h2_insuFault", false);
        context.set("h2_charging", false);
        context.set("h2_hadPower", false);
        resetPrev();
        node.status({ fill: "blue", shape: "dot", text: "Reset → State 1" });
        return null;
    }
    node.status({ fill: "grey", shape: "ring", text: "Reset skipped (" + (h2_state_now === 4 ? "InsuFault" : "Charging") + ")" });
    return null;
}

// ── State Machine ─────────────────────────────────────────

// ── 🚨 1. INSULATION FAULT (State 4): CCS2 ONLY, INDEPENDENT CHECK & DISPLAY ──
if (isInsulationFault || currentState === 4 || flow.get("h2_insuFault")) {
    if (activeCpState === "state_a") {
        const sa = (context.get("h2_unplugCnt") ?? 0) + 1;
        context.set("h2_unplugCnt", sa);
        if (sa >= 2) {
            context.set("h2_unplugCnt", 0);
            currentState = 1;
            returnKeyPressed = false;
            flow.set("h2_insuFault", false);
            flow.set("h2_locked", false);
            flow.set("h2_prePlugBeforeSelect", false);
            flow.set("h2_finishing_val", 0);
            global.set("H2_Finishing", 0);
            global.set("h2_stopCommanded", false);
            global.set("manualStop2", false);
            flow.set("h2_stopCommanded", false);
            flow.set("h2_cs_state", "");
            context.set("h2_charging", false);
            context.set("h2_hadPower", false);
            node.status({ fill: "blue", shape: "dot", text: "H2 Insu fault cleared: Unplugged → State 1 (Idle)" });
        } else {
            node.status({ fill: "red", shape: "dot", text: "H2 Insu fault: Unplugging (confirming " + sa + "/2)" });
        }
    } else {
        context.set("h2_unplugCnt", 0);
        currentState = 4;
        flow.set("h2_state", 4);
        global.set("h2_state", 4);
        flow.set("h2_insuFault", true);
        flow.set("h2_locked", false);
        flow.set("h2_remoteActive", false);
        global.set("h2_remoteStarted", false);
        context.set("h2_charging", false);
        context.set("h2_hadPower", false);
        flow.set("h2_prePlugBeforeSelect", false);
        node.status({ fill: "red", shape: "dot", text: "⚠️ H2 INSULATION FAULT (State 4) | cp:" + activeCpState });
    }

// ── ⚡ 2. PLEASE UNPLUG STATE (State 5): LATCHED UNTIL PHYSICALLY UNPLUGGED ──
} else if (currentState === 5 || isFinishing) {
    if (activeCpState === "state_a") {
        const sa = (context.get("h2_unplugCnt") ?? 0) + 1;
        context.set("h2_unplugCnt", sa);
        if (sa >= 2) {
            context.set("h2_unplugCnt", 0);
            currentState = 1;
            returnKeyPressed = false;
            flow.set("h2_locked", false);
            flow.set("h2_prePlugBeforeSelect", false);
            flow.set("h2_finishing_val", 0);
            global.set("H2_Finishing", 0);
            global.set("h2_stopCommanded", false);
            global.set("manualStop2", false);
            flow.set("h2_stopCommanded", false);
            flow.set("h2_cs_state", "");
            context.set("h2_charging", false);
            context.set("h2_hadPower", false);
            node.status({ fill: "blue", shape: "dot", text: "Unplugged → State 1 (Idle)" });
        } else {
            node.status({ fill: "orange", shape: "dot", text: "Unplug screen (confirming " + sa + "/2)" });
        }
    } else {
        context.set("h2_unplugCnt", 0);
        currentState = 5;
        flow.set("h2_state", 5);
        global.set("h2_state", 5);
        flow.set("h2_finishing_val", 1);
        global.set("H2_Finishing", 1);
        context.set("h2_charging", false);
        context.set("h2_hadPower", false);
        flow.set("h2_locked", false);
        global.set("h2_remoteStarted", false);
        flow.set("h2_remoteActive", false);
        flow.set("h2_prePlugBeforeSelect", false);
        node.status({ fill: "orange", shape: "dot", text: "🔌 Stopped/Finished -> PLEASE UNPLUG (cp:" + activeCpState + ")" });
    }

// ── 3. Unplugged Edge (state_a) ──────────────────────────
} else if (activeCpState === "state_a") {
    context.set("h2_charging", false);
    context.set("h2_hadPower", false);
    flow.set("h2_locked", false);
    if (returnKeyPressed && (currentState === 2 || flow.get("h2_state") === 2)) {
        currentState = 2;
        node.status({ fill: "yellow", shape: "dot", text: "H2 Selected (Waiting Plug)" });
    } else {
        currentState = 1;
        returnKeyPressed = false;
        flow.set("h2_remoteActive", false);
        global.set("h2_remoteStarted", false);
        flow.set("h2_finishing_val", 0);
        global.set("H2_Finishing", 0);
        global.set("h2_stopCommanded", false);
        global.set("manualStop2", false);
        flow.set("h2_stopCommanded", false);
        flow.set("h2_cs_state", "");
        node.status({ fill: "blue", shape: "dot", text: "State 1 (Idle / Unplugged)" });
    }
    flow.set("h2_prePlugBeforeSelect", false);

// ── ⚡ 4. CHARGING STATE (State 0) ──────────────────────
} else if ((activeCpState === "state_b" || activeCpState === "state_c") && isRemoteStart && !isFinishing) {
    currentState = 0;
    context.set("h2_charging", true);
    flow.set("h2_locked", true);
    flow.set("h2_prePlugBeforeSelect", false);
    node.status({ fill: "green", shape: "dot", text: "⚡ State 0 Charging (RemoteStart Active kW=" + h2Power + ")" });

// ── 5. Plugged In Before Remote Start (State 3 - Preparing) ──
} else if (activeCpState === "state_b" || activeCpState === "state_c") {
    context.set("h2_charging", false);
    flow.set("h2_locked", false);
    if (flow.get("selectedHead") === "h1") {
        currentState = 1;
    } else {
        currentState = 3;
        flow.set("selectedHead", "h2");
    }
    flow.set("h2_prePlugBeforeSelect", false);
    node.status({ fill: "yellow", shape: "dot", text: `Plugged (${activeCpState}) -> State 3 (Preparing)` });
}

flow.set("h2_state", currentState);
global.set("h2_state", currentState);
flow.set("h2_returnKeyPressed", returnKeyPressed);
if (cpState) flow.set("h2_cpState", cpState);
if (cpState) global.set("h2_cpState", cpState);
if (csState) flow.set("h2_cs_state", csState);

let _repaint = context.get("h2_emerRepaint") ?? 0;
if (_repaint > 0) {
    context.set("h2_emerRepaint", _repaint - 1);
    resetPrev();
}

const prevState = context.get("prevState") ?? -1;
const prevLang = context.get("prevLang") ?? -1;
if (currentState === prevState && lang === prevLang) return null;

context.set("prevState", currentState);
context.set("prevLang", lang);

msg.payload = makeVP(VP_ICON, applyLang(currentState, lang));
node.status({
    fill: currentState === 4 ? "red" : (currentState === 0 ? "green" : (currentState === 5 ? "orange" : "blue")),
    shape: "dot",
    text: "State " + currentState + " | cp: " + activeCpState + " | cs: " + activeCsState
});
return msg;

// On remote_start=1, flip this head's screen to the Charging page (state machine latches it).
const head = (msg.topic || "").slice(-1) === "2" ? 2 : 1;
if (Number(msg.payload && msg.payload.remote_start) === 1) {
    global.set("h" + head + "_remoteStarted", true);
    global.set("h" + head + "_remoteActive", true);
    flow.set("h" + head + "_remoteActive", true);
    global.set("h" + head + "_stopCommanded", false);
    node.status({ fill: "green", shape: "dot", text: "H" + head + " remote start -> Charging page" });
}
return null;

// ============ External fault LOG -> DWIN text at VP 0x0404 ============
// Rolling log, newest first, one issue per line:
//     14:32:07  H1: F11001 PE isolation fault
//     14:31:55  F10001 Emergency input active      <- no head = station-wide
//
// ---------------------------- SETTINGS ----------------------------
const VP_BASE    = 0x0404;   // first VP of the text control
const LOG_LINES  = 22;       // <-- how many lines to keep/show  (adjustable)
const LINE_WIDTH = 95;       // <-- characters the box renders per ROW.
                             //     Must match EXACTLY: if it is 1 too high every
                             //     line drifts right by one (staircase indent).
const SHOW_TIME  = true;     // put HH:MM:SS in front of each line
const SHOW_ALARMS= true;     // false = only severity "fault" is logged
const NEWEST_FIRST = true;   // false = oldest at the top
// ------------------------------------------------------------------
// The DWIN length byte counts cmd(1)+VP(2)+data, so one frame can carry at
// most 252 data bytes. LOG_LINES*LINE_WIDTH is usually more than that, so the
// buffer is sent as several frames, each at its own VP offset (2 bytes/word).
// IMPORTANT: LOG_LINES*LINE_WIDTH must be <= the DGUS "Text Length" of this
// control. Now: 22 x 95 = 2090, and Text Length is set to 2090 (exact fit).
// LINE_WIDTH must equal the characters the box renders per row (95) or the
// lines drift. Lines that fit on screen = box H / Y-lattice = 352 / 16 = 22.
const CHUNK = 240;           // data bytes per frame (even, <= 252)
const FRAME_GAP_MS = 30;     // <-- ms between frames. Sending many frames back-to-back
                             //     overflows the DWIN UART buffer and the tail is lost
                             //     (symptom: only about half the lines appear).

function pad2(n) { return (n < 10 ? "0" : "") + n; }
function hhmmss(ms) {
    const d = new Date(ms);
    return pad2(d.getHours()) + ":" + pad2(d.getMinutes()) + ":" + pad2(d.getSeconds());
}
function headOf(it) {
    if (it.connector === 1 || it.connector === "1") return "H1";
    if (it.connector === 2 || it.connector === "2") return "H2";
    const id = String(it.error_id || "");
    if (/^[FAS]\d1\d{3}$/.test(id)) return "H1";
    if (/^[FAS]\d2\d{3}$/.test(id)) return "H2";
    return "";
}

const snap = global.get("external_fault_snapshot") || {};
let items = Array.isArray(snap.issues) ? snap.issues.slice() : [];
if (!SHOW_ALARMS) items = items.filter(function (x) { return x.severity === "fault"; });

// ---- manual clear (the "CLEAR fault log" inject sets this flag) ----
if (flow.get("fltlog_clear")) {
    flow.set("fltlog_clear", false);
    context.set("faultLog", []);
    context.set("activeCodes", {});
    context.set("lastBlock", null);      // force a repaint of the blank block
}

// ---- append newly RAISED issues to the log (with their timestamp) ----
const active = context.get("activeCodes") || {};
const log = context.get("faultLog") || [];
const now = Date.now();
const live = {};

for (const it of items) {
    const c = it.code;
    live[c] = true;
    if (!active[c]) {                       // transition: not active -> active
        active[c] = now;
        const head = headOf(it);
        const code = it.error_id || it.code || "";
        const text = it.short_message || it.description || "";
        log.unshift({
            t: now,
            line: (head ? head + ": " : "") + code + (text ? " " + text : "")
        });
    }
}
for (const c of Object.keys(active)) if (!live[c]) delete active[c];   // cleared
if (log.length > LOG_LINES) log.length = LOG_LINES;                    // trim
context.set("activeCodes", active);
context.set("faultLog", log);

// ---- render the fixed-size text block ----
const rows = NEWEST_FIRST ? log : log.slice().reverse();
let block = "";
for (let i = 0; i < LOG_LINES; i++) {
    let s = "";
    if (i < rows.length) s = (SHOW_TIME ? hhmmss(rows[i].t) + "  " : "") + rows[i].line;
    if (s.length > LINE_WIDTH) s = s.slice(0, LINE_WIDTH);
    while (s.length < LINE_WIDTH) s += " ";      // pad so lines align & old text clears
    block += s;
}

// only write when something actually changed
if (block === (context.get("lastBlock") ?? null)) {
    node.status({ fill: log.length ? "red" : "green", shape: "ring",
        text: "(unchanged) " + log.length + "/" + LOG_LINES + " logged" });
    return null;
}
context.set("lastBlock", block);

// ---- split into frames: 5A A5 <len> 82 <vpHi> <vpLo> <ascii...> ----
const buf = Buffer.from(block, "ascii");
const msgs = [];
for (let off = 0; off < buf.length; off += CHUNK) {
    const part = buf.slice(off, Math.min(off + CHUNK, buf.length));
    const vp = VP_BASE + (off / 2);                  // 2 bytes per VP word
    const len = 1 + 2 + part.length;
    msgs.push({ payload: Buffer.concat([
        Buffer.from([0x5A, 0xA5, len & 0xFF, 0x82, (vp >> 8) & 0xFF, vp & 0xFF]),
        part
    ]) });
}

node.status({ fill: log.length ? "red" : "green", shape: "dot",
    text: log.length + "/" + LOG_LINES + " logged, " + msgs.length + " frame(s)" });

// Send the frames SPACED OUT. Returning them together makes node-red write the
// whole block to the serial port in one burst; past ~4 frames the DWIN input
// buffer overflows and the tail frames are dropped (symptom: only about half
// the lines appear on screen).
msgs.forEach(function (m, i) {
    if (i === 0) { node.send(m); return; }
    setTimeout(function () { node.send(m); }, i * FRAME_GAP_MS);
});
return null;

// Raise the flag; the poll node wipes the log and repaints on its next tick.
flow.set("fltlog_clear", true);
node.status({ fill: "grey", shape: "ring", text: "clear requested" });
return null;

// FORCE the Charging screen (state 0) on one head — debug only.
// Sets the same flow state the real state machine would set, so the Blink node
// holds it, then writes the icon VP immediately.
const head = (msg.topic === "h2") ? "h2" : "h1";
const VP = (head === "h2") ? 0x6200 : 0x6000;   // H1 icon 0x6000 / H2 icon 0x6200

// state 0 = Charging (no language offset: applyLang only shifts states 1..6)
flow.set(head + "_state", 0);
flow.set(head + "_locked", true);          // hold it; real telemetry can't bump it off
flow.set(head + "_returnKeyPressed", true);
flow.set("selectedHead", head);
global.set(head + "_remoteStarted", true); // keep the state machine agreeing
global.set(head + "_rsArmTime", Date.now());

msg.payload = Buffer.from([0x5A, 0xA5, 0x05, 0x82, (VP >> 8) & 0xFF, VP & 0xFF, 0x00, 0x00]);
node.status({ fill: "green", shape: "dot", text: head.toUpperCase() + " FORCED -> Charging (state 0)" });
return msg;

// RELEASE the forced Charging screen — hand control back to the state machine.
const head = (msg.topic === "h2") ? "h2" : "h1";
flow.set(head + "_locked", false);
flow.set(head + "_state", 1);
flow.set(head + "_returnKeyPressed", false);
global.set(head + "_remoteStarted", false);
global.set(head + "_rsArmTime", 0);
const VP = (head === "h2") ? 0x6200 : 0x6000;
const lang = flow.get("language_mode") ?? 1;
let s = 1; if (lang === 2) s = 7; if (lang === 3) s = 13;   // idle, language-adjusted
msg.payload = Buffer.from([0x5A, 0xA5, 0x05, 0x82, (VP >> 8) & 0xFF, VP & 0xFF, 0x00, s & 0xFF]);
node.status({ fill: "blue", shape: "dot", text: head.toUpperCase() + " released -> Idle" });
return msg;

msg.payload =
{
    "H1shown" : false
}
return msg;

msg.payload =
{
    "H1shown" : true
}
return msg;

msg.payload =
{
    "H2shown" : false
}
return msg;

msg.payload =
{
    "H2shown" : true
}
return msg;

const vp = msg.payload.vp_raw;

const VP_H1 = 0x6100;
const VP_H2 = 0x6300;

// ถ้าไม่ใช่ VP ที่เกี่ยวข้อง ไม่ต้องทำอะไร
if (vp !== VP_H1 && vp !== VP_H2) return null;

if (vp === VP_H1) {
    flow.set("selectedHead", 1);
    node.status({ fill: "green", shape: "dot", text: "Head 1 Selected" });

} else if (vp === VP_H2) {
    flow.set("selectedHead", 2);
    node.status({ fill: "blue", shape: "dot", text: "Head 2 Selected" });
}

return null;

const vp = msg.payload.vp_raw;

const VP_H1_START = 0x6100;
const VP_H2_START = 0x6300;
const VP_STOP_H1 = 0x8000;
const VP_STOP_H2 = 0x8100;  // ✅ เพิ่ม

if (vp !== VP_H1_START && vp !== VP_H2_START && vp !== VP_STOP_H1 && vp !== VP_STOP_H2) return null;

if (vp === VP_H1_START) {
    flow.set("selectedHead", 1);
    flow.set("selectedAction", "start");
    node.status({ fill: "green", shape: "dot", text: "Head 1 → Start" });

} else if (vp === VP_H2_START) {
    flow.set("selectedHead", 2);
    flow.set("selectedAction", "start");
    node.status({ fill: "blue", shape: "dot", text: "Head 2 → Start" });

} else if (vp === VP_STOP_H1) {
    flow.set("selectedHead", 1);
    flow.set("selectedAction", "stop");
    node.status({ fill: "red", shape: "dot", text: "Head 1 → Stop" });

} else if (vp === VP_STOP_H2) {  // ✅ เพิ่ม
    flow.set("selectedHead", 2);
    flow.set("selectedAction", "stop");
    node.status({ fill: "orange", shape: "dot", text: "Head 2 → Stop" });
}

return null;

// ==================== RFID Router ====================

const rfidValue = msg.payload;

if (!rfidValue || rfidValue === "0" || rfidValue === "") {
    node.status({ fill: "grey", shape: "ring", text: "No card" });
    return null;
}

const selectedHead = flow.get("selectedHead") ?? 0;
const selectedAction = flow.get("selectedAction") ?? "start";

if (selectedHead === 0) {
    node.status({ fill: "yellow", shape: "ring", text: "No head selected" });
    return null;
}

// ===== Same-card check: a STOP must use the SAME card that started this head's session =====
if (selectedAction === "start") {
    global.set("h" + selectedHead + "_startTag", rfidValue);          // remember the card that started
} else if (selectedAction === "stop") {
    const startTag = global.get("h" + selectedHead + "_startTag") || "";
    if (startTag && rfidValue !== startTag) {
        node.status({ fill: "red", shape: "ring", text: "Head " + selectedHead + ": different card — stop rejected" });
        flow.set("selectedHead", 0);
        flow.set("selectedAction", "start");
        return null;                                                  // wrong card -> don't stop, button stays
    }
    global.set("h" + selectedHead + "_startTag", "");                 // matched -> clear
}

// ===== ผ่านเงื่อนไข =====

// --- Output 1: MQTT ---
const cmdMsg = {
    payload: {
        head: selectedHead,
        idTag: rfidValue,
        action: selectedAction
    }
};

// --- Function สร้าง DWIN ---
function buildDwin(head, value) {
    const addrHi = head === 1 ? 0x83 : 0x84;

    return {
        payload: Buffer.from([
            0x5A, 0xA5,
            0x05,
            0x82,
            addrHi, 0x00,
            0x00, value
        ])
    };
}

// --- ส่ง state12 ---
const dwinStart = buildDwin(selectedHead, 0x0C);

// --- ตั้ง timer 30 วิ แล้วส่ง state0 ---
setTimeout(() => {
    const dwinStop = buildDwin(selectedHead, 0x00);
    node.send([null, dwinStop]);
}, 30000);

// status
node.status({
    fill: selectedHead === 1 ? "green" : "blue",
    shape: "dot",
    text: `Head ${selectedHead} → state12 (30s)`
});

// reset selection
flow.set("selectedHead", 0);
flow.set("selectedAction", "start");

// return ทันที (state12)
return [cmdMsg, dwinStart];

// ==================== Remote State → DWIN (Immediate Button + State) ====================
// VP 0x4800 (H1 State), VP 0x4900 (H2 State)
// VP 0x8500 (H1 Button: 0=START, 1=STOP)
// VP 0x8600 (H2 Button: 0=START, 1=STOP)
// VP 0x6000 (H1 Icon: 5 = Please Unplug)
// VP 0x6200 (H2 Icon: 5 = Please Unplug)

const topic = msg.topic;
const payload = msg.payload || {};

function writeVP(vp, val) {
    return Buffer.from([0x5A, 0xA5, 0x05, 0x82, (vp >> 8) & 0xFF, vp & 0xFF, 0x00, val & 0xFF]);
}

function applyLang(state, lang) {
    if (state >= 1 && state <= 6) {
        if (lang === 2) return state + 6;
        if (lang === 3) return state + 12;
    }
    return state;
}

const lang = flow.get("language_mode") || global.get("language_mode") || 1;
const frames = [];
let label = "";

// ===== H1 =====
if (topic === "topic/RemoteStart1" || topic === "RemoteStart1") {
    if (payload.remote_start === 1) {
        frames.push(writeVP(0x4800, 0x0C)); // H1 DWIN state = 12 (Charging)
        frames.push(writeVP(0x8500, 0x01)); // H1 Button = 1 (STOP icon immediately!)
        global.set("h1_remoteStarted", true);
        global.set("h1_remoteActive", true);
        flow.set("h1_remoteActive", true);
        global.set("h1_stopCommanded", false);
        flow.set("h1_stopCommanded", false);
        global.set("manualStop1", false);
        flow.set("h1_finishing_val", 0);
        global.set("H1_Finishing", 0);
        label = "H1 RemoteStart=1 -> State 12 + STOP button (1)";
    } else if (payload.remote_start === 0) {
        frames.push(writeVP(0x4800, 0x00)); // H1 DWIN state reset
        label = "H1 Start pulse reset (0x8500 stays STOP)";
    }
}
else if (topic === "topic/RemoteStop1" || topic === "RemoteStop1") {
    const h1_cp = global.get("h1_cpState") || global.get("cp_state1") || flow.get("h1_cpState") || "state_b";
    const isPlugged = (h1_cp !== "state_a" && h1_cp !== "");

    frames.push(writeVP(0x4800, 0x00)); // H1 DWIN state = 0 (Stop)
    frames.push(writeVP(0x8500, 0x00)); // H1 Button = 0 (START icon immediately!)

    global.set("h1_remoteStarted", false);
    global.set("h1_remoteActive", false);
    flow.set("h1_remoteActive", false);
    global.set("h1_stopCommanded", true);
    flow.set("h1_stopCommanded", true);

    if (isPlugged) {
        // Plugged in: Remote stop immediately shows PLEASE UNPLUG (State 5)
        frames.push(writeVP(0x6000, applyLang(5, lang)));
        flow.set("h1_state", 5);
        global.set("h1_state", 5);
        flow.set("h1_finishing_val", 1);
        global.set("H1_Finishing", 1);
        label = "H1 RemoteStop -> Please Unplug (State 5)";
    } else {
        frames.push(writeVP(0x6000, applyLang(1, lang)));
        flow.set("h1_state", 1);
        global.set("h1_state", 1);
        flow.set("h1_finishing_val", 0);
        global.set("H1_Finishing", 0);
        label = "H1 RemoteStop -> Idle (State 1)";
    }
}

// ===== H2 =====
else if (topic === "topic/RemoteStart2" || topic === "RemoteStart2") {
    if (payload.remote_start === 1) {
        frames.push(writeVP(0x4900, 0x0C)); // H2 DWIN state = 12 (Charging)
        frames.push(writeVP(0x8600, 0x01)); // H2 Button = 1 (STOP icon immediately!)
        global.set("h2_remoteStarted", true);
        global.set("h2_remoteActive", true);
        flow.set("h2_remoteActive", true);
        global.set("h2_stopCommanded", false);
        flow.set("h2_stopCommanded", false);
        global.set("manualStop2", false);
        flow.set("h2_finishing_val", 0);
        global.set("H2_Finishing", 0);
        label = "H2 RemoteStart=1 -> State 12 + STOP button (1)";
    } else if (payload.remote_start === 0) {
        frames.push(writeVP(0x4900, 0x00)); // H2 DWIN state reset
        label = "H2 Start pulse reset (0x8600 stays STOP)";
    }
}
else if (topic === "topic/RemoteStop2" || topic === "RemoteStop2") {
    const h2_cp = global.get("h2_cpState") || global.get("cp_state2") || flow.get("h2_cpState") || "state_b";
    const isPlugged = (h2_cp !== "state_a" && h2_cp !== "");

    frames.push(writeVP(0x4900, 0x00)); // H2 DWIN state = 0 (Stop)
    frames.push(writeVP(0x8600, 0x00)); // H2 Button = 0 (START icon immediately!)

    global.set("h2_remoteStarted", false);
    global.set("h2_remoteActive", false);
    flow.set("h2_remoteActive", false);
    global.set("h2_stopCommanded", true);
    flow.set("h2_stopCommanded", true);

    if (isPlugged) {
        // Plugged in: Remote stop immediately shows PLEASE UNPLUG (State 5)
        frames.push(writeVP(0x6200, applyLang(5, lang)));
        flow.set("h2_state", 5);
        global.set("h2_state", 5);
        flow.set("h2_finishing_val", 1);
        global.set("H2_Finishing", 1);
        label = "H2 RemoteStop -> Please Unplug (State 5)";
    } else {
        frames.push(writeVP(0x6200, applyLang(1, lang)));
        flow.set("h2_state", 1);
        global.set("h2_state", 1);
        flow.set("h2_finishing_val", 0);
        global.set("H2_Finishing", 0);
        label = "H2 RemoteStop -> Idle (State 1)";
    }
}

if (!frames.length) return null;

msg.payload = Buffer.concat(frames);
node.status({
    fill: label.includes("STOP") || label.includes("Unplug") ? "orange" : "green",
    shape: "dot",
    text: label
});

return msg;

// On startup: Ensure H1 state = 0 AND sync 0x8700 / 0x8800 with admin_login_required
const req = global.get("admin_login_required") ?? false;
const f1 = Buffer.from([0x5A, 0xA5, 0x05, 0x82, 0x48, 0x00, 0x00, 0x00]);
