    frames.push(Buffer.from([0x5A, 0xA5, 0x05, 0x82, 0x88, 0x00, 0x00, 0x00])); // 0x8800 = 0
} else {
    frames.push(Buffer.from([0x5A, 0xA5, 0x05, 0x82, 0x87, 0x00, 0x00, 0x01])); // 0x8700 = 1
    frames.push(Buffer.from([0x5A, 0xA5, 0x05, 0x82, 0x88, 0x00, 0x00, 0x01])); // 0x8800 = 1
}

msg.payload = Buffer.concat(frames);
node.status({ fill: "green", shape: "dot", text: req ? "Init: PIN REQUIRED (0x8700=0, 0x8800=0)" : "Init: NO LOGIN (0x8700=1, 0x8800=1)" });
return msg;

msg.payload = Buffer.from([
    0x5A, 0xA5, 0x05, 0x82,
