// ==================== Remote State → DWIN (Latched STOP) ====================
// VP 0x4800 (H1 State), VP 0x4900 (H2 State)
// VP 0x8500 (H1 Admin Btn: 0=START, 1=STOP)
// VP 0x8600 (H2 Admin Btn: 0=START, 1=STOP)

const topic = msg.topic;
const payload = msg.payload || {};

function writeVP(vp, val) {
    return Buffer.from([0x5A, 0xA5, 0x05, 0x82, (vp >> 8) & 0xFF, vp & 0xFF, 0x00, val & 0xFF]);
}

const frames = [];
let label = "";

// ===== H1 =====
if (topic === "topic/RemoteStart1") {
    if (payload.remote_start === 1) {
        frames.push(writeVP(0x4800, 0x0C)); // H1 DWIN state = 12 (Charging)
        frames.push(writeVP(0x8500, 0x01)); // H1 Admin Button = 1 (STOP Icon)
        flow.set("h1_remoteActive", true);
        label = "H1 RemoteStart=1 -> STOP button LATCHED (1)";
    } else if (payload.remote_start === 0) {
        frames.push(writeVP(0x4800, 0x00)); // H1 DWIN state reset
        // DO NOT reset 0x8500! Keeps STOP button active during session
        label = "H1 Start pulse reset (0x8500 stays STOP)";
    }
}
else if (topic === "topic/RemoteStop1") {
    frames.push(writeVP(0x4800, 0x00)); // H1 DWIN state = 0 (Stop)
    frames.push(writeVP(0x8500, 0x00)); // H1 Admin Button = 0 (START Icon)
    flow.set("h1_remoteActive", false);
    label = "H1 RemoteStop -> Button turns START (0)";
}

// ===== H2 =====
else if (topic === "topic/RemoteStart2") {
    if (payload.remote_start === 1) {
        frames.push(writeVP(0x4900, 0x0C)); // H2 DWIN state = 12 (Charging)
        frames.push(writeVP(0x8600, 0x01)); // H2 Admin Button = 1 (STOP Icon)
        flow.set("h2_remoteActive", true);
        label = "H2 RemoteStart=1 -> STOP button LATCHED (1)";
    } else if (payload.remote_start === 0) {
        frames.push(writeVP(0x4900, 0x00)); // H2 DWIN state reset
        // DO NOT reset 0x8600! Keeps STOP button active during session
        label = "H2 Start pulse reset (0x8600 stays STOP)";
    }
}
else if (topic === "topic/RemoteStop2") {
    frames.push(writeVP(0x4900, 0x00)); // H2 DWIN state = 0 (Stop)
    frames.push(writeVP(0x8600, 0x00)); // H2 Admin Button = 0 (START Icon)
    flow.set("h2_remoteActive", false);
    label = "H2 RemoteStop -> Button turns START (0)";
}

if (!frames.length) return null;

msg.payload = Buffer.concat(frames);
node.status({
    fill: label.includes("LATCHED") ? "green" : "grey",
    shape: "dot",
    text: label
});

return msg;

// ===== Realtime Admin Button Sync (0x8500 / 0x8600 / 0x8700 / 0x8800) =====
// VP 0x8500 (H1), VP 0x8600 (H2), VP 0x8700 (Admin Auth), VP 0x8800 (Active if REQUIRE_LOGIN is false)

function writeVP(vp, val) {
    return Buffer.from([0x5A, 0xA5, 0x05, 0x82, (vp >> 8) & 0xFF, vp & 0xFF, 0x00, val & 0xFF]);
}

// Read states from global (cross-tab) then flow context
const h1_state = global.get("h1_state") ?? flow.get("h1_state") ?? 1;
const h2_state = global.get("h2_state") ?? flow.get("h2_state") ?? 1;

const h1_cp = global.get("h1_cpState") || global.get("cp_state1") || flow.get("h1_cpState") || flow.get("CPStateCCS1") || "";
const h2_cp = global.get("h2_cpState") || global.get("cp_state2") || flow.get("h2_cpState") || flow.get("CPStateCCS2") || "";

const h1_isPlugged = (h1_cp === "state_b" || h1_cp === "state_c" || h1_cp === "state_d");
const h2_isPlugged = (h2_cp === "state_b" || h2_cp === "state_c" || h2_cp === "state_d");

const h1_flag = global.get("h1_remoteStarted") || global.get("h1_remoteActive") || flow.get("h1_remoteActive") || false;
const h2_flag = global.get("h2_remoteStarted") || global.get("h2_remoteActive") || flow.get("h2_remoteActive") || false;

const h1_pwr = Number(flow.get("h1_power") || global.get("h1_power") || 0);
const h2_pwr = Number(flow.get("h2_power") || global.get("h2_power") || 0);

const h1_cs = String(global.get("h1_cs_state") || flow.get("h1_cs_state") || "");
const h2_cs = String(global.get("h2_cs_state") || flow.get("h2_cs_state") || "");

const h1_stopReq = global.get("h1_stopCommanded") || false;
const h2_stopReq = global.get("h2_stopCommanded") || false;

const h1_stopping = (h1_state === 5 || h1_state === 4 || /SessionStop|WeldingDetection/.test(h1_cs) || h1_stopReq);
const h2_stopping = (h2_state === 5 || h2_state === 4 || /SessionStop|WeldingDetection/.test(h2_cs) || h2_stopReq);

// STOP (1) is active whenever:
// 1. Cable is plugged in (state_b, state_c, state_d)
// 2. Either remote start triggered (handshake/charging), state is 0 (charging), or delivering power > 0.5 kW
// 3. AND NOT stopped, finishing (state 5), or faulted (state 4)
const h1_active = h1_isPlugged && !h1_stopping && (h1_flag || (h1_state === 0 && h1_pwr > 0.5));
const h2_active = h2_isPlugged && !h2_stopping && (h2_flag || (h2_state === 0 && h2_pwr > 0.5));

const val1 = h1_active ? 1 : 0;
const val2 = h2_active ? 1 : 0;

const frames = [];

// 1. Manage Head 1 Button (0x8500: 0=START, 1=STOP)
frames.push(writeVP(0x8500, val1));

// 2. Manage Head 2 Button (0x8600: 0=START, 1=STOP)
frames.push(writeVP(0x8600, val2));

// 3. 🔓 Manage 0x8700 (Admin Auth) & 0x8800 (Active if REQUIRE_LOGIN is false):
const loginRequired = global.get("admin_login_required") ?? false;

if (loginRequired) {
    frames.push(writeVP(0x8700, flow.get("admin_auth") ? 1 : 0));
    frames.push(writeVP(0x8800, 0));
} else {
    frames.push(writeVP(0x8700, 1)); // Permanently Unlocked
    frames.push(writeVP(0x8800, 1)); // Active (1) when REQUIRE_LOGIN is false
}

msg.payload = Buffer.concat(frames);
node.status({
    fill: (val1 || val2) ? "green" : "grey",
    shape: "dot",
    text: `H1:${val1 ? "STOP" : "START"}(s${h1_state},${h1_cp}) | H2:${val2 ? "STOP" : "START"}(s${h2_state},${h2_cp}) | 0x8700:1 | 0x8800:${loginRequired ? 0 : 1}`
});

return msg;

// ==================== Admin Numpad (login optional) ====================
// VP 0x8700:  0 = Locked / logged out    1 = Unlocked / logged in
// VP 0x8800:  1 = Active when REQUIRE_LOGIN is false (Bypass mode)
//
// ┌──────────────────────── SETTINGS ────────────────────────┐
// Change auth mode directly here in code (no injector needed):
const REQUIRE_LOGIN = false; // <-- false = NO LOGIN (Bypass) | true = PIN required
const ADMIN_PASSWORD = "0000"; // <-- PLACEHOLDER (public copy): set your own PIN, digits 0-9 only, before deploying
const AUTH_TIMEOUT_MINUTES = 5; // <-- session AND PIN-entry timeout
// └──────────────────────────────────────────────────────────┘

// Always keep global and flow context synchronized with this code configuration
global.set("admin_login_required", REQUIRE_LOGIN);
flow.set("admin_login_required", REQUIRE_LOGIN);

function lockFrame() {
    return Buffer.concat([
        Buffer.from([0x5A, 0xA5, 0x05, 0x82, 0x87, 0x00, 0x00, 0x00]), // 0x8700 = 0
        Buffer.from([0x5A, 0xA5, 0x05, 0x82, 0x88, 0x00, 0x00, 0x00])  // 0x8800 = 0
    ]);
}

function unlockFrame() {
    const frames = [
        Buffer.from([0x5A, 0xA5, 0x05, 0x82, 0x87, 0x00, 0x00, 0x01])  // 0x8700 = 1
    ];
    if (!REQUIRE_LOGIN) {
        frames.push(Buffer.from([0x5A, 0xA5, 0x05, 0x82, 0x88, 0x00, 0x00, 0x01])); // 0x8800 = 1
    } else {
        frames.push(Buffer.from([0x5A, 0xA5, 0x05, 0x82, 0x88, 0x00, 0x00, 0x00])); // 0x8800 = 0
    }
    return Buffer.concat(frames);
}

function clearAdminTimers() {
    const t1 = context.get("authTimer");
    const t2 = context.get("pwdTimer");
    if (t1) clearTimeout(t1);
    if (t2) clearTimeout(t2);
    context.set("authTimer", null);
    context.set("pwdTimer", null);
}

const isKeypress = msg && msg.payload && typeof msg.payload === "object" && msg.payload.vp_raw !== undefined;

// ---------- MODE B: no login required -> permanently unlocked ----------
if (!REQUIRE_LOGIN) {
    clearAdminTimers();
    flow.set("admin_auth", true);
    global.set("admin_auth", true);
    flow.set("admin_session", true);

    node.status({ fill: "green", shape: "dot", text: "Auth: NO LOGIN (0x8700=1, 0x8800=1)" });

    if (!isKeypress || context.get("lastLock") !== 1) {
        context.set("lastLock", 1);
        msg.payload = unlockFrame();
        return msg;
    }
    return null;
}

// ---------- MODE A: PIN login required --------------------------------
if (context.get("lastLock") !== 0 && !context.get("authTimer")) {
    context.set("lastLock", 0);
    flow.set("admin_auth", false);
    global.set("admin_auth", false);
    flow.set("admin_session", false);
    flow.set("pwd_seq", []);
    node.status({ fill: "yellow", shape: "ring", text: "Auth: PIN REQUIRED (0x8700=0, 0x8800=0)" });
    if (!isKeypress) {
        msg.payload = lockFrame();
        return msg;
    }
}

if (!isKeypress) return null;

const PIN_ENTRY_TIMEOUT_SECONDS = AUTH_TIMEOUT_MINUTES * 60;

const VP_ADMIN_BTN = 0x3200;   // Admin mode button
const VP_LOGIN = 0x3300;       // Login / submit
const VP_LOGOUT = 0x3400;      // Logout
const VP_CLEAR_1 = 0x7700;     // Clear PIN
const VP_CLEAR_2 = 0x3450;     // Clear PIN (2nd button)

const VP_PWD_1 = 0x3500, VP_PWD_2 = 0x3600, VP_PWD_3 = 0x3700, VP_PWD_4 = 0x7000, VP_PWD_5 = 0x7100;
const VP_PWD_6 = 0x7200, VP_PWD_7 = 0x7300, VP_PWD_8 = 0x7400, VP_PWD_9 = 0x7500, VP_PWD_0 = 0x7600;

const ALL_PWD_KEYS = [VP_PWD_1, VP_PWD_2, VP_PWD_3, VP_PWD_4, VP_PWD_5,
    VP_PWD_6, VP_PWD_7, VP_PWD_8, VP_PWD_9, VP_PWD_0];
const DIGIT_VP = {
    "0": VP_PWD_0, "1": VP_PWD_1, "2": VP_PWD_2, "3": VP_PWD_3, "4": VP_PWD_4,
    "5": VP_PWD_5, "6": VP_PWD_6, "7": VP_PWD_7, "8": VP_PWD_8, "9": VP_PWD_9
};

const CORRECT_SEQ = String(ADMIN_PASSWORD).split("").map(function (d) { return DIGIT_VP[d]; });
if (!CORRECT_SEQ.length || CORRECT_SEQ.some(function (v) { return v === undefined; })) {
    node.status({ fill: "red", shape: "ring", text: "ADMIN_PASSWORD must be digits 0-9 only" });
    node.warn("Admin Numpad: ADMIN_PASSWORD '" + ADMIN_PASSWORD + "' is invalid - digits 0-9 only.");
    return null;
}

const VALID_VPS = [VP_ADMIN_BTN, VP_LOGIN, VP_LOGOUT, VP_CLEAR_1, VP_CLEAR_2].concat(ALL_PWD_KEYS);

const vp = msg.payload.vp_raw;
if (!VALID_VPS.includes(vp)) return null;

// ---- Logout ----
if (vp === VP_LOGOUT) {
    clearAdminTimers();
    context.set("lastLock", 0);
    flow.set("admin_auth", false); global.set("admin_auth", false);
    flow.set("admin_session", false);
    flow.set("pwd_seq", []);
    node.status({ fill: "grey", shape: "ring", text: "Logged out -> 0x8700 = 0, 0x8800 = 0" });
    msg.payload = lockFrame();
    return msg;
}

// ---- Admin button: start a PIN entry session ----
if (vp === VP_ADMIN_BTN) {
    clearAdminTimers();
    context.set("lastLock", 0);
    flow.set("admin_auth", false); global.set("admin_auth", false);
    flow.set("pwd_seq", []);
    flow.set("admin_session", true);
    node.status({ fill: "yellow", shape: "ring", text: "Admin mode: waiting for PIN..." });

    const pwdTimer = setTimeout(function () {
        flow.set("admin_session", false);
        flow.set("admin_auth", false); global.set("admin_auth", false);
        flow.set("pwd_seq", []);
        node.status({
            fill: "grey", shape: "ring",
            text: "PIN entry timeout (" + AUTH_TIMEOUT_MINUTES + " min) -> lock"
        });
        node.send({ payload: lockFrame() });
    }, PIN_ENTRY_TIMEOUT_SECONDS * 1000);
    context.set("pwdTimer", pwdTimer);
    return null;
}

// ---- everything below needs an open PIN session ----
if (!(flow.get("admin_session") || false)) return null;

// ---- Clear ----
if (vp === VP_CLEAR_1 || vp === VP_CLEAR_2) {
    flow.set("pwd_seq", []);
    node.status({ fill: "yellow", shape: "ring", text: "PIN cleared" });
    return null;
}

// ---- digit pressed ----
if (ALL_PWD_KEYS.includes(vp)) {
    const seq = flow.get("pwd_seq") || [];
    seq.push(vp);
    flow.set("pwd_seq", seq);
    node.status({
        fill: "yellow", shape: "dot",
        text: "PIN: " + seq.length + "/" + CORRECT_SEQ.length + " entered"
    });
    return null;
}

// ---- Login ----
if (vp === VP_LOGIN) {
    clearAdminTimers();
    const seq = flow.get("pwd_seq") || [];
    const ok = seq.length === CORRECT_SEQ.length &&
        seq.every(function (v, i) { return v === CORRECT_SEQ[i]; });

    if (ok) {
        context.set("lastLock", 1);
        flow.set("admin_auth", true); global.set("admin_auth", true);
        flow.set("admin_session", false);
        flow.set("pwd_seq", []);
        node.status({
            fill: "green", shape: "dot",
            text: "Login OK -> 0x8700 = 1 (" + AUTH_TIMEOUT_MINUTES + " min)"
        });

        const authTimer = setTimeout(function () {
            context.set("lastLock", 0);
            flow.set("admin_auth", false); global.set("admin_auth", false);
            node.status({ fill: "grey", shape: "ring", text: "Session expired -> lock" });
            node.send({ payload: lockFrame() });
        }, AUTH_TIMEOUT_MINUTES * 60 * 1000);
        context.set("authTimer", authTimer);

        msg.payload = unlockFrame();
        return msg;
    }

    context.set("lastLock", 0);
    flow.set("admin_auth", false); global.set("admin_auth", false);
    flow.set("admin_session", false);
    flow.set("pwd_seq", []);
    node.status({ fill: "red", shape: "dot", text: "Wrong PIN" });
    msg.payload = lockFrame();
    return msg;
}

return null;

// ==================== Parse DWIN Action1 V1 (Dedicated HEAD 1) ====================
// VP 0x8500: Dedicated for HEAD 1.
// Auth condition: Follows REQUIRE_LOGIN (if true, PIN login required; if false, no login needed).

if (!msg || !msg.payload) return null;

const vp = msg.payload.vp_raw;
const value = Number(msg.payload.value);

const VP_ACTION = 0x8500;
if (vp !== VP_ACTION) return null;

function applyLang(state, lang) {
    if (state >= 1 && state <= 6) {
        if (lang === 2) return state + 6;
        if (lang === 3) return state + 12;
    }
    return state;
}

const lang = flow.get("language_mode") || global.get("language_mode") || 1;
const dwinStartFrame = { payload: Buffer.from([0x5A, 0xA5, 0x05, 0x82, 0x85, 0x00, 0x00, 0x00]) };

const h1_cp = global.get("h1_cpState") || global.get("cp_state1") || flow.get("h1_cpState") || "state_a";
const isPlugged = (h1_cp === "state_b" || h1_cp === "state_c" || h1_cp === "state_d");

// 🛑 1. USER TOUCHED STOP (value === 0):
if (value === 0) {
    global.set("h1_remoteStarted", false);
    global.set("h1_remoteActive", false);
    flow.set("h1_remoteActive", false);
    global.set("h1_stopCommanded", true);
    flow.set("h1_stopCommanded", true);
    global.set("manualStop1", true);

    if (h1_cp === "state_a" || h1_cp === "state_e" || h1_cp === "state_f") {
        node.status({ fill: "grey", shape: "ring", text: "STOP touch แต่ไม่มีรถ (" + h1_cp + ") -> no-op" });
        return [null, null, dwinStartFrame];
    }

    if (isPlugged) {
        flow.set("h1_state", 5);
        global.set("h1_state", 5);
        flow.set("h1_finishing_val", 1);
        global.set("H1_Finishing", 1);
    }

    node.status({ fill: "orange", shape: "dot", text: "🛑 H1 STOP Touched -> remote_stop=1 + Please Unplug" });
    const stopMsg = { payload: { remote_stop: 1 } };

    // Emit 0x8500 = 0 (START) AND 0x6000 = 5 (Please Unplug)
    const outFrames = [
        Buffer.from([0x5A, 0xA5, 0x05, 0x82, 0x85, 0x00, 0x00, 0x00])
    ];
    if (isPlugged) {
        outFrames.push(Buffer.from([0x5A, 0xA5, 0x05, 0x82, 0x60, 0x00, 0x00, applyLang(5, lang)]));
    }
    const dwinStopFrame = { payload: Buffer.concat(outFrames) };

    // Output 1: null | Output 2: MQTT Stop | Output 3: DWIN write
    return [null, stopMsg, dwinStopFrame];
}

// ▶️ 2. USER TOUCHED START (value === 1):
if (value === 1) {
    if (!isPlugged) {
        global.set("h1_remoteStarted", false);
        global.set("h1_remoteActive", false);
        flow.set("h1_remoteActive", false);
        node.status({ fill: "yellow", shape: "ring", text: "❌ Cannot start: H1 unplugged (" + h1_cp + ")" });
        node.send([null, null, dwinStartFrame]);
        return null;
    }

    const loginRequired = global.get("admin_login_required") ?? false;
    const adminAuth = flow.get("admin_auth") || global.get("admin_auth") || false;

    if (loginRequired && !adminAuth) {
        global.set("h1_remoteStarted", false);
        global.set("h1_remoteActive", false);
        flow.set("h1_remoteActive", false);
        node.status({ fill: "red", shape: "ring", text: "🔒 Auth required: PIN login needed to start H1" });
        node.send([null, null, dwinStartFrame]);
        return null;
    }

    global.set("h1_remoteStarted", true);
    global.set("h1_remoteActive", true);
    flow.set("h1_remoteActive", true);
    global.set("h1_stopCommanded", false);
    flow.set("h1_stopCommanded", false);
    global.set("manualStop1", false);
    flow.set("h1_finishing_val", 0);
    global.set("H1_Finishing", 0);
    flow.set("selectedHead", "h1");

    node.status({
        fill: "green",
        shape: "dot",
        text: "▶️ H1 START Touched (" + (loginRequired ? "Authenticated" : "No Auth Needed") + ") -> STARTING"
    });

    const startMsg = { payload: { remote_start: 1 } };
    const dwinStopFrame = { payload: Buffer.from([0x5A, 0xA5, 0x05, 0x82, 0x85, 0x00, 0x00, 0x01]) };

    node.send([startMsg, null, dwinStopFrame]);

    setTimeout(function () {
        node.send([{ payload: { remote_start: 0 } }, null, null]);
    }, 5000);

    return null;
}

return null;

// ==================== Parse DWIN Action2 (Dedicated HEAD 2) ====================
// VP 0x8600: Dedicated for HEAD 2.
// Auth condition: Follows REQUIRE_LOGIN (if true, PIN login required; if false, no login needed).

if (!msg || !msg.payload) return null;

const vp = msg.payload.vp_raw;
const value = Number(msg.payload.value);

const VP_ACTION = 0x8600;
if (vp !== VP_ACTION) return null;

function applyLang(state, lang) {
    if (state >= 1 && state <= 6) {
        if (lang === 2) return state + 6;
        if (lang === 3) return state + 12;
    }
    return state;
}

const lang = flow.get("language_mode") || global.get("language_mode") || 1;
const dwinStartFrame = { payload: Buffer.from([0x5A, 0xA5, 0x05, 0x82, 0x86, 0x00, 0x00, 0x00]) };

const h2_cp = global.get("h2_cpState") || global.get("cp_state2") || flow.get("h2_cpState") || "state_a";
const isPlugged = (h2_cp === "state_b" || h2_cp === "state_c" || h2_cp === "state_d");

// 🛑 1. USER TOUCHED STOP (value === 0):
if (value === 0) {
    global.set("h2_remoteStarted", false);
    global.set("h2_remoteActive", false);
    flow.set("h2_remoteActive", false);
    global.set("h2_stopCommanded", true);
    flow.set("h2_stopCommanded", true);
    global.set("manualStop2", true);

    if (h2_cp === "state_a" || h2_cp === "state_e" || h2_cp === "state_f") {
        node.status({ fill: "grey", shape: "ring", text: "STOP touch แต่ไม่มีรถ (" + h2_cp + ") -> no-op" });
        return [null, null, dwinStartFrame];
    }

    if (isPlugged) {
        flow.set("h2_state", 5);
        global.set("h2_state", 5);
        flow.set("h2_finishing_val", 1);
        global.set("H2_Finishing", 1);
    }

    node.status({ fill: "orange", shape: "dot", text: "🛑 H2 STOP Touched -> remote_stop=1 + Please Unplug" });
    const stopMsg = { topic: "topic/RemoteStop2", payload: { remote_stop: 1 } };

    // Emit 0x8600 = 0 (START) AND 0x6200 = 5 (Please Unplug)
    const outFrames = [
        Buffer.from([0x5A, 0xA5, 0x05, 0x82, 0x86, 0x00, 0x00, 0x00])
    ];
    if (isPlugged) {
        outFrames.push(Buffer.from([0x5A, 0xA5, 0x05, 0x82, 0x62, 0x00, 0x00, applyLang(5, lang)]));
    }
    const dwinStopFrame = { payload: Buffer.concat(outFrames) };

    // Output 1: null | Output 2: MQTT Stop | Output 3: DWIN write
    return [null, stopMsg, dwinStopFrame];
}

// ▶️ 2. USER TOUCHED START (value === 1):
if (value === 1) {
    if (!isPlugged) {
        global.set("h2_remoteStarted", false);
        global.set("h2_remoteActive", false);
        flow.set("h2_remoteActive", false);
        node.status({ fill: "yellow", shape: "ring", text: "❌ Cannot start: H2 unplugged (" + h2_cp + ")" });
        node.send([null, null, dwinStartFrame]);
        return null;
    }

    const loginRequired = global.get("admin_login_required") ?? false;
    const adminAuth = flow.get("admin_auth") || global.get("admin_auth") || false;

    if (loginRequired && !adminAuth) {
        global.set("h2_remoteStarted", false);
        global.set("h2_remoteActive", false);
        flow.set("h2_remoteActive", false);
        node.status({ fill: "red", shape: "ring", text: "🔒 Auth required: PIN login needed to start H2" });
        node.send([null, null, dwinStartFrame]);
        return null;
    }

    global.set("h2_remoteStarted", true);
    global.set("h2_remoteActive", true);
    flow.set("h2_remoteActive", true);
    global.set("h2_stopCommanded", false);
    flow.set("h2_stopCommanded", false);
    global.set("manualStop2", false);
    flow.set("h2_finishing_val", 0);
    global.set("H2_Finishing", 0);
    flow.set("selectedHead", "h2");

    node.status({
        fill: "green",
        shape: "dot",
        text: "▶️ H2 START Touched (" + (loginRequired ? "Authenticated" : "No Auth Needed") + ") -> STARTING"
    });

    const startMsg = { topic: "topic/RemoteStart2", payload: { remote_start: 1 } };
    const dwinStopFrame = { payload: Buffer.from([0x5A, 0xA5, 0x05, 0x82, 0x86, 0x00, 0x00, 0x01]) };

    node.send([startMsg, null, dwinStopFrame]);

    setTimeout(function () {
        node.send([{ topic: "topic/RemoteStart2", payload: { remote_start: 0 } }, null, null]);
    }, 5000);

    return null;
}

return null;

// ===== FIX#HMIFLAGS rev1 (09 พ.ย. 2026): เคลียร์ธงปุ่ม START/STOP ของจอเมื่อถอดสาย =====
// บั๊กเดิม: Parse DWIN Action / Remote -> DWIN State ตั้ง global.h{n}_remoteActive และ flow.h{n}_remoteActive (tab นี้)
//   แต่ไม่มีใครเคลียร์ตอนถอดสาย (HEAD{n} ใน HMI_flow เคลียร์แค่ global.h{n}_remoteStarted กับ flow ของ tab ตัวเอง)
//   -> ถ้า session ก่อนหน้าจบโดยรถ/CSMS/E-stop (ไม่ได้กด STOP บนจอ) ธงค้าง true
//   -> เสียบสายรอบใหม่ "Realtime Admin Button Sync" เห็น h{n}_flag=true -> ปุ่มบนจอกลายเป็น STOP แทน START
//   -> ผู้ใช้กด = สั่งหยุด (remote_stop + Please Unplug) -> "ชาร์จไม่ได้"  (อาการหัว 1 วันที่ 09/11)
// โหนดนี้อยู่ใน tab RFID Routing เพื่อให้ flow.set() ตรงกับ flow context ที่ Parse DWIN Action / Realtime Sync ใช้
const topic = String(msg.topic || "");
const m = topic.match(/connector\/(\d)\//);
if (!m) return null;
const n = m[1];
const cp = String(msg.payload || "").trim();
if (cp !== "state_a" && cp !== "state_e" && cp !== "state_f") {
    node.status({ fill: "green", shape: "dot", text: "H" + n + " " + cp });
    return null;
}
const was = {
    remoteStarted: global.get("h" + n + "_remoteStarted") === true,
    remoteActiveG: global.get("h" + n + "_remoteActive") === true,
    remoteActiveF: flow.get("h" + n + "_remoteActive") === true,
    stopCommanded: global.get("h" + n + "_stopCommanded") === true || flow.get("h" + n + "_stopCommanded") === true
};
global.set("h" + n + "_remoteStarted", false);
global.set("h" + n + "_remoteActive", false);
flow.set("h" + n + "_remoteActive", false);
global.set("h" + n + "_stopCommanded", false);
flow.set("h" + n + "_stopCommanded", false);
if (was.remoteStarted || was.remoteActiveG || was.remoteActiveF || was.stopCommanded) {
    node.warn("H" + n + ": FIX#HMIFLAGS ถอดสาย (" + cp + ") -> เคลียร์ธงจอ " + JSON.stringify(was) + " (ปุ่มกลับเป็น START)");
}
node.status({ fill: "blue", shape: "ring", text: "H" + n + " " + cp + " -> flags cleared" });
return null;
